insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_mm','["Hm. Comfy chair. I’ll stay till {partner}’s back. Haven’t said hi yet.","Hm. Mabel says don’t leave before greeting everyone. So. Waiting for {partner}."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('MM-V01','adventure_friend_mm','Trivia','{"id":"MM-V01","friendId":"adventure_friend_mm","type":"Trivia","scene":"Mr Mole slides a blurry photo across the table. It''s a nose. A very weird nose.","lines":["Hm. My cousin. Don''t stare. Okay, stare a little."],"question":"The star-nosed mole holds a world record. For what?","selfQuestion":null,"choices":[{"id":"A","label":"Fastest eater of any mammal","reply":["Hm. Correct. Blink and lunch is over.","His 22 nose tentacles find and gulp food in about a quarter second.","Mabel calls him ''the vacuum.'' Not to his face."]},{"id":"B","label":"Loudest sneeze","reply":["Hm. With that nose? Fair guess.","It''s actually the fastest-eating mammal. Snack gone in about a quarter second.","Those 22 nose tentacles move faster than you can blink."]},{"id":"C","label":"Longest nap","reply":["Hm. That''s my record, not his.","He''s the fastest eater of any mammal. A bite takes about a quarter second.","Family dinners are short. Very short."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"The star-nosed mole is the fastest-eating mammal (~1/4 second per item); its star has 22 appendages.","coupleReplies":{}}'::jsonb),
('MM-V02','adventure_friend_mm','Trivia','{"id":"MM-V02","friendId":"adventure_friend_mm","type":"Trivia","scene":"Mr Mole sniffs the air by your open window, very slowly, eyes closed.","lines":["Hm. Rain''s coming. I can smell it. So can you, probably."],"question":"That lovely ''smell of rain'' on dry ground mostly comes from what?","selfQuestion":null,"choices":[{"id":"A","label":"Clouds rubbing together","reply":["Hm. Clouds don''t rub. They hover.","It''s mostly geosmin, made by soil bacteria, launched up by raindrops.","We can smell tiny amounts of it. Built-in rain alarm."]},{"id":"B","label":"Worms celebrating","reply":["Hm. They do celebrate. Not the smell, though.","It''s geosmin from soil bacteria, tossed into the air by raindrops.","That earthy smell even has a name: petrichor."]},{"id":"C","label":"Soil bacteria releasing a compound called geosmin","reply":["Hm. Correct. Bacteria. Romantic, isn''t it.","Rain kicks geosmin into the air, and human noses are incredibly sensitive to it.","The smell even has a name: petrichor. Mabel''s favorite word."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Petrichor''s earthy note is largely geosmin from soil microbes; humans detect it at very low concentrations.","coupleReplies":{}}'::jsonb),
('MM-V03','adventure_friend_mm','Trivia','{"id":"MM-V03","friendId":"adventure_friend_mm","type":"Trivia","scene":"A worm pokes out of your plant pot. Mr Mole tips his hat to it.","lines":["Hm. Respect the worm. It has more heart than you."],"question":"How many heart-like pumps does an earthworm have?","selfQuestion":null,"choices":[{"id":"A","label":"One, like everybody else","reply":["Hm. Reasonable. Also wrong.","Earthworms have five heart-like arches pumping blood.","Five hearts and still no drama. Admirable."]},{"id":"B","label":"Five","reply":["Hm. Correct. Five little pumps.","They''re called aortic arches, wrapped around the front of the worm.","Five hearts. Still can''t say ''I love you.'' Relatable."]},{"id":"C","label":"Zero. Cold-hearted","reply":["Hm. Harsh on my coworker.","They''ve got five heart-like pumps. More than any of us.","Lots of heart. Very little brain. Honestly, peaceful."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Earthworms have five pairs of aortic arches, often called ''hearts''.","coupleReplies":{}}'::jsonb),
('MM-V04','adventure_friend_mm','Trivia','{"id":"MM-V04","friendId":"adventure_friend_mm","type":"Trivia","scene":"Mr Mole taps the ground with his paw and listens, impressed.","lines":["Hm. Biggest living thing I know of. It''s underground. Of course."],"question":"One of the largest living organisms on Earth is a...?","selfQuestion":null,"choices":[{"id":"A","label":"Blue whale","reply":["Hm. Big. Not biggest by area.","A honey fungus in Oregon spreads underground across about 2,000+ acres.","Mostly hidden threads in the soil. Very mole of it."]},{"id":"B","label":"Giant honey fungus underground in Oregon","reply":["Hm. Correct. A mushroom the size of a town.","Its threads spread across roughly 2,000+ acres of forest soil.","Possibly thousands of years old. Quiet achiever. My hero."]},{"id":"C","label":"Giant sequoia tree","reply":["Hm. Tall. Impressive. Not the winner by area.","A honey fungus in Oregon covers about 2,000+ acres underground.","You walk over it and never know. Like most good things."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"An Armillaria ostoyae individual in Oregon''s Malheur National Forest spans ~2,385 acres.","coupleReplies":{}}'::jsonb),
('MM-V05','adventure_friend_mm','Trivia','{"id":"MM-V05","friendId":"adventure_friend_mm","type":"Trivia","scene":"Mr Mole presses one ear to the ground, listening to something you can''t hear.","lines":["Hm. The trees are gossiping again."],"question":"Underground, many trees are linked together by what?","selfQuestion":null,"choices":[{"id":"A","label":"Fungus threads that share nutrients","reply":["Hm. Correct. Fungus is the real networker.","Fungal threads wrap roots and help move water and nutrients between trees.","Nicknamed the wood wide web. No password needed."]},{"id":"B","label":"Secret tunnels dug by moles","reply":["Hm. I wish I got the credit.","It''s fungi. Their threads link roots and pass nutrients around.","People call it the ''wood wide web.'' Trees with a group chat."]},{"id":"C","label":"Root Wi-Fi with actual bars","reply":["Hm. Close, honestly. Still wrong.","It''s fungus threads linking roots, nicknamed the wood wide web.","No signal bars. Just mushrooms doing logistics."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Mycorrhizal fungal networks connect tree roots and move nutrients (''wood wide web'').","coupleReplies":{}}'::jsonb),
('MM-V06','adventure_friend_mm','Trivia','{"id":"MM-V06","friendId":"adventure_friend_mm","type":"Trivia","scene":"Mr Mole opens his lunchbox. Something inside wiggles. He closes it very calmly.","lines":["Hm. Don''t worry about it. Actually, quiz about it."],"question":"Some moles keep a pantry of live earthworms. How do they stop them escaping?","selfQuestion":null,"choices":[{"id":"A","label":"A tiny fridge","reply":["Hm. No outlets down here. Sadly.","They bite the worm''s head so it''s paralyzed but still fresh.","Hundreds stored at once. A pantry with a pulse."]},{"id":"B","label":"Asking them nicely to stay","reply":["Hm. Worms don''t respect manners.","Moles bite the head to paralyze them, so they keep for later.","The original meal prep. No containers, no dishes."]},{"id":"C","label":"A bite that paralyzes them","reply":["Hm. Correct. Grim, but efficient.","A bite to the head means the worm stays alive but can''t crawl off.","Some larders hold hundreds. Meal prep king."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Moles bite earthworms'' heads to immobilize them and store them alive in larders.","coupleReplies":{}}'::jsonb),
('MM-V07','adventure_friend_mm','Trivia','{"id":"MM-V07","friendId":"adventure_friend_mm","type":"Trivia","scene":"Mr Mole sets down a photo of a little seabird with an orange beak.","lines":["Hm. Fellow tunnel person. Different neighborhood."],"question":"What''s special about where Atlantic puffins nest?","selfQuestion":null,"choices":[{"id":"A","label":"They nest on floating ice","reply":["Hm. Cold. No.","They dig burrows in cliffs and often reuse them with the same partner.","Seabirds with tunnels. Respect."]},{"id":"B","label":"They borrow other birds'' nests every year","reply":["Hm. Rude. No.","Puffins dig their own burrows, often returning to the same one with the same mate.","Commitment, with a front door."]},{"id":"C","label":"They dig burrows and often return to the same one with the same mate","reply":["Hm. Correct. Same burrow. Same partner. Year after year.","Puffins dig underground nests on cliff tops.","Mabel and I approve. Strongly."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Atlantic puffins nest in burrows and often reuse them with the same mate across years.","coupleReplies":{}}'::jsonb),
('MM-V08','adventure_friend_mm','Trivia','{"id":"MM-V08","friendId":"adventure_friend_mm","type":"Trivia","scene":"Mr Mole sits beside you on the couch. Not too close. Then a little closer.","lines":["Hm. Mabel and I sit like this. Science says something about it."],"question":"When romantic partners sit close together, what can happen to their bodies?","selfQuestion":null,"choices":[{"id":"A","label":"They both get hungry at the same moment","reply":["Hm. That''s just dinnertime.","Studies found partners'' breathing and heart rhythms can sync up.","Bodies in step. No talking required. My favorite kind of communication."]},{"id":"B","label":"Their breathing and heart rhythms can start to sync","reply":["Hm. Correct. Studies found couples'' heart rhythms and breathing can sync up.","Being near your person literally tunes your body to them.","Twenty years. Mabel and I probably hum in harmony now."]},{"id":"C","label":"Nothing. Bodies don''t care","reply":["Hm. Bodies care more than mouths do.","Partners'' heart rhythms and breathing can sync when they''re together.","Love is a quiet duet. Hm."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Studies (e.g., UC Davis 2012) observed physiological synchrony (breathing, heart rate) between romantic partners.","coupleReplies":{}}'::jsonb),
('MM-V09','adventure_friend_mm','Trivia','{"id":"MM-V09","friendId":"adventure_friend_mm","type":"Trivia","scene":"Mr Mole pulls a purple carrot out of the soil and holds it up.","lines":["Hm. Not dyed. Not broken. Original."],"question":"What color were most cultivated carrots before orange became popular?","selfQuestion":null,"choices":[{"id":"A","label":"Purple or yellow","reply":["Hm. Correct. Purple and yellow carrots came first.","Orange carrots became widespread later, especially through Dutch growers.","Mabel says purple ones taste fancier. She''s right. Don''t tell her."]},{"id":"B","label":"Bright blue","reply":["Hm. Blue food makes me nervous.","Early carrots were mostly purple or yellow.","Orange took over later. Carrots had a rebrand."]},{"id":"C","label":"Always orange","reply":["Hm. History disagrees.","Early cultivated carrots were mostly purple or yellow.","Orange became popular later. Even vegetables have eras."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Early domesticated carrots were mainly purple and yellow; orange cultivars were popularized in the 17th-century Netherlands.","coupleReplies":{}}'::jsonb),
('MM-V10','adventure_friend_mm','Trivia','{"id":"MM-V10","friendId":"adventure_friend_mm","type":"Trivia","scene":"Mr Mole points at a beach photo, then at a tiny drawing of a turtle hatchling.","lines":["Hm. Long trip home. Very long."],"question":"Where do many female sea turtles return to lay their eggs?","selfQuestion":null,"choices":[{"id":"A","label":"Whichever beach has the best snacks","reply":["Hm. Practical. Not it.","Many return to the beach region where they hatched, decades later.","Magnetic navigation. No maps. Very impressive."]},{"id":"B","label":"The same beach region where they hatched","reply":["Hm. Correct. Decades later. Same beach.","They likely navigate using Earth''s magnetic field.","Coming home after a long time away. Mabel cried at this one."]},{"id":"C","label":"A different ocean every time","reply":["Hm. Too much travel.","Many return to the region where they hatched.","Sometimes decades later. That''s commitment to a place."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Many sea turtles show natal homing, likely using geomagnetic cues.","coupleReplies":{}}'::jsonb),
('MM-V11','adventure_friend_mm','Preference','{"id":"MM-V11","friendId":"adventure_friend_mm","type":"Preference","scene":"Mr Mole fiddles with a small trowel, avoiding eye contact.","lines":["Hm. Personal question. Don''t make it weird."],"question":"Saying ''I love you'': out loud, or through actions?","selfQuestion":null,"choices":[{"id":"A","label":"Out loud","reply":["Hm. Out loud. Brave.","I said it once in 2006. Mabel wrote down the date."]},{"id":"B","label":"Through actions","reply":["Hm. Actions. My people.","Twenty years. Twenty windows. Zero speeches."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both say it out loud. Hm. Loud house.","{partner} says it, you say it back. Very efficient.","Mabel would cry. Happy crying."],"A:B":["Actions for you. {partner} likes hearing it out loud.","Hm. Mabel''s the same. I learned to say it on Sundays.","Fix the shelf, then say the words. Double points."],"B:A":["You say it out loud. {partner} shows it instead.","So when they refill your water without asking? That''s a whole love letter.","Read the actions. Say the words. Balanced."],"B:B":["Both of you, actions over words. Hm. Respect.","Your home must be full of fixed hinges and warm tea.","Still. Say it to {partner} once a year. For safety."]}}'::jsonb),
('MM-V12','adventure_friend_mm','Preference','{"id":"MM-V12","friendId":"adventure_friend_mm","type":"Preference","scene":"Mr Mole taps a wobbly shelf on your wall. It wobbles more.","lines":["Hm. Who built this. Never mind."],"question":"Home repair day: DIY it together, or hire a pro?","selfQuestion":null,"choices":[{"id":"A","label":"DIY it together","reply":["Hm. DIY. You, a toolbox, and hope.","I dug every window myself. Mabel only cried twice."]},{"id":"B","label":"Hire a pro","reply":["Hm. Hire a pro. Wise.","Fewer fights about which way the screw turns."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Both pick DIY. Hm. Bold.","Buy extra screws. And extra patience for {partner}.","Crooked shelves hold the best memories."],"A:B":["You''d hire a pro. {partner} wants to grab the drill.","Hm. Let them try. Keep the pro''s number on the fridge.","Mabel calls this ''supervising.'' I call it love."],"B:A":["You want to DIY. {partner} wants to call someone.","Hm. Classic standoff. Try one small shelf first.","If it wobbles, call the pro. No shame."],"B:B":["You both hire a pro. Hm. Peaceful household.","No ''you''re holding it wrong'' fights with {partner}. Ever.","Spend the saved energy on snacks."]}}'::jsonb),
('MM-V13','adventure_friend_mm','Preference','{"id":"MM-V13","friendId":"adventure_friend_mm","type":"Preference","scene":"Mr Mole squints at your window and measures it with his paw.","lines":["Hm. I dig windows. Professionally. Romantically."],"question":"Dream window view: a garden, the night sky, or a rainy street?","selfQuestion":null,"choices":[{"id":"A","label":"A garden","reply":["Hm. A garden. Classic.","Mabel''s first window faced her tomatoes. She talks to them daily."]},{"id":"B","label":"The night sky","reply":["Hm. Night sky. Romantic.","Hard to dig toward. Worth it."]},{"id":"C","label":"A rainy street","reply":["Hm. Rainy street. Moody.","Good for sitting. Good for not talking."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["A garden for both of you. Hm. Easy.","Grow tomatoes with {partner}. Name them. Mabel did.","Don''t get attached. They become sauce."],"A:B":["Night sky for you. {partner} picked the garden.","Hm. Plant flowers that bloom at night. Moonflowers exist.","Garden for them. Stars for you. One window."],"A:C":["Rainy street for you. {partner} wants a garden.","Hm. Rainy garden. Both happy. Worms happiest.","My coworkers thank you both."],"B:A":["You want a garden. {partner} wants the night sky.","Hm. Easy fix. Garden window by day, roof window by night.","I dug Mabel both. It took two anniversaries."],"B:B":["Both pick the night sky. Hm. Stargazers.","Put the bed under it. Fall asleep counting stars with {partner}.","Mabel counts stars. I count Mabel. Hm. Too much?"],"B:C":["You love rain. {partner} loves stars.","Hm. Get one big window. Let the sky pick the mood.","Rain one night, stars the next. Nobody loses."],"C:A":["Garden for you, rainy street for {partner}.","Hm. Rain waters the garden. Same team, technically.","Watch it rain on the flowers together."],"C:B":["You want stars. {partner} wants rain.","Hm. Unlucky. Clouds block stars. Weather picks favorites.","Rainy nights for {partner}, clear nights for you. Shared custody."],"C:C":["Rainy street for both. Hm. Cozy weirdos.","Tea, blanket, rain sounds, {partner}. No talking needed.","Best date. Zero effort. My kind."]}}'::jsonb),
('MM-V14','adventure_friend_mm','Preference','{"id":"MM-V14","friendId":"adventure_friend_mm","type":"Preference","scene":"Mr Mole sets two bowls of stew on your table and sits. Silently.","lines":["Hm. ...Hm."],"question":"Dinner for two: comfy silence, or nonstop chatting?","selfQuestion":null,"choices":[{"id":"A","label":"Comfy silence","reply":["Hm. Silence. My love language.","Mabel and I once didn''t talk for an entire stew. Best dinner."]},{"id":"B","label":"Nonstop chatting","reply":["Hm. Chatting. Lively.","Mabel tells stories. I nod. It''s a system."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Both pick comfy silence. Hm. Rare skill.","Some couples need to talk. You and {partner} just pass the salt.","That''s peak comfort. Trust me."],"A:B":["You want to chat. {partner} wants quiet.","Hm. Talk through the main course. Silence for dessert.","Pudding should be eaten in peace anyway."],"B:A":["You like quiet. {partner} likes to chat.","Hm. Be the nodder. It''s a respected position.","Toss in ''really?'' every few minutes. Works for me."],"B:B":["Both pick nonstop chatting. Hm. Loud table.","Hm. you and {partner} never finish soup while it''s hot, do you.","Microwave it. Keep talking."]}}'::jsonb),
('MM-V15','adventure_friend_mm','Preference','{"id":"MM-V15","friendId":"adventure_friend_mm","type":"Preference","scene":"Mr Mole pulls out a tiny calendar with one date circled. Hard.","lines":["Hm. Anniversary talk. My specialty. Quietly."],"question":"Anniversaries: a big celebration, or the same quiet tradition every year?","selfQuestion":null,"choices":[{"id":"A","label":"A big celebration","reply":["Hm. Big. Balloons. Noise.","I''d hide under the table. But good for you."]},{"id":"B","label":"A quiet tradition","reply":["Hm. Same tradition every year. Correct answer.","Twenty years. Twenty windows. Never once boring."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Both want big celebrations. Hm. Party couple.","Invite everyone. Make {partner} give a speech.","I would leave early. You won''t."],"A:B":["You love a quiet tradition. {partner} wants it big.","Hm. Let them throw the party. You sneak in the ritual.","A toast for two, mid-party. Mabel likes that."],"B:A":["You want a big party. {partner} wants the quiet tradition.","Hm. Do the tradition at sunrise. Party at night.","Two celebrations. Twice the cake."],"B:B":["You both want a quiet tradition. Hm. Perfect.","Same spot, same meal with {partner}, every year. That''s a love story.","Mabel calls ours ''window day.'' Find yours."]}}'::jsonb),
('MM-V16','adventure_friend_mm','Guess','{"id":"MM-V16","friendId":"adventure_friend_mm","type":"Guess","scene":"Mr Mole kneels by your sink, listening to a drip with deep concern.","lines":["Hm. That drip. It''s mocking us."],"question":"When something breaks at home, what does your partner do?","selfQuestion":"When something breaks at home, what do you do?","choices":[{"id":"A","label":"Fixes it (eventually)","reply":["Hm. ''Eventually.'' Love that word.","My gutter''s been ''almost fixed'' since spring."]},{"id":"B","label":"Calls for help right away","reply":["Hm. Calls for help. Efficient.","Nothing wrong with knowing your limits."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You fix it yourself, and {partner} knew it. Hm.","They''ve watched you mutter at a broken drawer before.","''Eventually'' is a valid timeline."],"A:B":["You''d call for help. {partner} pictured you with a wrench.","Hm. They believe in you more than your skills do.","Call the pro. Keep the wrench as decoration."],"B:A":["You''d fix it yourself. {partner} thought you''d call someone.","Hm. Underestimated. Go get the toolbox.","Let them watch. Quietly impressed is a love language."],"B:B":["Help on speed dial, and {partner} called it. Hm.","No pretending to understand pipes. Healthy.","Mole wisdom: wet floors don''t care about pride."]}}'::jsonb),
('MM-V17','adventure_friend_mm','Guess','{"id":"MM-V17","friendId":"adventure_friend_mm","type":"Guess","scene":"Mr Mole quietly slides the last cookie toward you, then looks away.","lines":["Hm. That wasn''t anything. Moving on."],"question":"Which tiny thing does your partner do that secretly means ''I love you''?","selfQuestion":"Which tiny thing do you do that secretly means ''I love you''?","choices":[{"id":"A","label":"Saves the last bite","reply":["Hm. The last bite. Real sacrifice.","Mabel gives me hers. I pretend I didn''t notice. I noticed."]},{"id":"B","label":"Warms up the bed first","reply":["Hm. Bed warming. Underrated.","Cold sheets are a crime. They''re a hero."]},{"id":"C","label":"Texts ''home safe?''","reply":["Hm. ''Home safe?'' Short. Strong.","Two words that carry all the other words."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["The last bite, and {partner} saw it coming. Hm.","They noticed every fry you''ve ever given up.","That''s real love. Food love."],"A:B":["You warm the bed. {partner} guessed the last bite.","Hm. They think the mattress is just naturally cozy.","Leave a note on the pillow. ''This was me.''"],"A:C":["You send ''home safe?'' {partner} guessed the last bite.","Hm. They think your love language is fries. It''s also texts.","Do both. Text from the table. Pass the fries."],"B:A":["You give up the last bite. {partner} guessed bed warming.","Hm. They missed all the fries you sacrificed.","Next time, slide it over slowly. Make eye contact."],"B:B":["Warming the bed, and {partner} knew. Hm.","They clocked the warm sheets. Every single time.","Human heater. Respected profession."],"B:C":["''Home safe?'' is your love note. {partner} guessed bed warming.","Hm. They''re giving the blanket your credit.","Fine. Warm the bed too. Overachiever."],"C:A":["Last bite for you. {partner} guessed the ''home safe?'' text.","Hm. They''re reading your texts, not your plate.","Text ''saved you the last bite.'' Both covered."],"C:B":["Bed warming is your move. {partner} guessed the texts.","Hm. Your best work, completely uncredited. Classic.","Text them: ''Bed''s warm.'' Now they''ll know."],"C:C":["''Home safe?'' texts, and {partner} knew. Hm.","Short texts. Huge meaning. They get it.","Mabel texts me that. From the next room."]}}'::jsonb),
('MM-V18','adventure_friend_mm','Guess','{"id":"MM-V18","friendId":"adventure_friend_mm","type":"Guess","scene":"A spider strolls across your ceiling. Mr Mole watches it, unbothered.","lines":["Hm. Roommate. Doesn''t pay rent."],"question":"There''s a spider in the house. What does your partner do?","selfQuestion":"There''s a spider in the house. What do you do?","choices":[{"id":"A","label":"Gently carries it outside","reply":["Hm. Spider escort. Gentle soul.","Mabel does this. She names them first."]},{"id":"B","label":"Calls for backup","reply":["Hm. Backup. Smart. Spiders are fast.","No shame. I scream too. Quietly."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Spider escort, and {partner} knew. Hm.","Cup, paper, calm face, out the door.","That spider tells all its friends about you."],"A:B":["You''d call for backup. {partner} thought you were the brave one.","Hm. Your secret''s out.","Good news: now they know to come running."],"B:A":["You''d walk the spider out. {partner} thought you''d yell for help.","Hm. They don''t know you''re the spider whisperer.","Show them next time. Very casually."],"B:B":["Calling for backup, and {partner} knew it. Hm.","They already know their role: spider bodyguard.","Teamwork. One screams, one carries."]}}'::jsonb),
('MM-V19','adventure_friend_mm','Guess','{"id":"MM-V19","friendId":"adventure_friend_mm","type":"Guess","scene":"Mr Mole lies flat on your rug and stares at the ceiling. Peacefully.","lines":["Hm. Sunday energy. Let''s discuss."],"question":"Lazy Sunday. What does your partner actually want to do?","selfQuestion":"Lazy Sunday. What do you actually want to do?","choices":[{"id":"A","label":"Fix a few things around the house","reply":["Hm. Productive Sunday. Suspicious.","Mabel calls it ''puttering.'' I respect it."]},{"id":"B","label":"Absolutely nothing","reply":["Hm. Nothing. A noble goal.","Sundays were made for staring at ceilings."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Fixing stuff, and {partner} knew. Hm.","They''ve seen you ''relax'' while holding a screwdriver.","Let them nap nearby. You putter."],"A:B":["You want to do nothing. {partner} thought you''d be fixing things.","Hm. Busted. The tools stay in the drawer.","Tell them gently: Sunday is a no-hammer zone."],"B:A":["You''d want to fix stuff. {partner} thought you''d do nothing.","Hm. Surprise handyman. Plot twist.","Fix one thing, then do nothing together. Fair trade."],"B:B":["Absolutely nothing, and {partner} knew. Hm.","Pajamas. No plans. No guilt.","Perfect Sunday. Mole approved."]}}'::jsonb),
('MM-V20','adventure_friend_mm','Guess','{"id":"MM-V20","friendId":"adventure_friend_mm","type":"Guess","scene":"Mr Mole shows you a small window he dug for Mabel. He looks very proud. Says nothing.","lines":["Hm. About being proud. Quietly."],"question":"When your partner is secretly proud of you, what do they do?","selfQuestion":"When you''re secretly proud of your partner, what do you do?","choices":[{"id":"A","label":"Tells everyone","reply":["Hm. A hype person. Loud love.","Mabel tells the whole tunnel when I fix a window."]},{"id":"B","label":"Says ''hm, nice'' and smiles","reply":["Hm. ''Hm, nice.'' My entire vocabulary.","Means more than it sounds. Trust me."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You tell everyone, and {partner} knew. Hm.","Your group chat has heard about them. Many times.","Keep going. They act embarrassed. They''re not."],"A:B":["Just ''hm, nice'' from you. {partner} imagined a whole parade.","Hm. Lower their expectations or raise your volume.","Tell one person. Out loud. Where they can hear."],"B:A":["You tell everyone. {partner} thought you''d just say ''hm, nice.''","Hm. They have no idea about your bragging.","Forward them one hype text. Let them see."],"B:B":["''Hm, nice'' and a smile, and {partner} knew. Hm.","They read that tiny smile like a full speech.","Mole-level communication. I''m proud. Hm. Nice."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_jn','["I’m fine. Just chilling on your couch till {partner} shows up. Don’t mind me.","Not leaving till I’ve said hi to {partner}. Also your snacks are good. Mostly that."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('JN-V01','adventure_friend_jn','Trivia','{"id":"JN-V01","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper strolls in wearing sunglasses indoors, holding a family-size bag of chips.","lines":["I''m fine. Totally fine. Anyway, I brought trivia. And these chips are mine."],"question":"When a red fox pounces on prey under snow, what helps it aim?","selfQuestion":null,"choices":[{"id":"A","label":"Smelling the snow''s vibes","reply":["Vibes are real, but no.","Scientists think foxes use Earth''s magnetic field to aim their pounce.","They land better facing northeast. Nature''s cheat code."]},{"id":"B","label":"Closing their eyes and hoping","reply":["That''s literally how I date. Didn''t work either.","Foxes likely use Earth''s magnetic field to aim pounces.","Northeast-facing jumps hit way more often. Wild, right?"]},{"id":"C","label":"Earth''s magnetic field","reply":["Okay, you''re smart. Annoyingly smart.","Red foxes pounce more accurately facing roughly northeast, likely using Earth''s magnetism.","Built-in GPS. Wish it worked for my love life."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Red foxes'' pounces are more successful when aligned roughly NE; magnetoreception hypothesized.","coupleReplies":{}}'::jsonb),
('JN-V02','adventure_friend_jn','Trivia','{"id":"JN-V02","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper chops an onion on your counter. Her eyes are watering. She glares at the onion.","lines":["This is onion. Not feelings. Onion."],"question":"Why does cutting onions make you cry?","selfQuestion":null,"choices":[{"id":"A","label":"Onions are just sad vegetables","reply":["Relatable. Not science.","Cutting them releases a sulfur gas that irritates your eyes.","Tip: chill the onion first. Fewer tears. Unlike breakups."]},{"id":"B","label":"Onions release a gas that irritates your eyes","reply":["Correct. It''s chemical warfare, not heartbreak.","Cutting releases a sulfur compound that turns into an eye-stinging gas.","So these tears are scientifically NOT about him. Thank you."]},{"id":"C","label":"You''re allergic to all vegetables","reply":["Then I''d only eat chips. Wait. Hm.","Onions release an eye-irritating sulfur gas when cut.","A cold onion or a sharp knife helps. Emotional tips not included."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Cutting onions releases syn-propanethial-S-oxide, a lachrymatory factor.","coupleReplies":{}}'::jsonb),
('JN-V03','adventure_friend_jn','Trivia','{"id":"JN-V03","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper peels a banana with suspicious focus.","lines":["Eating fruit. Healthy coping. My therapist would be so proud."],"question":"Which of these is technically a berry?","selfQuestion":null,"choices":[{"id":"A","label":"Strawberry","reply":["Plot twist: strawberries aren''t true berries.","Bananas are, botanically. Strawberries are a whole other thing.","Their seeds are on the outside. Trust issues, much?"]},{"id":"B","label":"Banana","reply":["Correct. Bananas are berries. Feel betrayed yet?","Botanically, bananas fit the berry definition. Strawberries don''t.","Things aren''t always what they''re called. Like ''talking stage.''"]},{"id":"C","label":"Raspberry","reply":["Nope, betrayed by the name.","It''s the banana. Botanically, bananas count as berries.","Raspberries are something else entirely. Labels lie."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Botanically, bananas are berries; strawberries and raspberries are not.","coupleReplies":{}}'::jsonb),
('JN-V04','adventure_friend_jn','Trivia','{"id":"JN-V04","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper breaks a chocolate bar in half, eats both halves.","lines":["Chocolate question. Very relevant to my current lifestyle."],"question":"Where do cacao pods, the source of chocolate, grow?","selfQuestion":null,"choices":[{"id":"A","label":"Directly on the trunk of the cacao tree","reply":["Correct. Pods sprout straight off the trunk.","Each pod holds seeds that become chocolate after fermenting and roasting.","A tree that grows dessert on its body. Goals."]},{"id":"B","label":"Underground, like potatoes","reply":["Underground chocolate would be a dream. No.","Cacao pods grow right off the trunk and big branches of the tree.","Imagine a tree just... sprouting chocolate pods from its body. Iconic."]},{"id":"C","label":"On tiny bushes in the desert","reply":["Too dry. Cacao loves the tropics.","The pods grow right on the trunk and thick branches.","The beans inside become chocolate. Long process. Worth it."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Cacao is cauliflorous; pods grow directly from trunk and main branches.","coupleReplies":{}}'::jsonb),
('JN-V05','adventure_friend_jn','Trivia','{"id":"JN-V05","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper rips open a bag of peanuts with dramatic force.","lines":["Snack question. Underground edition. My two favorite things."],"question":"Where do peanuts grow?","selfQuestion":null,"choices":[{"id":"A","label":"On tall trees","reply":["Nope. No peanut trees.","Peanuts grow underground. The flower stalk pushes into the soil.","Basically a plant that buries its own snacks. Relatable."]},{"id":"B","label":"Inside little pods on vines","reply":["Close-ish. They are pods.","But they grow underground. The flower stalk dives into the dirt.","Peanuts are actually legumes. Like beans in disguise."]},{"id":"C","label":"Underground","reply":["Correct. Underground snacks. My people.","The plant flowers above ground, then pushes its pods into the soil.","Peanuts are legumes, not nuts. Identity crisis. Same."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Peanuts develop underground after the flower stalk (peg) pushes into soil; they are legumes.","coupleReplies":{}}'::jsonb),
('JN-V06','adventure_friend_jn','Trivia','{"id":"JN-V06","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper changes her phone wallpaper to a snowy mountain, then back again.","lines":["I''m fine. New season, new me. Speaking of glow-ups."],"question":"What does an Arctic fox''s coat do through the year?","selfQuestion":null,"choices":[{"id":"A","label":"Stays white all year","reply":["Basic. The Arctic fox would never.","It changes color: snowy white in winter, brownish in summer.","A full seasonal rebrand. Iconic."]},{"id":"B","label":"Turns pink in summer","reply":["Okay, I''d watch that reality show.","It switches from white in winter to brown-gray in summer.","Camouflage, not Barbiecore. Sadly."]},{"id":"C","label":"Changes color with the seasons","reply":["Correct. The ultimate seasonal glow-up.","White in winter for snow, brownish-gray in summer to blend in.","She switches her look and nobody asks questions. Goals."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Arctic foxes molt from white winter coats to brown/gray summer coats.","coupleReplies":{}}'::jsonb),
('JN-V07','adventure_friend_jn','Trivia','{"id":"JN-V07","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper holds up a tomato like she''s in a courtroom.","lines":["Is it a fruit? Is it a vegetable? Is anything what it seems? Anyway."],"question":"In 1893, the U.S. Supreme Court ruled that tomatoes were legally what?","selfQuestion":null,"choices":[{"id":"A","label":"A fruit","reply":["Botanically, yes. Legally? Plot twist.","The court ruled tomatoes a vegetable, for tax reasons.","Science said fruit. The law said vegetable. Complicated relationship."]},{"id":"B","label":"A vegetable","reply":["Correct. Legally a vegetable.","Botanically it''s a fruit, but the court went with how people cook it.","Labels are complicated. I''m ''single'' but also ''it''s complicated.''"]},{"id":"C","label":"A berry","reply":["Botanically it IS a berry. The law didn''t care.","The court called it a vegetable, mostly about import taxes.","Two identities. Relatable tomato."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Nix v. Hedden (1893) classified tomatoes as vegetables for tariff purposes.","coupleReplies":{}}'::jsonb),
('JN-V08','adventure_friend_jn','Trivia','{"id":"JN-V08","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper drizzles honey on toast and doesn''t make eye contact.","lines":["I''m fine. This one''s about something that lasts. Unlike some people."],"question":"What''s special about honey?","selfQuestion":null,"choices":[{"id":"A","label":"It can basically never spoil","reply":["Yep. Honey is forever. Unlike some boyfriends.","Edible honey has been found in ancient Egyptian tombs.","Low water, high sugar, no germs. Main character food."]},{"id":"B","label":"It''s made from bee tears","reply":["Bees cry? Okay, now I''m sad.","No, it''s nectar. And properly stored, honey basically never spoils.","Archaeologists found edible honey in ancient tombs."]},{"id":"C","label":"It glows in the dark","reply":["That would be iconic for midnight toast.","Real fact: stored right, honey basically never spoils.","Edible honey turned up in ancient Egyptian tombs."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Properly stored honey is extremely resistant to spoiling; edible honey reported in ancient Egyptian tombs.","coupleReplies":{}}'::jsonb),
('JN-V09','adventure_friend_jn','Trivia','{"id":"JN-V09","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper puts a hand on her chest, then quickly pretends she''s adjusting her scarf.","lines":["Heart question. Medical. Not personal. Completely unrelated to anything."],"question":"Can intense emotional stress actually affect your heart?","selfQuestion":null,"choices":[{"id":"A","label":"No, that''s just a metaphor","reply":["Turns out it''s more than a metaphor.","''Broken heart syndrome'' is a real, usually temporary heart condition from intense stress.","Most people recover fully. Note to self. I mean, note to everyone."]},{"id":"B","label":"Yes, there''s a real condition called ''broken heart syndrome''","reply":["Yes. It''s real. Doctors call it takotsubo.","Sudden intense stress can temporarily weaken the heart muscle.","Usually it recovers. Which is good news. For everyone. Hypothetically."]},{"id":"C","label":"Only in movies","reply":["Movies got this one right, weirdly.","Broken heart syndrome is real and triggered by intense stress.","It usually heals. Hearts are tougher than they look."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Takotsubo cardiomyopathy (''broken heart syndrome'') is a usually reversible stress-induced heart condition.","coupleReplies":{}}'::jsonb),
('JN-V10','adventure_friend_jn','Trivia','{"id":"JN-V10","friendId":"adventure_friend_jn","type":"Trivia","scene":"Juniper scrolls through photos of pink birds standing on one leg.","lines":["They''re so dramatic. I love them. Unrelated: I''m also dramatic."],"question":"Why are flamingos pink?","selfQuestion":null,"choices":[{"id":"A","label":"From pigments in the food they eat","reply":["Correct. Diet-based glow-up.","Pigments called carotenoids in algae and shrimp tint their feathers pink.","No pink snacks, no pink bird. Respect the commitment."]},{"id":"B","label":"They''re born pink and stay that way","reply":["Nope. Baby flamingos are gray-white.","They turn pink from pigments in the algae and shrimp they eat.","You are what you eat. I''m currently 40% chips."]},{"id":"C","label":"Sunburn from standing in the sun all day","reply":["Ouch. No.","Their pink comes from pigments in their algae and shrimp diet.","Chicks start gray. The pink is earned."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Flamingo coloration comes from dietary carotenoids.","coupleReplies":{}}'::jsonb),
('JN-V11','adventure_friend_jn','Preference','{"id":"JN-V11","friendId":"adventure_friend_jn","type":"Preference","scene":"Juniper opens your fridge without asking and stands there thinking.","lines":["Don''t mind me. Doing research. On comfort food. For science."],"question":"Bad day comfort food: sweet or salty?","selfQuestion":null,"choices":[{"id":"A","label":"Sweet","reply":["Sweet. Ice cream therapy.","Free, cold, and never cancels plans."]},{"id":"B","label":"Salty","reply":["Salty. Chips first, questions later.","Crunch is emotional support."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both go sweet. A two-spoon household.","Get a pint for you and a pint for {partner}. No sharing drama.","I''m fine. I just want ice cream now."],"A:B":["Salty for you, sweet for {partner}.","Honestly ideal. Zero snack competition.","Fries dipped in a milkshake. Try it. Life-changing."],"B:A":["Sweet for you, salty for {partner}.","Perfect. Nobody steals anybody''s snack.","Chocolate-covered pretzels. Peace treaty."],"B:B":["Salty for both of you. Crunch squad.","So you and {partner} probably fight over the last chip.","Buy two bags. Love is logistics."]}}'::jsonb),
('JN-V12','adventure_friend_jn','Preference','{"id":"JN-V12","friendId":"adventure_friend_jn","type":"Preference","scene":"Juniper glances at your phone lock screen, then pretends she didn''t.","lines":["I''m fine. Totally not looking. Okay I looked."],"question":"Your phone wallpaper: a photo of you two, or literally anything else?","selfQuestion":null,"choices":[{"id":"A","label":"A photo of us","reply":["A couple photo? Cute. Disgusting. Cute.","Your lock screen is a soft launch."]},{"id":"B","label":"Anything else","reply":["Anything else? Mysterious.","A sunset, a cat, a meme. Respect."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Both of you use a couple photo. Okay, adorable.","Honestly, you and {partner} are a hard launch couple.","I''m fine. My wallpaper is a croissant."],"A:B":["You keep it random. {partner} uses a photo of you two.","They''re down bad, in a sweet way.","Maybe match them. Just for a week. See what happens."],"B:A":["Couple photo for you. {partner} keeps it mysterious.","Their lock screen might be a sandwich. Don''t take it personally.","Send them your favorite pic. Just as a suggestion."],"B:B":["Neither of you uses a couple photo. Low-key love.","I can picture it: you and {partner} keep it private. Mature.","Croissant wallpaper gang. Welcome."]}}'::jsonb),
('JN-V13','adventure_friend_jn','Preference','{"id":"JN-V13","friendId":"adventure_friend_jn","type":"Preference","scene":"Juniper steals a fry from your plate and looks you dead in the eye.","lines":["This fry looked lonely. I rescued it."],"question":"Food-sharing rule?","selfQuestion":null,"choices":[{"id":"A","label":"Order two, share both","reply":["Share both. Diplomatic.","Two dishes, double the joy."]},{"id":"B","label":"Hands off my plate","reply":["Hands off. A boundary. Healthy.","Some fries are not for sharing."]},{"id":"C","label":"Say ''not hungry,'' then eat theirs","reply":["Ah, the classic fry thief.","Not hungry, but hungry for theirs."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Order two and share. You and {partner} are a buffet couple.","Every dinner is a tasting menu with a side of forks crossing.","Rowan never shared his fries. Not that I think about it. Next."],"A:B":["Hands off your plate. {partner} wants to share.","They''ll keep offering bites. You''ll keep saying no.","Give them one fry. Just one. It''s love."],"A:C":["You steal food. {partner} likes sharing. Easy.","They''re basically an open buffet for you.","Lucky you. Don''t push it."],"B:A":["You share both dishes. {partner} guards their plate.","Rough. Your fork will get rejected.","Ask first. Or order extra fries for the middle."],"B:B":["Hands off for both of you. Respect.","Pretty sure you and {partner} each guard your plates like treasure.","No tension. Separate fries, happy hearts."],"B:C":["Fry thief, meet plate guard.","{partner} will catch you. They always do.","Ask nicely. Or bribe them with dessert."],"C:A":["You love sharing. {partner} pretends they''re not hungry.","Then eats half your plate while saying ''I''m good.''","Order an extra side just for them. Label it ''not hungry fries.''"],"C:B":["Hands off your plate. {partner} is a fry thief.","Oof. You''ll need a fork shield.","Or order one extra fries just for them."],"C:C":["You''re both fry thieves. Absolute chaos.","Lowkey, you and {partner} will reach for the same fry at the same time.","Order extra fries for the middle. Or fight. Your call."]}}'::jsonb),
('JN-V14','adventure_friend_jn','Preference','{"id":"JN-V14","friendId":"adventure_friend_jn","type":"Preference","scene":"Juniper grabs your remote and scrolls past every rom-com, very fast.","lines":["Nope. Skip. Skip. Not that one. Okay, movie question."],"question":"Movie night: rom-com, or something with explosions?","selfQuestion":null,"choices":[{"id":"A","label":"Rom-com","reply":["Rom-com. Brave choice around me.","I won''t cry. Okay, I might."]},{"id":"B","label":"Explosions","reply":["Explosions. Loud. Safe. Emotionally.","No kissing scenes. Just cars flipping."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Both rom-com. Tissues on standby.","You and {partner} probably mouth the lines together.","I''m fine. I''m not crying. You''re crying."],"A:B":["Explosions for you. {partner} wants a rom-com.","Watch theirs first. Hold their hand at the sad part.","Then blow stuff up. Balance."],"B:A":["Rom-com for you. {partner} wants explosions.","Plot twist: some rom-coms have car chases.","Or alternate nights. Fair is fair."],"B:B":["Both explosions. Volume up.","So you and {partner} prefer feelings in the form of car chases.","Popcorn plus fire. Iconic."]}}'::jsonb),
('JN-V15','adventure_friend_jn','Preference','{"id":"JN-V15","friendId":"adventure_friend_jn","type":"Preference","scene":"Juniper unlocks her phone, then deletes a photo with zero hesitation.","lines":["That photo didn''t exist. You saw nothing."],"question":"Phone passwords: share everything, or some things stay private?","selfQuestion":null,"choices":[{"id":"A","label":"Share everything","reply":["Open phone policy. Bold.","Nothing to hide but your search history."]},{"id":"B","label":"Some things stay private","reply":["Privacy. Healthy and valid.","Trust doesn''t need passwords."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Full password sharing for both of you. Trust era.","Honestly, you and {partner} could swap phones and survive.","I''m fine. I''d delete my notes app first."],"A:B":["You like privacy. {partner} shares everything.","Tell them it''s not about secrets. It''s about you.","Then maybe share one thing. Like your favorite meme folder."],"B:A":["You''d share everything. {partner} likes some privacy.","That''s okay. Trust isn''t a password.","Give them space. They''ll share when they''re ready."],"B:B":["You both keep some things private. Respect.","Trust without passwords. You and {partner} are mature.","Very healthy. Juniper approves."]}}'::jsonb),
('JN-V16','adventure_friend_jn','Guess','{"id":"JN-V16","friendId":"adventure_friend_jn","type":"Guess","scene":"Juniper opens three snack bags at once, side by side.","lines":["Before you ask, this is a normal amount of snacks."],"question":"On a bad day, what''s your partner''s go-to snack?","selfQuestion":"On a bad day, what''s your go-to snack?","choices":[{"id":"A","label":"Ice cream","reply":["Ice cream. Classic heartbreak food.","I''m fine. I''m not eating ice cream. Shut up."]},{"id":"B","label":"Chips","reply":["Chips. Crunch therapy.","Can''t cry when you''re crunching."]},{"id":"C","label":"Midnight instant noodles","reply":["Midnight noodles. Unhinged. Respect.","Comfort in a cup at 2 a.m."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Ice cream, and {partner} called it.","They''ve seen you with a spoon and a sad face before.","Keep a pint in the freezer. Emergency use only."],"A:B":["Chips for you. {partner} guessed ice cream.","They''re showing up with a pint while you want crunch.","Tell them. Or take both."],"A:C":["Midnight noodles for you. {partner} guessed ice cream.","Cold vs hot. Opposite ends of the freezer.","Time to tell them your 2 a.m. secret."],"B:A":["Ice cream for you. {partner} guessed chips.","They''ve been bringing the wrong snack. Gently correct them.","Or do sweet and salty together. Peak bad-day combo."],"B:B":["Chips, and {partner} called it.","They know the crunch means you''re struggling.","Hide a bag somewhere. For emergencies."],"B:C":["Midnight noodles for you. {partner} guessed chips.","They show up with a bag while you''re boiling water.","Tell them your 2 a.m. kettle is a cry for help."],"C:A":["Ice cream for you. {partner} guessed midnight noodles.","Same timing, different temperature.","Ice cream at midnight still counts."],"C:B":["Chips for you. {partner} guessed midnight noodles.","Right salt level, wrong format.","Crush chips on top of noodles. Trust me. Life-changing."],"C:C":["Midnight noodles, and {partner} called it.","They''ve heard the kettle at 2 a.m. They know.","Iconic. Make extra for them."]}}'::jsonb),
('JN-V17','adventure_friend_jn','Guess','{"id":"JN-V17","friendId":"adventure_friend_jn","type":"Guess","scene":"Juniper smiles a little too wide.","lines":["I''m fine. Totally fine. Why do you ask?"],"question":"When your partner says ''I''m fine,'' what does it actually mean?","selfQuestion":"When you say ''I''m fine,'' what does it actually mean?","choices":[{"id":"A","label":"Actually fine","reply":["Actually fine? Rare. Lucky you.","Some people mean it. Not me, but some people."]},{"id":"B","label":"Absolutely not fine","reply":["Not fine. Classic.","The ''I''m fine'' that hits like thunder."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Actually fine, and {partner} trusts it.","When you say it, you mean it. Good communication.","I''m fine. Okay, I''m jealous."],"A:B":["You''re not fine. {partner} thought you meant it.","Oof. Time for a new code word.","Try ''I''m fine-ish.'' That''s a cry for snacks."],"B:A":["You''re actually fine. {partner} thinks you''re secretly not.","They''ll keep checking on you. Kind of cute.","Say ''really fine'' with a smile. Then they''ll relax."],"B:B":["Not fine, and {partner} knows it.","They can tell the ''I''m fine'' that means ''please hug me.''","Real ones know. Keep them close."]}}'::jsonb),
('JN-V18','adventure_friend_jn','Guess','{"id":"JN-V18","friendId":"adventure_friend_jn","type":"Guess","scene":"Juniper casually checks someone''s social media, then closes it fast.","lines":["Not jealous. Just checking. Who even posts that much? Anyway."],"question":"How does your partner act when they''re a little jealous?","selfQuestion":"How do you act when you''re a little jealous?","choices":[{"id":"A","label":"Goes quiet","reply":["Quiet jealous. Silent but deadly.","One sigh. Seven meanings. All of them about that one coworker."]},{"id":"B","label":"Makes a joke about it","reply":["Joke jealous. Hides it in a meme.","''Haha who''s THAT'' is never just a joke."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You go quiet, and {partner} knew.","They''ve learned your silence has a volume. A loud one.","Say one honest sentence next time. Saves you both an hour."],"A:B":["You joke about it. {partner} expected silence.","They''ll laugh at the joke and completely miss the feeling under it.","Say it once, straight. Then go back to joking. Balance."],"B:A":["You go quiet. {partner} expected a joke.","So they''re waiting for a meme while you''re doing a full silent movie.","Try one tiny joke, then one tiny truth. Works on foxes."],"B:B":["You joke about it, and {partner} knew.","They can hear the jealousy hiding inside your ''lol.''","Funny is fine. Add one real line after. I''m working on that too."]}}'::jsonb),
('JN-V19','adventure_friend_jn','Guess','{"id":"JN-V19","friendId":"adventure_friend_jn","type":"Guess","scene":"Juniper hums a breakup ballad, then switches to a pop song fast.","lines":["I wasn''t singing about him. Songs are songs."],"question":"What''s your partner''s karaoke energy?","selfQuestion":"What''s your karaoke energy?","choices":[{"id":"A","label":"Main character, full choreography","reply":["Full choreography. Star behavior.","Grabs the mic and doesn''t let go."]},{"id":"B","label":"Hides behind the snack menu","reply":["Snack menu hider. Shy legend.","Present, supportive, eating fries."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Main character, and {partner} knew it.","They''ve seen your shower concerts. They''ve been warned.","Next time, duet. Make it a moment."],"A:B":["You hide behind the menu. {partner} expected a performance.","Sorry, they''re waiting for a show you won''t give.","Tell them you''ll clap. Loudly. That''s your role."],"B:A":["You''re a karaoke star. {partner} thought you''d hide.","Surprise! Drag them up for a duet.","Watching them see your full choreography? Priceless."],"B:B":["Snack menu hider, and {partner} knew.","They know you''d rather eat fries than sing.","Fair. Someone has to hold the snacks."]}}'::jsonb),
('JN-V20','adventure_friend_jn','Guess','{"id":"JN-V20","friendId":"adventure_friend_jn","type":"Guess","scene":"Juniper pulls out an old ticket stub and stares at it, then puts it away quickly.","lines":["First dates. I''m fine. Don''t ask why I''m fine."],"question":"How would your partner describe your first date?","selfQuestion":"How would you describe your first date?","choices":[{"id":"A","label":"Magical","reply":["Magical. Okay, movie scene.","Sparkles, slow motion, everything."]},{"id":"B","label":"Chaotic","reply":["Chaotic. The best kind of story.","Something went wrong, and it was perfect."]},{"id":"C","label":"Awkward but cute","reply":["Awkward but cute. The realest kind.","Weird pauses, cute smiles."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Magical for both of you. Disgusting. Cute.","{partner} remembers the sparkle too. Same movie, same soundtrack.","I''m fine. Not crying. It''s allergies. To happiness."],"A:B":["Chaos for you. {partner} remembers magic.","They saw sparkles through all the chaos.","That''s love goggles. Keep them."],"A:C":["Awkward but cute for you. {partner} remembers pure magic.","They completely missed the weird pauses. Lucky you.","Never tell them. Let them keep the movie version."],"B:A":["Magical for you. {partner} remembers chaos.","Same date, different movie genres.","Rewatch it together. Who''s right?"],"B:B":["Chaotic, and {partner} agrees.","Spilled drinks? Wrong restaurant? Rain? That''s the lore.","Retell it every anniversary. Add one fake detail each year."],"B:C":["Awkward but cute for you. {partner} remembers chaos.","You remember the pauses. They remember the disasters.","Either way, look at you two now. Rude. Cute."],"C:A":["Magical for you. {partner} remembers awkward but cute.","They were sweating through the whole thing. You saw fireworks.","Tell them their nerves were invisible. Even if they weren''t."],"C:B":["Chaos for you. {partner} remembers awkward but cute.","So something went wrong AND nobody knew what to say?","And you still came back for date two. That''s love."],"C:C":["Awkward but cute, and {partner} agrees.","Weird pauses, nervous laughs, and somehow, a second date.","That''s the realest kind. Movies lie. Awkward is honest."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_pk','["I’m NOT staying just to see {partner}. I’m just... resting. Okay, I’m staying.","Tell {partner} I’m here. Not because I missed them. I’m FINE."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('PK-V01','adventure_friend_pk','Trivia','{"id":"PK-V01","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles sniffs your candle, then suddenly starts licking her own back. Then stops.","lines":["Don''t. Look. At me. It''s a hedgehog thing."],"question":"When hedgehogs find a new smell, they sometimes do what?","selfQuestion":null,"choices":[{"id":"A","label":"Sneeze three times for good luck","reply":["Cute. Not real. I wish it was.","They actually make frothy spit and lick it onto their spines.","It''s called self-anointing. Scientists are still confused."]},{"id":"B","label":"Foam at the mouth and lick it onto their spines","reply":["Yes. It''s called self-anointing. It''s NORMAL.","Nobody knows exactly why. Maybe scent camouflage.","Basil saw me do it on our second date. He stayed. Hero."]},{"id":"C","label":"Write it down in a diary","reply":["I DO have a diary. Not the point.","They self-anoint: froth up spit and spread it on their spines.","Very weird. Very hedgehog. Zero explanation."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Hedgehogs self-anoint, spreading frothy saliva on their spines.","coupleReplies":{}}'::jsonb),
('PK-V02','adventure_friend_pk','Trivia','{"id":"PK-V02","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles pokes a Venus flytrap on your windowsill. It doesn''t close. She pokes it again. SNAP.","lines":["It WAITED. It counted. That''s so me."],"question":"How does a Venus flytrap avoid snapping shut on raindrops?","selfQuestion":null,"choices":[{"id":"A","label":"It can see the bug with tiny eyes","reply":["Plants with eyes? Terrifying. No.","It counts touches. Two in a short window triggers the snap.","No eyes. Just math. And snacks."]},{"id":"B","label":"It waits for two touches in a short time","reply":["Correct! It literally counts!","Two hair triggers touched within about 20 seconds, then SNAP.","One touch could be nothing. Two means business. I respect that boundary."]},{"id":"C","label":"It only closes at night","reply":["Nope, it''s open for business all day.","It needs two touches on its trigger hairs within seconds.","A plant with trust issues. Same, flytrap. Same."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Venus flytraps typically require two trigger-hair stimulations within ~20–30 seconds to close.","coupleReplies":{}}'::jsonb),
('PK-V03','adventure_friend_pk','Trivia','{"id":"PK-V03","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles flinches dramatically at a pinecone on your shelf.","lines":["I thought that was a porcupine. Long day."],"question":"Can a porcupine shoot its quills at you?","selfQuestion":null,"choices":[{"id":"A","label":"No, quills come off on contact","reply":["Correct. No sniper porcupines.","Quills pop off when touched, and tiny barbs make them stick.","Mine stay on. I''m the safe spiky friend. Mostly."]},{"id":"B","label":"Yes, like darts","reply":["Nope. Myth. Movies lied to you.","Porcupines can''t shoot quills. They just detach easily on contact.","Back into one and you''ll learn. Painfully."]},{"id":"C","label":"Only when it''s really mad","reply":["Mad or not, no shooting.","Quills detach on contact. Barbs make them hard to pull out.","Rule one: don''t hug a porcupine. Rule two: see rule one."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Porcupines can''t shoot quills; barbed quills detach on contact.","coupleReplies":{}}'::jsonb),
('PK-V04','adventure_friend_pk','Trivia','{"id":"PK-V04","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles grabs your hand, holds it for a second, then lets go and crosses her arms.","lines":["That was a test. For science. Don''t make it a thing."],"question":"What did a famous study find about holding a partner''s hand during stress?","selfQuestion":null,"choices":[{"id":"A","label":"It made people sweat more","reply":["Rude to sweaty hands everywhere. No.","Holding a partner''s hand reduced brain responses to threat.","Hand-holding is basically a chill pill. Free. No prescription."]},{"id":"B","label":"It did nothing at all","reply":["It did SOMETHING. Don''t be a cactus.","Holding a partner''s hand calmed brain responses to stress.","Even more than holding a stranger''s hand. Basil is very smug about this."]},{"id":"C","label":"It calmed the brain''s threat response","reply":["YES. Science says holding hands helps.","In the study, holding a partner''s hand reduced brain activity linked to threat.","So when Basil grabs my hand, it''s medical. Not cute. Medical."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Coan et al. (2006): spousal hand-holding attenuated neural threat responses.","coupleReplies":{}}'::jsonb),
('PK-V05','adventure_friend_pk','Trivia','{"id":"PK-V05","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles pokes a cactus on your windowsill and gasps.","lines":["A fellow spiky queen."],"question":"What are cactus spines, technically?","selfQuestion":null,"choices":[{"id":"A","label":"Hardened hairs","reply":["Close in vibe, wrong in biology.","Cactus spines are modified leaves.","No big leaves means less water lost in the desert. Smart."]},{"id":"B","label":"Tiny bones","reply":["Bones?? In a plant?? Spooky.","They''re modified leaves.","Tiny spines lose less water and say ''back off'' to hungry animals."]},{"id":"C","label":"Modified leaves","reply":["Correct. Leaves that chose violence.","Spines lose less water than leaves and guard the plant from snackers.","Honestly? Relatable. Protect yourself, queen."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Cactus spines are modified leaves.","coupleReplies":{}}'::jsonb),
('PK-V06','adventure_friend_pk','Trivia','{"id":"PK-V06","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles shows you a photo of a tiny hedgehog wearing a sock, then hides her face.","lines":["It''s not cute. It''s SO cute. Ugh."],"question":"What''s a baby hedgehog called?","selfQuestion":null,"choices":[{"id":"A","label":"A hedgie","reply":["Close. Cute. Not official.","It''s a hoglet. Yes, really.","Hoglets are born with soft spines under their skin, so mom doesn''t get poked."]},{"id":"B","label":"A hoglet","reply":["YES. Hoglet. Say it again. Hoglet.","Their spines are tucked under a fluid-filled skin at birth.","Then they pop through within hours. Spiky from day one."]},{"id":"C","label":"A spikelet","reply":["That''s a grass part. But I love it.","Baby hedgehogs are hoglets.","Their spines are soft and covered at birth. Nature''s bubble wrap."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Baby hedgehogs are hoglets; spines emerge shortly after birth.","coupleReplies":{}}'::jsonb),
('PK-V07','adventure_friend_pk','Trivia','{"id":"PK-V07","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles stares at a deep-sea documentary on your TV in horror.","lines":["That''s not romantic. That''s a hostage situation."],"question":"What do males of some anglerfish species do after finding a mate?","selfQuestion":null,"choices":[{"id":"A","label":"Fuse permanently to her body","reply":["Correct. Permanently attached. Forever. Literally.","The tiny male bites on and their bodies fuse, sharing her bloodstream.","And Basil thinks I''M clingy. HA."]},{"id":"B","label":"Write her a love song","reply":["In the deep sea? With what pen?","The tiny male latches on and fuses to her body permanently.","Commitment level: absolutely unhinged."]},{"id":"C","label":"Swim away immediately","reply":["The opposite. Terrifyingly opposite.","He bites on and fuses with her, forever.","Some females carry several males. Nobody talks about this enough."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"In some anglerfish (e.g., Ceratiidae), males permanently fuse to females (sexual parasitism).","coupleReplies":{}}'::jsonb),
('PK-V08','adventure_friend_pk','Trivia','{"id":"PK-V08","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles holds up a rose and looks at you very seriously.","lines":["Rose question. Do NOT make a pun about my name."],"question":"Botanists say roses don''t have true thorns. What do they have?","selfQuestion":null,"choices":[{"id":"A","label":"Spikes","reply":["Close. Botanists are pickier.","Roses technically have prickles, from the outer skin layer.","Yes. Prickles. Basil laughed for ten minutes."]},{"id":"B","label":"Prickles","reply":["Yes. Roses have PRICKLES. I''m in this question.","Thorns grow from deeper stem tissue. Rose prickles come from the outer skin layer.","So technically, roses are named after me. Kidding. Unless?"]},{"id":"C","label":"Splinters","reply":["Ow. No.","Roses technically have prickles, not thorns.","Prickles grow from the outer layer, so they snap off easily."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Rose ''thorns'' are botanically prickles (epidermal outgrowths).","coupleReplies":{}}'::jsonb),
('PK-V09','adventure_friend_pk','Trivia','{"id":"PK-V09","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles bites into a chili pepper, turns red, and fans her mouth furiously.","lines":["I''m FINE. It''s FINE. Birds don''t even feel this. Unfair."],"question":"Why can birds eat spicy chili peppers without feeling the burn?","selfQuestion":null,"choices":[{"id":"A","label":"Their bodies don''t react to capsaicin, the spicy chemical","reply":["Correct! Spice-proof!","Birds lack the receptor response that makes chili feel hot to mammals.","So they eat peppers and spread the seeds. Smart pepper. Evil pepper."]},{"id":"B","label":"They drink milk afterward","reply":["Birds with milk mustaches? No.","Birds simply don''t feel capsaicin''s burn the way mammals do.","They spread chili seeds far away. Nature''s delivery service."]},{"id":"C","label":"They swallow without tasting","reply":["Not the reason, though they do gulp.","Their bodies don''t respond to capsaicin, so no burn.","Peppers might have evolved spice to keep mammals away. Rude. Effective."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Birds'' TRPV1 receptors are insensitive to capsaicin; birds disperse chili seeds.","coupleReplies":{}}'::jsonb),
('PK-V10','adventure_friend_pk','Trivia','{"id":"PK-V10","friendId":"adventure_friend_pk","type":"Trivia","scene":"Pickles looks into a mirror, then at you, then back at the mirror, eyes wide.","lines":["My pupils are huge right now. It''s the lighting. Not the snacks. Not Basil."],"question":"What can make your pupils get bigger, besides darkness?","selfQuestion":null,"choices":[{"id":"A","label":"Eating something sour","reply":["Sour makes you squint, not dilate.","Interest and emotional arousal can make pupils widen.","Your eyes are snitches. Remember that."]},{"id":"B","label":"Blinking really fast","reply":["Just makes you look suspicious.","Pupils can widen when you see something exciting or attractive.","Eyes: the worst at keeping secrets."]},{"id":"C","label":"Looking at something or someone you find really interesting","reply":["Correct. Interest makes pupils widen.","Emotional arousal, like attraction or excitement, can dilate pupils.","Basil says my pupils go huge around him. Lies. Probably. Ugh."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Pupil dilation reflects emotional/cognitive arousal, including interest and attraction.","coupleReplies":{}}'::jsonb),
('PK-V11','adventure_friend_pk','Preference','{"id":"PK-V11","friendId":"adventure_friend_pk","type":"Preference","scene":"Pickles hides her hands in her sleeves when you mention Basil.","lines":["Hypothetical question. NOT about me and Basil."],"question":"PDA: hold hands in public, or keep it subtle?","selfQuestion":null,"choices":[{"id":"A","label":"Hold hands in public","reply":["Hold hands? Bold. Cute. Ugh.","Basil tried once. I rolled into a ball. Progress."]},{"id":"B","label":"Keep it subtle","reply":["Subtle. Respect. That''s me.","Cool on the outside, screaming on the inside."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both hold hands in public. Disgusting. I love it.","So you and {partner} are a walking rom-com.","Sigh. I''m FINE."],"A:B":["Subtle for you. {partner} wants to hold hands.","Their hand will keep drifting toward yours.","Hold it for three seconds. Then act casual. Trust me."],"B:A":["You want to hold hands. {partner} likes subtle.","Try pinky fingers. Barely counts as PDA.","Basil and I started there. Now it''s full palm."],"B:B":["You both keep it subtle. Secret agents of love.","Just one eyebrow wiggle between you and {partner}. Everyone else misses it.","Super cute. Super sneaky."]}}'::jsonb),
('PK-V12','adventure_friend_pk','Preference','{"id":"PK-V12","friendId":"adventure_friend_pk","type":"Preference","scene":"Pickles mutters ''pumpkin'' under her breath, then looks horrified.","lines":["I didn''t say anything."],"question":"Pet names: cute nicknames, or just real names?","selfQuestion":null,"choices":[{"id":"A","label":"Cute nicknames","reply":["Nicknames? Sweet pea, honey bun, everything.","Basil calls me ''Pickle.'' I pretend to hate it."]},{"id":"B","label":"Just real names","reply":["Real names. Classy.","Your name is a name. That''s romance."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Both nickname people. Prepare for ''sugar plum.''","Honestly, you and {partner} will invent ten new ones a month.","The weirder, the cuter. Rules."],"A:B":["Real names for you. {partner} loves nicknames.","They''ll call you ''bean'' at some point. Brace.","Smile through it. It''s love. Sticky, sticky love."],"B:A":["Nicknames for you. {partner} likes real names.","Start small. ''Babe.'' Watch their face.","If they blush, upgrade to ''honey bun.''"],"B:B":["Both real names. Straight shooters.","When {partner} says your name, it lands. Simple.","Respect. No ''snookums'' crisis here."]}}'::jsonb),
('PK-V13','adventure_friend_pk','Preference','{"id":"PK-V13","friendId":"adventure_friend_pk","type":"Preference","scene":"Pickles holds her phone, thumb hovering over ''send'', for a very long time.","lines":["This is a theoretical fight. I''m FINE."],"question":"After a fight, who should text first?","selfQuestion":null,"choices":[{"id":"A","label":"Whoever was wrong","reply":["Whoever was wrong. Fair. Rare.","But who admits it? Not me."]},{"id":"B","label":"Whoever''s less stubborn","reply":["Less stubborn. Smart. Mature.","Being stubborn is my cardio though."]},{"id":"C","label":"Whoever gets hungry first","reply":["Hungry first. Honestly genius.","Hunger ends wars. Snacks are diplomacy."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Whoever was wrong. You both agree.","Now you and {partner} just have to agree on who was wrong.","Good luck. Get snacks."],"A:B":["You say less stubborn. {partner} says whoever''s wrong.","So you''re saying THEY''RE stubborn. Bold.","Text first. Prove you''re the chill one."],"A:C":["Hunger rule for you. {partner} wants whoever was wrong.","They want an apology. You want snacks.","Apologize WITH snacks. Unstoppable."],"B:A":["You say whoever''s wrong. {partner} says whoever''s less stubborn.","Plot twist: that might be the same person.","Text first and call it ''being the bigger hedgehog.''"],"B:B":["Less stubborn first. You both agree.","So you and {partner} just have to admit who''s stubborn.","Ha. Ha. Ha. Good luck."],"B:C":["Hunger rule for you. {partner} picks less stubborn.","Snack-powered peace vs principle. Classic.","Bring fries to the negotiation. Win-win."],"C:A":["You say whoever''s wrong. {partner} says whoever''s hungry.","They just want snacks. Let them win this one.","Text ''want pizza?'' Done. Fight over."],"C:B":["Less stubborn for you. {partner} picks hunger.","Stubborn people still get hungry. That''s just science.","Wait an hour. They''ll text ''want food?'' That''s their sorry."],"C:C":["Hunger rule for both of you. Brilliant.","I can picture it: you and {partner} will make up over pizza every time.","Best fight resolution system. I''m stealing it."]}}'::jsonb),
('PK-V14','adventure_friend_pk','Preference','{"id":"PK-V14","friendId":"adventure_friend_pk","type":"Preference","scene":"Pickles stares at her phone screen. Three dots appear. Disappear. Appear.","lines":["WHY does Basil type so slow. Unrelated. Totally unrelated."],"question":"Texting: instant replies, or reply whenever?","selfQuestion":null,"choices":[{"id":"A","label":"Instant replies","reply":["Instant. A hero.","Read receipts on, nerves of steel."]},{"id":"B","label":"Reply whenever","reply":["Whenever. A free spirit.","I wish I was this chill."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Instant replies from both of you. A speedrun couple.","Pretty sure you and {partner} text faster than you talk.","Your phones must be tired."],"A:B":["You reply whenever. {partner} replies instantly.","They''re refreshing the chat. Be kind.","Send a quick ''busy, love you.'' Instant peace."],"B:A":["You reply instantly. {partner} replies whenever.","You''ll stare at the screen. Don''t spiral.","Put the phone down. They''ll text. Probably with a meme."],"B:B":["Both reply whenever. Calm, collected icons.","Lowkey, you and {partner} trust the silence. Amazing.","I could never. Teach me."]}}'::jsonb),
('PK-V15','adventure_friend_pk','Preference','{"id":"PK-V15","friendId":"adventure_friend_pk","type":"Preference","scene":"Pickles hugs a pillow, then rolls up around it.","lines":["Cuddle question. This is NOT personal research."],"question":"Cuddling: big spoon or little spoon?","selfQuestion":null,"choices":[{"id":"A","label":"Big spoon","reply":["Big spoon. Protector energy.","Careful. Some of us are spiky."]},{"id":"B","label":"Little spoon","reply":["Little spoon. Cozy legend.","Being held is a whole vibe."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Both big spoons. Uh oh.","You and {partner} will fight for the back position forever.","Take turns. Or invent a spork."],"A:B":["Little spoon for you. {partner} wants to be big spoon.","Perfect fit. You get held, they get to feel heroic.","Ugh. Too cute. I''m leaving. I''m not leaving. Tell me more."],"B:A":["Big spoon for you. {partner} wants to be little spoon.","Perfect fit. Like two puzzle pieces, but cuddlier.","Basil and I are the same combo. Except my spikes. He wears a hoodie."],"B:B":["Both little spoons. Chaos.","Nobody''s holding anybody. You and {partner} are just two spoons, sad.","Flip a coin. Winner gets held."]}}'::jsonb),
('PK-V16','adventure_friend_pk','Guess','{"id":"PK-V16","friendId":"adventure_friend_pk","type":"Guess","scene":"Pickles'' cheeks go pink when you compliment her quills.","lines":["Stop. I''m not blushing."],"question":"When your partner gets embarrassed, what happens?","selfQuestion":"When you get embarrassed, what happens?","choices":[{"id":"A","label":"Turns red instantly","reply":["Red instantly. Tomato mode.","Can''t hide it. It''s beautiful."]},{"id":"B","label":"Gets extra sassy","reply":["Extra sassy. Defense mechanism.","Sass is armor. I would know."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You go red, and {partner} knew. Tomato twins.","They''ve seen your face switch colors. They live for it.","Accept it. It''s adorable."],"A:B":["Extra sassy. {partner} thought you''d just blush.","Oops. They''ll get the attitude now.","Tell them it means you''re flustered. Save yourself."],"B:A":["You go red. {partner} expected sass.","They''re waiting for attitude. Your cheeks already confessed.","Now they know the blush. They''ll be chasing it forever. Sorry."],"B:B":["Extra sass, and {partner} knew.","They know the attitude means you''re flustered.","Sass equals blushing, but louder. They speak fluent you."]}}'::jsonb),
('PK-V17','adventure_friend_pk','Guess','{"id":"PK-V17","friendId":"adventure_friend_pk","type":"Guess","scene":"Pickles snips a thread with scissors, then yelps. She examines a tiny scratch.","lines":["I''m FINE. It''s barely a scratch. Totally FINE."],"question":"Your partner gets a tiny paper cut. How do they react?","selfQuestion":"You get a tiny paper cut. How do you react?","choices":[{"id":"A","label":"Shrugs it off","reply":["Shrugs it off. A legend.","Tiny cut, zero drama."]},{"id":"B","label":"Full drama, needs a bandage","reply":["Full drama. Respect the performance.","Paper cuts DO hurt. I said what I said."]},{"id":"C","label":"Requests a kiss to make it better","reply":["Kiss it better? Stop. That''s adorable.","Cuts heal faster with love. Fact. Probably."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You shrug it off, and {partner} knew.","Low drama, high tolerance.","Still, let them fuss. It''s their love language."],"A:B":["Full drama for you. {partner} thought you''d shrug.","They expected a shrug. You gave them a three-act tragedy.","Demand the cartoon bandage. You''ve earned it."],"A:C":["Kiss it better for you. {partner} thought you''d shrug.","They didn''t know you''re a softie.","Hold up the finger and pout. They''ll get it."],"B:A":["You shrug it off. {partner} expected full drama.","You surprised them with how chill you are.","Fake one dramatic gasp. For fun."],"B:B":["Full drama, and {partner} knew.","They already have the bandages ready. The cartoon ones.","Oscar-worthy performance. Over a paper cut. I''d clap."],"B:C":["Kiss it better for you. {partner} expected drama.","Different kind of drama. Romantic drama.","Tell them. Watch them pucker up instantly."],"C:A":["You shrug it off. {partner} expected a kiss request.","They were puckered up and everything. You just said ''it''s fine.''","Accept the kiss anyway. Free kiss. Never refuse a free kiss."],"C:B":["Full drama for you. {partner} expected a kiss request.","Close. You want the drama AND the kiss.","Collapse on the couch. Hold out the finger. Wait."],"C:C":["Kiss it better, and {partner} knew.","They''re already puckering up.","Gross. Cute. Okay, mostly cute. I''m blushing for you."]}}'::jsonb),
('PK-V18','adventure_friend_pk','Guess','{"id":"PK-V18","friendId":"adventure_friend_pk","type":"Guess","scene":"Pickles pokes you with one quill, playfully, then pretends she didn''t.","lines":["That wasn''t me."],"question":"How does your partner react when you tease them?","selfQuestion":"How do you react when your partner teases you?","choices":[{"id":"A","label":"Teases back harder","reply":["Teases back harder? Love is war.","Nobody wins. Everybody giggles. Basil still owes me a rematch."]},{"id":"B","label":"Pretends to be mad, secretly loves it","reply":["Fake mad, secretly loving it? Classic.","Arms crossed. Smile absolutely visible. Fooling no one."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You tease back harder, and {partner} knew exactly what they were starting.","They poke you on purpose. They WANT the war.","Keep score on the fridge. Loser buys snacks."],"A:B":["You pretend to be mad. {partner} braced for a counterattack.","They''re ready for war, and you just... pout adorably?","Let one tiny grin slip. Watch them realize they won."],"B:A":["You tease back harder. {partner} expected a cute fake pout.","Plot twist. They poked the wrong hedgehog.","Go easy on them. Or don''t. I''m not your mom."],"B:B":["You fake-pout, and {partner} saw right through it.","They can see the smile fighting its way out behind your crossed arms.","The mad act was never convincing. Not once. Sorry."]}}'::jsonb),
('PK-V19','adventure_friend_pk','Guess','{"id":"PK-V19","friendId":"adventure_friend_pk","type":"Guess","scene":"Pickles rolls into a ball when you get close, then peeks out.","lines":["Sorry. Reflex. My walls are, um, physical."],"question":"What gets through your partner''s walls fastest?","selfQuestion":"What gets through your walls fastest?","choices":[{"id":"A","label":"A silly joke","reply":["A silly joke. Laugh first, open up later.","Humor is the key. I know."]},{"id":"B","label":"A long hug","reply":["A long hug. Even spiky ones need it.","Hold on. Ouch. Worth it."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Silly jokes work on you, and {partner} knew.","They know your walls are made of giggles and bad puns.","One knock-knock joke and the drawbridge just drops. Embarrassing. Cute."],"A:B":["Hugs get through your walls. {partner} guessed jokes.","They''re doing stand-up when you need arms.","Tell them: less comedy, more cuddles."],"B:A":["Jokes get through your walls. {partner} guessed hugs.","They''re hugging when they should be joking.","Hug AND joke. Double defense breach."],"B:B":["Long hugs work on you, and {partner} knew.","They know you melt in hug number two.","Spiky outside, marshmallow inside."]}}'::jsonb),
('PK-V20','adventure_friend_pk','Guess','{"id":"PK-V20","friendId":"adventure_friend_pk","type":"Guess","scene":"Pickles stomps in grumpy, then instantly softens when she sees your snacks.","lines":["Grumpy question. I''m not grumpy. I''m FINE."],"question":"When your partner is grumpy, what fixes it?","selfQuestion":"When you''re grumpy, what fixes it?","choices":[{"id":"A","label":"Food","reply":["Food. Hangry is a real condition. I''ve had it since birth.","Feed first, feelings later."]},{"id":"B","label":"Ten minutes alone","reply":["Ten minutes alone. A reset button.","Do not disturb. Do not even breathe loudly."]},{"id":"C","label":"Being annoyingly cute at them","reply":["Annoyingly cute? High risk, high reward.","Could fix everything. Could start a war."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Food fixes you, and {partner} knew.","There''s probably an emergency granola bar in their bag right now. For you.","That''s not a snack. That''s a love letter."],"A:B":["Alone time fixes you. {partner} guessed food.","They keep feeding you when you need quiet.","Take the snack. Then leave."],"A:C":["Annoying cuteness fixes you. {partner} guessed food.","They''re bringing snacks. You secretly want them to be obnoxiously adorable at you.","Next grumpy day, just say: ''Do the cute thing.'' Watch them deliver."],"B:A":["Food fixes you. {partner} guessed alone time.","They leave you alone when you need a sandwich.","Tell them: snacks first, space second."],"B:B":["Ten minutes alone, and {partner} knew.","They know to back away slowly when your eyebrows do the thing.","Healthy. It''s not rejection, it''s maintenance."],"B:C":["Annoying cuteness fixes you. {partner} guessed alone time.","They keep leaving when they should stay.","Grab them. Say ''be cute at me.''"],"C:A":["Food fixes you. {partner} guessed cuteness.","They''re being adorable at a hungry person. Dangerous.","Rule of the house: feed first, cute second. Write it on the fridge."],"C:B":["Alone time fixes you. {partner} guessed cuteness.","They''re being cute too close. Too soon.","Ten minutes, THEN the cuteness."],"C:C":["Annoyingly cute works on you, and {partner} knew.","One silly face from them and your grump just collapses.","You''re a total softie. I''m the same. Don''t tell anyone."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_tw','["Is {partner} coming back soon? Not that I’m waiting. I’m totally waiting. Nice weather.","Okay so I’ll just sit here quietly until {partner} gets home. Quietly. Mostly quietly."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('TW-V01','adventure_friend_tw','Trivia','{"id":"TW-V01","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig scurries in at top speed, hits your rug, slides, and pretends that was the plan.","lines":["Hi hi hi okay so I was humming earlier and it made me think of a quiz. Nice weather."],"question":"Male mice do something surprising to impress a mate. What is it?","selfQuestion":null,"choices":[{"id":"A","label":"Bring her cheese","reply":["Cute, very cartoon, but no.","Male mice sing ultrasonic love songs, way too high for humans to hear.","Real-life mice are basically secret boy bands."]},{"id":"B","label":"Sing high-pitched love songs","reply":["YES. Mice sing! Ultrasonic serenades, too high for you to hear.","Male mice sing complex songs to court females.","If Sage could hear me sing... wait no, never mind. Nice weather."]},{"id":"C","label":"Do a little dance","reply":["Okay, I would pay to see that.","They actually sing: ultrasonic songs humans can''t hear.","Tiny love ballads happening in your walls right now. You''re welcome."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Male mice produce ultrasonic courtship songs.","coupleReplies":{}}'::jsonb),
('TW-V02','adventure_friend_tw','Trivia','{"id":"TW-V02","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig unrolls a list titled ''36 Questions'' and immediately rolls it back up.","lines":["This is research. For a friend. The friend is me."],"question":"Psychologists created a set of 36 questions designed to do what?","selfQuestion":null,"choices":[{"id":"A","label":"Help strangers feel close quickly","reply":["Yes!! Strangers asking deep questions in turns!","The study found pairs felt surprisingly close afterward.","Should I ask Sage all 36? Is that too many? It''s too many. Nice weather."]},{"id":"B","label":"Test if someone is lying","reply":["No, that''s a different, scarier test.","They''re questions that help two people build closeness fast.","Taking turns opening up, a little more each round. So brave."]},{"id":"C","label":"Pick the perfect pizza topping","reply":["I''d answer those instantly. Pineapple. Sorry.","It''s a set designed to build closeness between strangers.","Questions get deeper slowly. Like my crush. Slowly. Deeper."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Aron et al. (1997) developed 36 questions to generate interpersonal closeness.","coupleReplies":{}}'::jsonb),
('TW-V03','adventure_friend_tw','Trivia','{"id":"TW-V03","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig touches a little potted plant and it folds its leaves shut. She gasps.","lines":["IT''S SHY. IT''S LIKE ME."],"question":"Why does the ''sensitive plant'' (Mimosa) fold up when touched?","selfQuestion":null,"choices":[{"id":"A","label":"It''s allergic to fingers","reply":["Haha! No.","It folds to protect itself, maybe to scare off hungry bugs.","Water rushes out of special cells, so the leaves collapse in seconds."]},{"id":"B","label":"It''s falling asleep","reply":["Aww, nap plant. Close, but no.","It''s a defense move, triggered by touch.","Water shifts in its cells, so the leaves fold in seconds."]},{"id":"C","label":"A quick defense reaction","reply":["Correct! A defense move!","Touch triggers water to rush out of cells, so leaves fold fast.","Same thing happens to me when Sage says hi. Instant fold."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Mimosa pudica folds leaves rapidly when touched, likely as defense.","coupleReplies":{}}'::jsonb),
('TW-V04','adventure_friend_tw','Trivia','{"id":"TW-V04","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig tilts her head left, then right, then left again, practicing something.","lines":["Purely hypothetical tilting. Unrelated to any future plans."],"question":"When people kiss, which way do most tilt their heads?","selfQuestion":null,"choices":[{"id":"A","label":"To the left","reply":["Some do! But most tilt right.","A study found about two-thirds of people tilt their heads right.","Lefties exist. They''re the rebels of kissing."]},{"id":"B","label":"Straight on, no tilt","reply":["Bonk. That''s noses colliding.","Most people tilt right, about two out of three.","Straight on is how you headbutt. Romantically, maybe."]},{"id":"C","label":"To the right","reply":["Yes! About two out of three people tilt right!","Scientists literally watched couples kissing in public to find this out.","Okay so I should tilt right. Noted. Not for anything. Nice weather."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Güntürkün (2003) observed ~2/3 of kissing couples turn heads to the right.","coupleReplies":{}}'::jsonb),
('TW-V05','adventure_friend_tw','Trivia','{"id":"TW-V05","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig picks up a smooth pebble from your garden and holds it like treasure.","lines":["This is perfect. This is so perfect. For... no reason."],"question":"What do gentoo penguins give potential mates?","selfQuestion":null,"choices":[{"id":"A","label":"Small fish","reply":["Snacks are romantic, but no.","Gentoo penguins give pebbles to their crushes.","Pebbles build their nests. It''s literally a ''let''s build a home'' gift."]},{"id":"B","label":"Pebbles","reply":["YES. Pebbles. I''m crying.","A good pebble helps build a nest, so it''s a big deal.","Should I give Sage a pebble? Is that weird? Nice weather."]},{"id":"C","label":"Seashells","reply":["Pretty, but no.","They give pebbles. Nest-building gifts.","A pebble from a penguin is basically a promise ring."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Gentoo penguins offer pebbles to mates during courtship.","coupleReplies":{}}'::jsonb),
('TW-V06','adventure_friend_tw','Trivia','{"id":"TW-V06","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig wraps her tail around a pen and lifts it, wobbling dramatically.","lines":["Look look look. Okay I dropped it."],"question":"What can a harvest mouse do with its tail?","selfQuestion":null,"choices":[{"id":"A","label":"Grab onto grass stalks, like a fifth hand","reply":["YES. A tail that grabs things!","Harvest mice wrap their tails around stems to climb and balance.","I tried. I dropped the pen. Still proud."]},{"id":"B","label":"Use it to send Morse code","reply":["Ha! That would solve all my texting problems.","Harvest mice use their tails to grip grass stems while climbing.","Basically a fifth hand. Very handy. Sorry. Pun."]},{"id":"C","label":"Nothing, it''s just decoration","reply":["Rude to tails everywhere.","Harvest mice can grip grass stalks with their tails.","It helps them balance way up on wobbly stems."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Harvest mice have prehensile tails.","coupleReplies":{}}'::jsonb),
('TW-V07','adventure_friend_tw','Trivia','{"id":"TW-V07","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig ''accidentally'' walks past your window. Then again. Then again.","lines":["Totally random. Very random. Science says this works, actually."],"question":"What''s the ''mere exposure effect''?","selfQuestion":null,"choices":[{"id":"A","label":"You get sunburned if you stay outside","reply":["That''s just exposure. Mere sunburn.","It''s about liking people and things more after seeing them often.","Familiar feels safe, and safe feels nice."]},{"id":"B","label":"We tend to like things more the more often we see them","reply":["YES. Familiarity breeds fondness!","Repeated exposure tends to make things feel more likable.","This is why I walk past Sage''s café daily. It''s SCIENCE."]},{"id":"C","label":"Seeing something too much makes you hate it","reply":["Sometimes! But usually the opposite.","Repeated exposure tends to increase liking.","Up to a point. I''ll keep my walk-bys to twice a day."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Zajonc''s mere-exposure effect: repeated exposure increases liking.","coupleReplies":{}}'::jsonb),
('TW-V08','adventure_friend_tw','Trivia','{"id":"TW-V08","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig arranges blue buttons on your table in a perfect line.","lines":["Decorating! For a bird reason!"],"question":"How does a male bowerbird try to attract a mate?","selfQuestion":null,"choices":[{"id":"A","label":"Builds and decorates a fancy display","reply":["YES. Interior design for love!","Males build bowers and decorate with colorful objects, often blue ones.","Some even arrange items by size. Main character behavior."]},{"id":"B","label":"Sings opera","reply":["Dramatic! Not the answer!","They build and decorate fancy structures called bowers.","Shiny objects, flowers, berries. Total aesthetic."]},{"id":"C","label":"Writes a love letter","reply":["Okay, I''d faint.","They build a bower and decorate it with colorful treasures.","Blue is a favorite for some species. Taste."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Male bowerbirds build and decorate bowers to attract females.","coupleReplies":{}}'::jsonb),
('TW-V09','adventure_friend_tw','Trivia','{"id":"TW-V09","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig waves her arms and wiggles, doing a strange little dance.","lines":["This is how spiders flirt. I''ve been practicing. Don''t watch."],"question":"How do male peacock spiders try to impress a mate?","selfQuestion":null,"choices":[{"id":"A","label":"Bring her a fly with a bow on it","reply":["Cute! Not real!","They lift a colorful flap on their abdomen and dance.","Tiny, colorful, bold. Everything I''m not."]},{"id":"B","label":"Spin a heart-shaped web","reply":["Omg that would be adorable. No.","They show off a colorful flap and do a little dance.","Some are smaller than a grain of rice. Big moves, tiny body."]},{"id":"C","label":"Raise a colorful flap and dance","reply":["YES!! A tiny rainbow dance!","They lift a bright, colorful fan and wave their legs in a dance.","If I danced for Sage, would he... no. Nice weather."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Male peacock spiders (Maratus) display colorful abdominal flaps and dance.","coupleReplies":{}}'::jsonb),
('TW-V10','adventure_friend_tw','Trivia','{"id":"TW-V10","friendId":"adventure_friend_tw","type":"Trivia","scene":"Twig turns to face the window, then turns to face you, then back again.","lines":["I''m following the sun. And you. And the sun."],"question":"What do young sunflowers do during the day?","selfQuestion":null,"choices":[{"id":"A","label":"Stand completely still","reply":["Nope! They move!","Young sunflowers turn to follow the sun across the sky.","Then they reset overnight. Like a crush reset."]},{"id":"B","label":"Follow the sun across the sky","reply":["Correct! Sun-tracking babies!","Young sunflowers turn east to west, then reset overnight.","Grown-up flowers mostly face east. Committed. Respect."]},{"id":"C","label":"Close up like a book","reply":["Aww, no.","Young sunflowers follow the sun all day.","Then they reset at night to face east again."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Young sunflowers track the sun (heliotropism); mature heads mostly face east.","coupleReplies":{}}'::jsonb),
('TW-V11','adventure_friend_tw','Preference','{"id":"TW-V11","friendId":"adventure_friend_tw","type":"Preference","scene":"Twig fans herself with a napkin. Her cheeks are very pink.","lines":["Hypothetically, if someone, anyone, wanted to confess... Nice weather. Anyway."],"question":"Confessing a crush: in person, or by text?","selfQuestion":null,"choices":[{"id":"A","label":"In person","reply":["In person?? With your actual face?? Legend.","I''d make eye contact for one second and then evaporate."]},{"id":"B","label":"By text","reply":["By text. Safe. Editable. Smart.","You can rewrite it 40 times and nobody has to know. Not that I do that."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["In person for both of you. A courage couple.","So you and {partner} looked each other in the eye and SAID it?","Okay I need a full replay. Slow motion. Please."],"A:B":["By text for you. {partner} wants it in person.","They want eye contact. You want the backspace key.","Text it, then show up with snacks. Best of both. Stealing this."],"B:A":["In person for you. {partner} would rather text it.","So you''d say it out loud, and they''d reply later with ''same'' and a heart?","Honestly? That''s my dream scenario. Writing it down."],"B:B":["By text for both of you. Typing champions.","I bet you and {partner} both stared at ''typing...'' for ten full minutes.","That''s my plan too. I have 14 drafts. It''s fine."]}}'::jsonb),
('TW-V12','adventure_friend_tw','Preference','{"id":"TW-V12","friendId":"adventure_friend_tw","type":"Preference","scene":"Twig peeks around your door like she just happened to be passing by. For the third time.","lines":["Total coincidence that I''m here. Total."],"question":"Making the first move: ask them out directly, or ''accidentally'' keep running into them?","selfQuestion":null,"choices":[{"id":"A","label":"Ask directly","reply":["Directly?! A hero walks among us.","No plan B, no hiding behind plants. Wow."]},{"id":"B","label":"''Accidentally'' run into them","reply":["Strategic run-ins. My entire life strategy.","I know Sage''s coffee schedule. For... unrelated reasons."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both go direct. No games. Very healthy. Very scary.","Neither you nor {partner} would survive my method.","Can one of you write me a script? Bullet points are fine."],"A:B":["You''d plan the run-ins. {partner} would just ask.","You''d be hiding behind a plant while they walk up and say hi.","Let them do it. Accept graciously. Pretend you weren''t hiding."],"B:A":["You''d ask directly. {partner} would rather ''run into'' you.","So while they''re memorizing your schedule, you just say ''coffee?''","Efficient. Brutal. Romantic. I''m taking notes."],"B:B":["Strategic run-ins for both of you. Masterminds.","Honestly, you and {partner} ''bumped into'' each other for how many months?","I see you. I am you. Nice weather."]}}'::jsonb),
('TW-V13','adventure_friend_tw','Preference','{"id":"TW-V13","friendId":"adventure_friend_tw","type":"Preference","scene":"Twig clutches a tiny notebook full of crossed-out lines.","lines":["Okay hypothetical gift for a hypothetical crush. Help. Fast."],"question":"The perfect ''I like you'' gift?","selfQuestion":null,"choices":[{"id":"A","label":"A playlist","reply":["A playlist. Every song is a secret clue.","Track seven says what you can''t. Track eight says it louder."]},{"id":"B","label":"A handwritten note","reply":["A handwritten note?! So brave.","Your handwriting is basically your heart, but in ink."]},{"id":"C","label":"Their favorite snack","reply":["Their favorite snack. Sneaky and smart.","It says ''I pay attention to you.'' Without saying it."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Playlist for both of you. Music nerds in love.","I can picture it: you and {partner} speak entirely in song lyrics.","Please tell me there''s a shared playlist with a cheesy name."],"A:B":["Note for you. {partner} would rather get a playlist.","So they''d want feelings in song form, and you''d want them in ink.","Write the lyrics of their favorite song by hand. Combo achieved."],"A:C":["Snacks for you. {partner} prefers a playlist.","Snacks and songs. That''s a whole date honestly.","Picnic, headphones, done. I''m so jealous."],"B:A":["Playlist for you. {partner} would rather get a note.","Easy fix: write one line for every song.","Track list with tiny love notes. I''m sweating. That''s so good."],"B:B":["Handwritten notes for both of you. My heart.","I bet you and {partner} keep each other''s notes in a box somewhere.","Don''t answer. Just let me imagine it. Thank you."],"B:C":["Snacks for you. {partner} wants a handwritten note.","Write ''I like you'' on the snack bag in marker.","Low effort, high impact. I''m writing this down. Wait. For no one."],"C:A":["Playlist for you. {partner} wants their favorite snack.","Make a playlist called ''songs to eat chips to.''","Gift both. Watch them crunch and smile."],"C:B":["Note for you. {partner} wants snacks.","Tape the note to their favorite snack. Romance AND protein.","They''ll read it mid-bite. Perfect timing."],"C:C":["Favorite snack for both of you. Practical lovers.","Pretty sure you and {partner} show affection by knowing each other''s chip flavor.","That''s real intimacy. Don''t let anyone tell you otherwise."]}}'::jsonb),
('TW-V14','adventure_friend_tw','Preference','{"id":"TW-V14","friendId":"adventure_friend_tw","type":"Preference","scene":"Twig''s phone buzzes. Her group chat is named ''SAGE WATCH 2026''. She flips the phone over.","lines":["That''s a book club. A plant book club."],"question":"Back when you had a crush: did you tell your friends everything, or keep it secret?","selfQuestion":null,"choices":[{"id":"A","label":"Told everyone","reply":["Told everyone. Group chat had a whole investigation.","Screenshots, timelines, astrology charts. The works."]},{"id":"B","label":"Kept it secret","reply":["Kept it secret. Mysterious. Unbothered.","How?? I can''t even keep a secret from my reflection."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both told everyone. Your friends knew before you two did.","Somewhere there''s a group chat about you and {partner} with 400 unread messages.","Honestly, your friends deserve credit at the wedding."],"A:B":["You kept it secret. {partner} told literally everyone.","Their group chat has screenshots of you. Analyzed. Color-coded.","Ask to see it. Brace yourself. It''s going to be adorable."],"B:A":["You told everyone. {partner} kept it secret.","Your friends knew everything. Their friends knew nothing.","Ask their friends now. Watch them find out on replay."],"B:B":["You both kept it secret. Ninja crushes.","Nobody knew? Not even one friend? You and {partner} are spies.","Teach me your ways. My face tells everyone everything."]}}'::jsonb),
('TW-V15','adventure_friend_tw','Preference','{"id":"TW-V15","friendId":"adventure_friend_tw","type":"Preference","scene":"Twig stares out your window. Fidgets. Stares again.","lines":["...Nice weather. Sorry, that''s my default."],"question":"Nervous small talk go-to: the weather, or random fun facts?","selfQuestion":null,"choices":[{"id":"A","label":"The weather","reply":["The weather. Iconic. My people.","''Nice weather'' has gotten me through every awkward moment ever."]},{"id":"B","label":"Random fun facts","reply":["Fun facts. Weird, cute, memorable.","Nothing breaks tension like ''did you know otters hold hands?''"]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Weather talk for both of you. My kind of couple.","Lowkey, you and {partner} probably bonded over a suspicious cloud.","Sunny with a chance of love. Sorry. I had to."],"A:B":["Fun facts for you. {partner} defaults to weather.","You''re over here talking wombats. They''re commenting on humidity.","Somehow it works. Two nervous systems, one love story."],"B:A":["Weather for you. {partner} panics in fun facts.","They say ''snails can sleep for three years,'' you say ''cloudy today.''","That''s a nervous duet. Honestly charming."],"B:B":["Fun facts for both of you. Nerd romance.","I bet you and {partner} flirted entirely through trivia.","Octopuses have three hearts. Imagine having three hearts for someone."]}}'::jsonb),
('TW-V16','adventure_friend_tw','Guess','{"id":"TW-V16","friendId":"adventure_friend_tw","type":"Guess","scene":"Twig giggles way too loud at nothing, then slaps a paw over her mouth.","lines":["Nervous laugh. Ignore it."],"question":"Back when your partner had a crush on you, what gave it away?","selfQuestion":"Back when you had a crush on your partner, what gave it away?","choices":[{"id":"A","label":"Laughing at every single joke","reply":["Laughing at every joke. Even the bad ones. Especially the bad ones.","That''s not humor. That''s love."]},{"id":"B","label":"''Accidentally'' showing up everywhere","reply":["''Accidentally'' everywhere. Coincidence? I think not.","Respect. That takes logistics."]},{"id":"C","label":"Staring, then panicking","reply":["Staring, then panicking. That''s my whole situation.","Eye contact, then full-body chaos."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You laughed at every joke, and {partner} clocked it.","They knew their jokes weren''t that funny. They noticed.","Laughing at bad puns is a love language. I said what I said."],"A:B":["You showed up everywhere. {partner} thought it was the laughing.","They have no idea you planned those ''random'' meetings.","Tell them. Watch them replay every coincidence. Iconic."],"A:C":["Staring then panicking for you. {partner} thought it was the laughing.","They missed the staring? How? You were probably so loud about it.","Tell them about the panicked looking-away. They''ll melt."],"B:A":["You laughed at everything. {partner} thought it was your ''coincidences.''","So they noticed your schedule but not your fake laughing? Lucky.","Confess the laughing now. They''ll be so smug."],"B:B":["You kept ''accidentally'' showing up, and {partner} knew all along.","Your coincidences had a suspiciously good schedule.","And they still let you think it was smooth. That''s love."],"B:C":["Staring then panicking for you. {partner} remembers you always ''being around.''","They noticed you nearby, but not you looking at them.","Next date: stare, panic, then tell them. Full circle."],"C:A":["You laughed at everything. {partner} noticed the staring instead.","So you were laughing AND staring. Double obvious.","Honestly you were not subtle at all. I love that for you."],"C:B":["You showed up everywhere. {partner} remembers the staring.","So they caught your eyes but missed your master plan.","Secret mission: still classified. Nice weather."],"C:C":["Staring then panicking, and {partner} caught every single one.","They watched you look away so fast you almost fell.","Reassuring, honestly. If you two made it, maybe I can too."]}}'::jsonb),
('TW-V17','adventure_friend_tw','Guess','{"id":"TW-V17","friendId":"adventure_friend_tw","type":"Guess","scene":"Twig spins once, slips on your rug, and grabs the table to stay up.","lines":["I''m a terrible dancer. That was a preview."],"question":"If your partner had to slow-dance in public, what would happen?","selfQuestion":"If you had to slow-dance in public, what would happen?","choices":[{"id":"A","label":"Total smooth operator","reply":["Smooth operator? Movie scene unlocked.","Spin, dip, the crowd applauds, I faint."]},{"id":"B","label":"Steps on toes, laughs it off","reply":["Steps on toes, laughs it off. The cutest version.","Honestly better than smooth. More real."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You''re smooth, and {partner} already knew.","They''ve seen the kitchen twirls. They know your secret talent.","Next party, you lead. They hold on and look impressed."],"A:B":["You''d step on toes. {partner} imagined you gliding.","Their expectations: ballroom. Reality: bumper cars.","Laugh through it. Somehow it''ll be even more romantic."],"B:A":["You''d be smooth. {partner} expected stepped-on toes.","They underestimated you. Surprise twirl incoming.","Dip them dramatically. Watch their face. Report back to me."],"B:B":["Toes get stepped on, and {partner} already knew.","They''ve accepted their feet are a sacrifice for love.","Laugh-dancing is the best dancing. Ask anyone. Ask me."]}}'::jsonb),
('TW-V18','adventure_friend_tw','Guess','{"id":"TW-V18","friendId":"adventure_friend_tw","type":"Guess","scene":"Twig scrolls way up in an old chat, then locks her phone very fast.","lines":["I wasn''t rereading anything. Phones just scroll by themselves."],"question":"Does your partner reread old texts from your early dating days?","selfQuestion":"Do you reread old texts from your early dating days?","choices":[{"id":"A","label":"Yes, all the time","reply":["Yes, all the time. Sentimental queen behavior.","There''s probably a screenshot folder labeled with a heart."]},{"id":"B","label":"Never, that''s chaos","reply":["Never. Lives in the present. So healthy.","Teach me. I''ve reread one ''haha'' from Sage 90 times."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You reread them all the time, and {partner} knew.","They''ve caught you smiling at your phone at 1 a.m. They know.","Read your favorite out loud. Watch them cringe and melt."],"A:B":["You never reread them. {partner} imagined you scrolling and smiling.","They think you''re more sentimental than you are. Cute.","Try it once. You''ll cringe. You''ll smile. Worth it."],"B:A":["You reread them. {partner} thought you never would.","Secret softie exposed. Your sentimental side has been found.","Send them a screenshot from the very first week. Chaos and love."],"B:B":["Never, and {partner} knew it.","They know you live in the now. Very zen. Very not me.","Maybe they''re secretly the one with the screenshot folder."]}}'::jsonb),
('TW-V19','adventure_friend_tw','Guess','{"id":"TW-V19","friendId":"adventure_friend_tw","type":"Guess","scene":"Twig scribbles in her notebook, crosses it out, scribbles more, crosses that out too.","lines":["I''m writing a poem. For a cloud. A specific cloud."],"question":"If your partner wrote you a love poem, what would it be like?","selfQuestion":"If you wrote your partner a love poem, what would it be like?","choices":[{"id":"A","label":"Deep and dramatic","reply":["Deep and dramatic. Tissue warning.","Moonlight, longing, seven stanzas."]},{"id":"B","label":"Funny and full of rhymes","reply":["Funny with rhymes. Love that.","''You''re my honey, you''re so funny.'' Classic."]},{"id":"C","label":"Three words long","reply":["Three words long. Efficient poet.","Short, sharp, devastating."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Deep and dramatic, and {partner} expected nothing less.","They already know you''d write three pages about their eyebrows.","Frame it. Read it on every anniversary."],"A:B":["Funny rhymes for you. {partner} expected drama.","They''re ready to cry. You hand them a limerick.","Honestly, laughing is romantic too. Ask any comedian''s partner."],"A:C":["Three words for you. {partner} expected drama.","They were ready for an epic. You drop three words and leave.","Mic drop. Legendary poet energy."],"B:A":["Deep and dramatic for you. {partner} expected silly rhymes.","They''re ready to giggle. You hand them seven stanzas of feelings.","They''ll be crying by stanza two. Bring tissues."],"B:B":["Funny rhymes, and {partner} called it.","They''re already bracing for ''roses are red, you''re my bread.''","Honestly, rhyme-based love is underrated."],"B:C":["Three words for you. {partner} expected funny rhymes.","They wanted ''moon'' and ''June.'' You gave them pure sincerity.","Somehow that''s even more devastating. In a good way."],"C:A":["Deep and dramatic for you. {partner} expected three words.","They think you''re short and sweet. Surprise, you''re a novelist.","Make the last line just three words. Twist ending."],"C:B":["Funny rhymes for you. {partner} expected three words.","They''re expecting a short line. You bring a whole rap.","Bonus content. They''ll memorize it."],"C:C":["Three words, and {partner} knew it.","They know you''d say everything in a single line.","And it would hit harder than any epic poem. Unfair."]}}'::jsonb),
('TW-V20','adventure_friend_tw','Guess','{"id":"TW-V20","friendId":"adventure_friend_tw","type":"Guess","scene":"Twig closes her eyes and puckers, then opens them, horrified that you saw.","lines":["I was stretching my face. Face yoga. It''s a thing!"],"question":"How would your partner react to a surprise kiss?","selfQuestion":"How would you react to a surprise kiss?","choices":[{"id":"A","label":"Melts instantly","reply":["Melts instantly. A puddle. A soft puddle.","Knees gone. Brain gone. Smile stays."]},{"id":"B","label":"Acts shocked, then kisses back","reply":["Fake shock, then kisses back. Main character move.","Dramatic gasp, then romance."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You''d melt instantly, and {partner} knew.","They know you''re a marshmallow pretending to be a person.","Surprise them back sometime. Turnabout is cute."],"A:B":["You''d act shocked first. {partner} expected you to melt.","They''ll think they messed up. Then you kiss back. Twist.","Don''t leave them hanging too long. Three seconds max."],"B:A":["You''d melt. {partner} expected fake shock first.","They''re ready for drama. You just turn into soup.","That''s even better. Seriously. Nice weather."],"B:B":["Fake shock then kiss back, and {partner} knew.","They''re expecting the gasp. They secretly live for it.","The drama is part of the charm. Never stop."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_hz','["Okay, so, I’ve blocked out the next hour to wait for {partner}. It’s in my planner.","Okay, so, I reorganized your shelf while waiting for {partner}. You’re welcome."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('HZ-V01','adventure_friend_hz','Trivia','{"id":"HZ-V01","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel bursts in with a clipboard, three pens behind her ear, and acorn crumbs on her cheek.","lines":["Okay, so, I have a question. Color-coded. Laminated. Let''s go."],"question":"What happens to many of the nuts squirrels bury and then forget?","selfQuestion":null,"choices":[{"id":"A","label":"They grow into new trees","reply":["YES. We''re accidental gardeners!","Forgotten acorns and nuts sprout, so squirrels help forests spread.","My ''forgetfulness'' is a public service. Please tell Walnut."]},{"id":"B","label":"They rot and disappear","reply":["Some do! But that''s not the plot twist.","Lots of forgotten nuts sprout and grow into brand-new trees.","Squirrels accidentally plant forests. Biggest flex in nature."]},{"id":"C","label":"Other squirrels steal every single one","reply":["Theft does happen. Rude. I keep a list.","But plenty of forgotten nuts grow into new trees.","So every lost snack is a tiny tree in disguise."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Squirrels'' uneaten cached nuts can germinate, aiding tree dispersal.","coupleReplies":{}}'::jsonb),
('HZ-V02','adventure_friend_hz','Trivia','{"id":"HZ-V02","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel holds up a single lotus seed like a priceless gem.","lines":["Okay, so, talk about long-term storage. This beats my pantry."],"question":"About how old was the oldest lotus seed that still sprouted?","selfQuestion":null,"choices":[{"id":"A","label":"About 13 years old","reply":["Way older! Like, history-book older.","A sacred lotus seed around 1,300 years old was successfully sprouted.","Patience. Tough shell. Great storage."]},{"id":"B","label":"About 13 days old","reply":["That''s just a regular seed, babe.","An ancient lotus seed about 1,300 years old still sprouted.","Talk about waiting for the right moment."]},{"id":"C","label":"About 1,300 years old","reply":["YES. Okay, so, 1,300 years. In storage. Then sprouted.","Scientists germinated ancient sacred lotus seeds from a dried lakebed.","Best shelf life ever. I''m rethinking my expiration labels."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Sacred lotus seeds ~1,300 years old from China were germinated (Shen-Miller et al.).","coupleReplies":{}}'::jsonb),
('HZ-V03','adventure_friend_hz','Trivia','{"id":"HZ-V03","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel pins a photo of a tree full of tiny holes onto your fridge, very reverently.","lines":["This is my vision board. Storage goals."],"question":"What does an acorn woodpecker do with its acorns?","selfQuestion":null,"choices":[{"id":"A","label":"Throws them at squirrels","reply":["Honestly? Possible. But no.","They drill holes in trees and store one acorn per hole.","Some trees hold tens of thousands. My dream pantry."]},{"id":"B","label":"Eats them all immediately","reply":["No planning?! Chaos!","They drill holes and store acorns in special ''granary'' trees.","Every acorn gets its own hole. Peak organization."]},{"id":"C","label":"Drills holes and stores one acorn in each","reply":["YES. A whole granary tree!","They drill thousands of holes and wedge one acorn into each.","One acorn, one hole. Organized. Labeled. Beautiful. I''m emotional."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Acorn woodpeckers store acorns in individually drilled holes in granary trees.","coupleReplies":{}}'::jsonb),
('HZ-V04','adventure_friend_hz','Trivia','{"id":"HZ-V04","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel shows you a video of ants carrying leaf pieces in a long line.","lines":["Okay, so, they''re not eating those leaves. They''re farming. With them."],"question":"What do leafcutter ants do with the leaves they carry?","selfQuestion":null,"choices":[{"id":"A","label":"Build tiny umbrellas","reply":["Okay, so, cute. Wrong.","They use the leaves to grow fungus gardens for food.","Agriculture before humans. Show-offs."]},{"id":"B","label":"Use them to grow fungus gardens they eat","reply":["YES. Okay, so, ants are farmers!","They chew leaves into compost to grow a special fungus, then eat the fungus.","Underground farms with job roles. My dream spreadsheet."]},{"id":"C","label":"Eat them right away","reply":["Okay, so, they can''t digest them well.","They feed the leaves to fungus gardens, then eat the fungus.","Farmers. With very organized teams."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Leafcutter ants cultivate fungus on harvested leaf material.","coupleReplies":{}}'::jsonb),
('HZ-V05','adventure_friend_hz','Trivia','{"id":"HZ-V05","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel unrolls a map covered in thousands of tiny dots.","lines":["Memory question. I''m VERY competitive about this one."],"question":"About how many seed stashes can a Clark''s nutcracker bird remember?","selfQuestion":null,"choices":[{"id":"A","label":"Thousands","reply":["YES. Thousands!","They hide seeds in thousands of spots and find many again months later.","Living spreadsheet. A bird after my own heart."]},{"id":"B","label":"About ten","reply":["Way, way more!","Clark''s nutcrackers remember thousands of hiding spots.","Months later, under snow, they still find many of them."]},{"id":"C","label":"None, they just guess","reply":["That''s my method. Not theirs.","They can remember thousands of seed stashes.","Elite memory. I''m a little jealous. Okay, a lot."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Clark''s nutcrackers cache seeds in thousands of sites and recall many of them.","coupleReplies":{}}'::jsonb),
('HZ-V06','adventure_friend_hz','Trivia','{"id":"HZ-V06","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel turns off your lights and clicks on a tiny purple flashlight.","lines":["Spooky science time!"],"question":"What surprising thing do flying squirrels do under UV light?","selfQuestion":null,"choices":[{"id":"A","label":"Turn invisible","reply":["Imagine! But no.","They actually glow pink under ultraviolet light.","Scientists found it by accident. Best accident ever."]},{"id":"B","label":"Glow pink","reply":["YES. Pink!! I''m obsessed.","North American flying squirrels glow pink under UV light.","Nobody knows exactly why yet. Mysterious, sparkly queens."]},{"id":"C","label":"Glow green like a glow stick","reply":["Close! Wrong color.","They glow pink under UV. Hot pink fluff.","Discovered by accident with a UV flashlight. Very rave."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"North American flying squirrels fluoresce pink under UV light.","coupleReplies":{}}'::jsonb),
('HZ-V07','adventure_friend_hz','Trivia','{"id":"HZ-V07","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel pats an imaginary pocket under her arm.","lines":["Okay, so, sea otters have a storage system. I''m jealous."],"question":"Where do sea otters keep their favorite rock?","selfQuestion":null,"choices":[{"id":"A","label":"In a pocket of loose skin under their arm","reply":["YES. A built-in pocket! Okay, so, iconic.","They store food and a favorite rock to crack shellfish open.","Some keep the same rock for a long time. A beloved tool."]},{"id":"B","label":"They bury it on the beach","reply":["Okay, so, then they''d lose it. Like me with keys.","They keep it in a loose skin pocket under their forearm.","Pocket plus tool. Organized otter."]},{"id":"C","label":"They hold it in their mouth all day","reply":["Okay, so, then how would they eat?","There''s a loose skin pouch under each forearm for food and rocks.","A natural fanny pack. I need one."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Sea otters have loose skin pouches under forelegs for storing food and tools.","coupleReplies":{}}'::jsonb),
('HZ-V08','adventure_friend_hz','Trivia','{"id":"HZ-V08","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel dumps a huge pile of acorns on your table, then places one lonely acorn next to it.","lines":["See the difference? Big years and small years."],"question":"What''s a ''mast year'' for oak trees?","selfQuestion":null,"choices":[{"id":"A","label":"A year they don''t grow at all","reply":["The opposite, actually!","A mast year is when oaks drop way more acorns than usual.","Squirrel Christmas. I make a chart every time."]},{"id":"B","label":"A year they grow sideways","reply":["Trees aren''t THAT chaotic.","It''s when oaks produce a huge acorn crop all at once.","Lots of trees do it together. Very coordinated. Very group project."]},{"id":"C","label":"A year they drop way more acorns than usual","reply":["YES. Acorn jackpot!","Oaks across an area produce a huge crop at the same time.","Walnut and I stock up. I have a color code for this."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Mast years: synchronized heavy seed production in oaks.","coupleReplies":{}}'::jsonb),
('HZ-V09','adventure_friend_hz','Trivia','{"id":"HZ-V09","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel drops an apple into a bowl of water. It bobs up immediately.","lines":["Okay, so, it floats! I tested four apples. And a pear. The pear sank."],"question":"Why do apples float in water?","selfQuestion":null,"choices":[{"id":"A","label":"They''re coated in wax","reply":["Okay, so, wax doesn''t make things float.","Apples are about 25% air, so they''re less dense than water.","Built-in pool floatie."]},{"id":"B","label":"They''re about a quarter air","reply":["YES. About 25% air! Okay, so, natural floaties.","Air pockets between cells make them less dense than water.","Hence bobbing for apples. Very scientific party game."]},{"id":"C","label":"They''re secretly hollow","reply":["Okay, so, not hollow. Just airy.","Around a quarter of an apple''s volume is air.","Less dense than water. Up it goes."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Apples are roughly 20–25% air by volume and float.","coupleReplies":{}}'::jsonb),
('HZ-V10','adventure_friend_hz','Trivia','{"id":"HZ-V10","friendId":"adventure_friend_hz","type":"Trivia","scene":"Hazel asks you to hold her clipboard. Then smiles like she won something.","lines":["Okay, so, you just did me a favor. Now you like me more. Science."],"question":"What''s the ''Ben Franklin effect''?","selfQuestion":null,"choices":[{"id":"A","label":"Flying a kite in a storm","reply":["Okay, so, that''s a different Franklin story.","It''s when doing someone a favor makes you like them more.","Ask your partner for small favors. It''s a love hack."]},{"id":"B","label":"Doing someone a favor can make you like them more","reply":["YES. Okay, so, asking for help builds connection!","Franklin wrote about borrowing a rival''s book and becoming friends.","I ask Walnut to help assemble furniture. Strategic. Romantic."]},{"id":"C","label":"Saving money makes you happy","reply":["Okay, so, ''a penny saved'' is also him, but no.","Doing a favor for someone can increase how much you like them.","Small asks, big closeness."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"The Ben Franklin effect: doing someone a favor can increase liking for them.","coupleReplies":{}}'::jsonb),
('HZ-V11','adventure_friend_hz','Preference','{"id":"HZ-V11","friendId":"adventure_friend_hz","type":"Preference","scene":"Hazel unrolls a chore chart that reaches the floor. And keeps going.","lines":["Okay, so, Walnut and I just moved in. I made a chart. He made a face."],"question":"Splitting chores: a detailed chart, or just vibe it out?","selfQuestion":null,"choices":[{"id":"A","label":"Detailed chart","reply":["A chart?! You''re my soulmate.","Color-coded. Laminated. Stickers when done."]},{"id":"B","label":"Just vibe it","reply":["Just vibe it. That genuinely scares me.","But respect. Free spirits keep the world balanced."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Charts for both of you. Power couple energy.","I bet you and {partner} have a shared calendar with matching emojis.","Send me your template. Please. I''m begging. I''ll trade acorns."],"A:B":["Vibes for you. {partner} wants a chart.","Fair warning: they''re probably color-coding you right now.","Let them. Then claim the fun chores before the chart goes live."],"B:A":["Chart for you. {partner} would rather vibe it out.","Give them three tasks. Big font. Absolutely no color legend.","Let them check one box. Watch them get hooked. It''s a gateway."],"B:B":["You both just vibe it. Wow. How.","So you and {partner} just... wash dishes when they''re dirty? Without a system?","Teach me slowly. I need to take notes on this."]}}'::jsonb),
('HZ-V12','adventure_friend_hz','Preference','{"id":"HZ-V12","friendId":"adventure_friend_hz","type":"Preference","scene":"Hazel waves a grocery list that''s double-sided and sorted by aisle.","lines":["It''s alphabetized within each aisle. Don''t laugh."],"question":"Grocery shopping: strict list, or wander and grab?","selfQuestion":null,"choices":[{"id":"A","label":"Strict list","reply":["Strict list. In and out in 14 minutes. Love.","Budget intact. Dignity intact."]},{"id":"B","label":"Wander and grab","reply":["Wander and grab. Adventure mode.","Suddenly you own three kinds of cheese and a candle."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Strict lists for both of you. Efficient love.","So you and {partner} probably split the list and race each other.","Grocery speedrun. Honestly, date idea."],"A:B":["Wander for you. {partner} brings the list.","They hold the list. You hold the surprise cheese.","That''s balance. Delicious, slightly-over-budget balance."],"B:A":["List for you. {partner} wants to wander.","You''ll finish in ten minutes. They''ll still be in the snack aisle, inspired.","Give them one ''free pick'' per trip. Treat budget. Everyone''s happy."],"B:B":["Wanderers, both of you. Snack chaos.","Honestly, you and {partner} came in for milk and left with a plant and four dips.","Honestly? That''s the fun part. Keep wandering."]}}'::jsonb),
('HZ-V13','adventure_friend_hz','Preference','{"id":"HZ-V13","friendId":"adventure_friend_hz","type":"Preference","scene":"Hazel holds up three paint swatches and looks deeply overwhelmed.","lines":["I have seven Pinterest boards. They''re fighting."],"question":"Moving in together: which room do you decorate first?","selfQuestion":null,"choices":[{"id":"A","label":"Bedroom","reply":["Bedroom. Sleep is a priority. Correct.","Good sheets, soft lights, done."]},{"id":"B","label":"Kitchen","reply":["Kitchen. Snacks are a priority. Also correct.","Spice rack first. Personality second."]},{"id":"C","label":"Living room","reply":["Living room. Hosting energy.","Couch first, guest list second."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Bedroom for both of you. A nap-first couple.","I can picture it: you and {partner} agree that comfort comes before everything.","Fluffy pillows forever. I approve this budget line."],"A:B":["Kitchen for you. {partner} wants the bedroom.","Snacks versus sleep. The eternal debate.","Snacks in bed. Crumbs are a small price for peace."],"A:C":["Living room for you. {partner} wants the bedroom.","You want people over. They want to never leave bed.","Host early, kick everyone out by nine. Everyone wins."],"B:A":["Bedroom for you. {partner} wants the kitchen first.","Easy compromise: breakfast in bed.","Both rooms, one plan. I''m proud of this solution."],"B:B":["Kitchen for both of you. Food is love.","Pretty sure you and {partner} would build your whole home around the snack shelf.","Honestly, the best homes smell like garlic."],"B:C":["Living room for you. {partner} wants the kitchen.","So you''ll host, and they''ll feed everyone. A team.","Movie nights, sorted. I''ll take popcorn duty."],"C:A":["Bedroom for you. {partner} wants the living room.","You want rest. They want guests. Classic split.","Do the bedroom first, then host a housewarming. In that order."],"C:B":["Kitchen for you. {partner} wants the living room.","That''s basically a dinner party already.","Cook in one room, eat in the other. Invite me. Kidding. Unless?"],"C:C":["Living room for both of you. Host mode.","Lowkey, you and {partner} want the couch ready before the bed is even built.","Game nights incoming. Invite me. I''ll bring a scoreboard."]}}'::jsonb),
('HZ-V14','adventure_friend_hz','Preference','{"id":"HZ-V14","friendId":"adventure_friend_hz","type":"Preference","scene":"Hazel opens a spreadsheet titled ''OUR MONEY (draft 6)''. Draft 6.","lines":["Money talk. Calm. Breathing."],"question":"Paying for shared stuff: one shared account, or split every bill?","selfQuestion":null,"choices":[{"id":"A","label":"One shared account","reply":["Shared account. Team mode. Big trust.","One pot. One plan. No receipts drama."]},{"id":"B","label":"Split every bill","reply":["Split every bill. Clear and fair.","My spreadsheet just blushed."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Shared account for both of you. Fully merged.","That''s a big step for you and {partner}. Proud of you two.","Remember to set a snack budget. Very important."],"A:B":["You''d split bills. {partner} wants a shared account.","They''re ready to merge. You need a minute. Valid.","Start with one shared fund. Like ''date nights.'' Fun money first."],"B:A":["You''d go joint. {partner} prefers splitting bills.","Try a shared account just for rent and groceries.","Small merge first. Big merge later. Very healthy."],"B:B":["Split every bill, both of you. Clean and fair.","You and {partner} have zero ''who paid for what'' drama.","My spreadsheet salutes you. It''s wearing a tiny hat."]}}'::jsonb),
('HZ-V15','adventure_friend_hz','Preference','{"id":"HZ-V15","friendId":"adventure_friend_hz","type":"Preference","scene":"Hazel holds a feather duster in one paw and a vacuum in the other.","lines":["Walnut and I disagree on this. I''m right."],"question":"Cleaning: a little bit every day, or one big Sunday clean?","selfQuestion":null,"choices":[{"id":"A","label":"A little every day","reply":["A little every day. Never overwhelmed. Iconic.","Five minutes a day keeps the chaos away."]},{"id":"B","label":"One big Sunday clean","reply":["Big Sunday clean. Power hour.","Playlist on, mess gone, smug all evening."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Little-every-day for both of you. Spotless.","So you and {partner} have never seen a pile in your lives.","Please come explain this to Walnut. Slowly."],"A:B":["Sunday clean for you. {partner} tidies every day.","They''ll handle the little stuff. You bring the big Sunday energy.","Honestly a perfect system. I''m writing it down."],"B:A":["You tidy daily. {partner} saves it all for Sunday.","You''ll pick things up while they pile things up. Hmm.","Agree on one zone that stays clean always. The rest can wait."],"B:B":["Sunday clean for both of you. Cleaning party.","Honestly, you and {partner} blast music and scrub like it''s a concert.","Fun AND productive. Who knew."]}}'::jsonb),
('HZ-V16','adventure_friend_hz','Guess','{"id":"HZ-V16","friendId":"adventure_friend_hz","type":"Guess","scene":"Hazel opens your junk drawer, gasps quietly, and closes it again.","lines":["No judgment. Some judgment."],"question":"What does your partner''s ''organized'' drawer actually look like?","selfQuestion":"What does your ''organized'' drawer actually look like?","choices":[{"id":"A","label":"Labeled perfection","reply":["Labeled perfection? Marry them again.","Label maker owners are rare and precious."]},{"id":"B","label":"Total chaos with a lid","reply":["Chaos with a lid. Relatable.","Batteries, rubber bands, and three mystery keys."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Labeled perfection, and {partner} knew it.","They''ve watched you label the label maker.","I''m so jealous. Can I see it? Can I touch it?"],"A:B":["Chaos with a lid. {partner} believed in your organization.","They''re going to open it and lose faith.","Hide it. Or let me help. I''m already reaching for labels."],"B:A":["Your drawer is perfect. {partner} expected chaos.","They underestimated your inner organizer.","Open it dramatically in front of them. Let them gasp."],"B:B":["Chaos with a lid, and {partner} knew it.","They''ve opened it once. Quietly closed it. Never spoke of it.","At least it closes. That''s something."]}}'::jsonb),
('HZ-V17','adventure_friend_hz','Guess','{"id":"HZ-V17","friendId":"adventure_friend_hz","type":"Guess","scene":"Hazel holds up a cracked mug and looks at it lovingly.","lines":["Sentimental clutter question. I have a box of ''important'' bottle caps."],"question":"When moving, what would your partner refuse to throw away?","selfQuestion":"When moving, what would you refuse to throw away?","choices":[{"id":"A","label":"Old concert tickets","reply":["Concert tickets. A memory keeper.","Proof they were there, screaming lyrics."]},{"id":"B","label":"A broken but beloved mug","reply":["The broken mug. Emotional support ceramic.","It doesn''t hold coffee. It holds feelings."]},{"id":"C","label":"A suspicious amount of cables","reply":["The cables. Classic.","For devices that haven''t existed since 2014."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Concert tickets, and {partner} knew it.","They''ve seen the shoebox. They respect the shoebox.","Frame your favorites. Wall of memories."],"A:B":["The mug for you. {partner} guessed tickets.","They think it''s all about concerts. It''s about that one mug.","Tell them the mug''s origin story. It deserves to be heard."],"A:C":["Cables for you. {partner} guessed tickets.","They think you''re sentimental. You''re just ''prepared.''","For what? Nobody knows. Not even you."],"B:A":["Tickets for you. {partner} guessed the mug.","They think you''re sentimental about dishes. You''re sentimental about nights out.","Show them the ticket box. Tell one story per ticket."],"B:B":["The broken mug, and {partner} knew it.","They''ve watched you rescue it from the trash twice.","Turn it into a plant pot. Second life, same love."],"B:C":["Cables for you. {partner} guessed the mug.","They think you keep things for feelings. You keep them ''just in case.''","Label the cable box. At least make the chaos official."],"C:A":["Tickets for you. {partner} guessed cables.","They think you hoard tech. You hoard memories.","Very different. Much cuter."],"C:B":["The mug for you. {partner} guessed cables.","They have no idea about your emotional mug bond.","Introduce them properly. Mug, meet {partner}."],"C:C":["The cable box, and {partner} knew it.","They fear the box. Everyone fears the box.","Just toss one cable. One. As a treat."]}}'::jsonb),
('HZ-V18','adventure_friend_hz','Guess','{"id":"HZ-V18","friendId":"adventure_friend_hz","type":"Guess","scene":"Hazel reorganizes your dishwasher, then steps back like it''s an art piece.","lines":["There IS a right way."],"question":"How does your partner load the dishwasher?","selfQuestion":"How do you load the dishwasher?","choices":[{"id":"A","label":"Tetris-level precision","reply":["Tetris precision. A rare genius.","Every plate facing the same direction. Chills."]},{"id":"B","label":"Throw it in and pray","reply":["Throw it in and pray. Brave.","Somehow it still comes out clean. Mostly."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Tetris precision, and {partner} knew.","They''ve caught you secretly reloading their dishes.","Gently stop. Or teach them. Kindly. With diagrams."],"A:B":["Throw and pray for you. {partner} guessed precision.","They believed in you. They thought you were a Tetris person.","Next time, close the door fast. Hide the evidence."],"B:A":["Precision for you. {partner} guessed throw and pray.","They have no idea about your plate-alignment skills.","Do a full demo. They''ll never unsee the beauty."],"B:B":["Throw and pray, and {partner} knew it.","They''ve made peace with the bowl on the top rack sideways.","Honestly, the dishwasher believes in you."]}}'::jsonb),
('HZ-V19','adventure_friend_hz','Guess','{"id":"HZ-V19","friendId":"adventure_friend_hz","type":"Guess","scene":"Hazel holds a three-page packing list for a two-day trip.","lines":["It''s thorough. It has a table of contents."],"question":"How does your partner pack for a weekend trip?","selfQuestion":"How do you pack for a weekend trip?","choices":[{"id":"A","label":"Two days early, with a checklist","reply":["Early with a checklist. My hero.","Socks counted. Twice."]},{"id":"B","label":"Ten minutes before, forgets socks","reply":["Ten minutes before. Chaos.","Socks? Who needs socks?"]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Early checklist, and {partner} knew.","They''ve seen your list. Maybe they''re on it.","Pack theirs too. It''s an act of love."],"A:B":["Last-minute for you. {partner} thought you''d have a checklist.","They believed in you. Sock-less, you''ve let them down.","Socks first next time. Always. Write it on your hand."],"B:A":["Early checklist for you. {partner} expected last-minute chaos.","They''re about to be shocked by your preparedness.","Hand them your list. Watch them get emotional."],"B:B":["Last-minute chaos, and {partner} knew.","They secretly pack extra socks for you. Every trip.","That''s love. Sock-shaped love."]}}'::jsonb),
('HZ-V20','adventure_friend_hz','Guess','{"id":"HZ-V20","friendId":"adventure_friend_hz","type":"Guess","scene":"Hazel finally sits still on your couch. For about four seconds.","lines":["Calm question for once. Saturday mornings."],"question":"What''s your partner''s ideal Saturday morning at home?","selfQuestion":"What''s your ideal Saturday morning at home?","choices":[{"id":"A","label":"Farmers market and errands","reply":["Farmers market and errands. Productive queen.","Berries, tote bag, to-do list."]},{"id":"B","label":"Pancakes and pajamas till noon","reply":["Pancakes and pajamas. Sacred.","No plans. Just syrup."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Farmers market, and {partner} knew it.","They know you like a productive morning. With a tote bag.","Grab them a peach. Love language."],"A:B":["Pancakes for you. {partner} thought you''d be at the market.","They imagined you productive. You chose pajamas.","Market next week. Syrup now. Priorities."],"B:A":["Farmers market for you. {partner} thought you''d sleep in.","Surprise! You''re up and buying zucchini.","Bring pancakes home after. Everyone wins."],"B:B":["Pancakes and pajamas, and {partner} knew it.","They know slow mornings are your religion.","Extra syrup. Non-negotiable."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_bc','["What time does {partner} get back? I’ll wait. I’m really good at waiting.","I’ll just keep checking the clock till {partner} gets here. Old habit."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('BC-V01','adventure_friend_bc','Trivia','{"id":"BC-V01","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit pops up through your floor wearing two watches, one on each wrist.","lines":["Hi! One''s my time, one''s Pip''s time. What time is it there? Oh, right, here. Quiz!"],"question":"What''s Groundhog Day all about?","selfQuestion":null,"choices":[{"id":"A","label":"Groundhogs get the day off work","reply":["I wish! Pip says I deserve it.","The legend says if a groundhog sees its shadow, six more weeks of winter.","Every February 2. Very dramatic. Mostly inaccurate."]},{"id":"B","label":"Everyone has to dig a hole","reply":["That would be my favorite holiday.","It''s actually about the groundhog''s shadow predicting winter''s length.","Sees shadow, six more weeks of winter. Doesn''t, early spring."]},{"id":"C","label":"If a groundhog sees its shadow, six more weeks of winter","reply":["Yes! That''s the legend. Every February 2.","No shadow means an early spring. Shadow means more winter.","Spoiler: groundhogs are not great forecasters. We try, though."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Groundhog Day (Feb 2): shadow means six more weeks of winter per folklore.","coupleReplies":{}}'::jsonb),
('BC-V02','adventure_friend_bc','Trivia','{"id":"BC-V02","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit holds up a photo of a salmon leaping up a waterfall, and sniffles.","lines":["They go home no matter what. I relate. Pip''s home is very far."],"question":"How do salmon find their way back to the stream where they were born?","selfQuestion":null,"choices":[{"id":"A","label":"By reading river signs","reply":["Ha! Cute! No signs underwater.","They mainly follow the unique smell of their home stream.","Years later, across an ocean. Still remember. Wow."]},{"id":"B","label":"They just follow the biggest fish","reply":["Ha! Follow the leader? Not quite.","Salmon use smell to recognize their birth stream.","They likely use magnetic cues out at sea, then smell near home."]},{"id":"C","label":"Mostly by smell","reply":["Yes! They sniff their way home!","Each stream has its own scent, and salmon remember it from when they were tiny.","Pip''s hoodie smells like home to me. Same principle."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Salmon use olfactory imprinting (and likely geomagnetic cues) to return to natal streams.","coupleReplies":{}}'::jsonb),
('BC-V03','adventure_friend_bc','Trivia','{"id":"BC-V03","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit traces a long line across a map, from one pole to the other.","lines":["This bird does more long distance than me and Pip."],"question":"Which bird has the longest migration of any animal?","selfQuestion":null,"choices":[{"id":"A","label":"The bald eagle","reply":["Majestic, but not the champion.","The Arctic tern wins. Pole to pole every year.","Over 40,000 miles a year. Respect."]},{"id":"B","label":"The Arctic tern","reply":["Yes! Pole to pole!","It flies between the Arctic and Antarctic, tens of thousands of miles a year.","And I thought my flights to see Pip were long."]},{"id":"C","label":"The penguin","reply":["Penguins can''t fly!","It''s the Arctic tern. It flies pole to pole every year.","Endless summer. Endless travel."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Arctic terns migrate between Arctic and Antarctic, ~70,000 km/year.","coupleReplies":{}}'::jsonb),
('BC-V04','adventure_friend_bc','Trivia','{"id":"BC-V04","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit hugs her knees, looking at her phone. No new messages. Time zones.","lines":["Missing someone hurts. Like, actually. Science agrees."],"question":"What did researchers find about the pain of feeling left out or lonely?","selfQuestion":null,"choices":[{"id":"A","label":"It activates brain areas linked to physical pain","reply":["Yes. Social pain overlaps with physical pain in the brain.","Feeling excluded lit up some of the same regions as physical hurt.","So missing Pip is basically a stubbed toe of the heart. Real."]},{"id":"B","label":"It only affects your mood, not your brain","reply":["It goes deeper than mood.","Studies found overlap with brain areas involved in physical pain.","Being left out really hurts. Literally."]},{"id":"C","label":"It makes you better at math","reply":["Ha! I wish. Then I''d be a genius.","It activates brain regions also involved in physical pain.","Be gentle with lonely hearts. Including yours."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Eisenberger et al. (2003): social exclusion engaged regions associated with physical pain (dACC).","coupleReplies":{}}'::jsonb),
('BC-V05','adventure_friend_bc','Trivia','{"id":"BC-V05","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit holds an orange butterfly sticker against the window.","lines":["This one makes me cry a little."],"question":"How do monarch butterflies complete their long migration?","selfQuestion":null,"choices":[{"id":"A","label":"One butterfly makes the whole round trip","reply":["Not quite!","It takes several generations to make the full round trip.","The great-grandkids finish the journey. Love that."]},{"id":"B","label":"It takes several generations","reply":["Yes! Family relay!","The return trip is a relay across several generations.","Great-grandkids finish the journey. Legacy love."]},{"id":"C","label":"They hitch a ride on birds","reply":["Ha! Cute. No.","The migration takes several generations to complete.","A relay race, butterfly-style."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Monarch migration spans multiple generations.","coupleReplies":{}}'::jsonb),
('BC-V06','adventure_friend_bc','Trivia','{"id":"BC-V06","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit puts her paw on her chest, feeling her heartbeat, then counts slowly.","lines":["Long-distance hearts beat slower when we''re apart. Kidding."],"question":"What happens to a groundhog''s heartbeat during hibernation?","selfQuestion":null,"choices":[{"id":"A","label":"It slows way down","reply":["Yes! Like, way down.","From around 80 beats per minute to about 5.","Imagine sleeping through the whole winter. Pip would miss me so much."]},{"id":"B","label":"It speeds up to stay warm","reply":["Nope, the opposite!","It drops from around 80 beats a minute to about 5.","Body temp drops too. Super deep sleep mode."]},{"id":"C","label":"It stops completely","reply":["That would be scary! No.","It slows from around 80 to about 5 beats per minute.","Barely ticking. Energy-saving queen."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Hibernating groundhogs'' heart rate drops from ~80 to ~5 bpm.","coupleReplies":{}}'::jsonb),
('BC-V07','adventure_friend_bc','Trivia','{"id":"BC-V07","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit hums a little tune, pauses, then hums the next part like a reply.","lines":["Pip and I do this on voice notes. It''s our duet. Gibbons do it too!"],"question":"What do many gibbon couples do every morning?","selfQuestion":null,"choices":[{"id":"A","label":"Groom each other''s feet","reply":["Close in affection! Not it.","Gibbon couples sing loud, coordinated duets.","Their songs travel far through the trees. Couple goals."]},{"id":"B","label":"Hide from each other","reply":["Aww, no! The opposite!","Many gibbon pairs sing morning duets together.","The duet tells the forest: we''re a team."]},{"id":"C","label":"Sing duets together","reply":["Yes! Morning love songs!","Gibbon pairs sing coordinated duets that can be heard far through the forest.","Long-distance love language. I''m emotional."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Many gibbon species'' mated pairs sing coordinated duets.","coupleReplies":{}}'::jsonb),
('BC-V08','adventure_friend_bc','Trivia','{"id":"BC-V08","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit cups her paws around her mouth and makes a low humming sound.","lines":["Long-distance calls, ocean edition!"],"question":"How far can some blue whale calls travel underwater?","selfQuestion":null,"choices":[{"id":"A","label":"About one mile","reply":["Way farther!","Blue whale calls can travel hundreds of miles underwater.","Deep, low sounds go really far."]},{"id":"B","label":"Hundreds of miles","reply":["Yes! Hundreds of miles!","Low-frequency whale calls can carry hundreds of miles underwater.","The original long-distance call. No roaming fees."]},{"id":"C","label":"Only across one pond","reply":["Ha! Whales don''t live in ponds.","Their calls travel hundreds of miles underwater.","The ocean is their phone line."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Low-frequency blue whale calls can travel hundreds of km underwater.","coupleReplies":{}}'::jsonb),
('BC-V09','adventure_friend_bc','Trivia','{"id":"BC-V09","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit points at a pale flower in a photo, then checks both her watches.","lines":["This flower is only open for one day. Talk about timing."],"question":"How long does a vanilla orchid flower usually stay open?","selfQuestion":null,"choices":[{"id":"A","label":"About one month","reply":["Way shorter!","Each flower opens for about a day.","Farmers hand-pollinate them fast. Vanilla is a labor of love."]},{"id":"B","label":"About one day","reply":["Yes. Just one day!","Outside its native Mexico, it usually has to be pollinated by hand.","One-day chance. Like catching Pip when he''s awake. Precious."]},{"id":"C","label":"Forever","reply":["Aww, I wish!","Each flower usually lasts about a day.","That''s why vanilla is so expensive. Precious timing."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Vanilla orchid flowers typically open for ~1 day; outside Mexico they''re hand-pollinated.","coupleReplies":{}}'::jsonb),
('BC-V10','adventure_friend_bc','Trivia','{"id":"BC-V10","friendId":"adventure_friend_bc","type":"Trivia","scene":"Biscuit waves at a crow outside your window. It caws back.","lines":["That one knows me. Seriously. Crows remember faces!"],"question":"What can crows remember about humans?","selfQuestion":null,"choices":[{"id":"A","label":"Faces, especially of people who treated them badly","reply":["Yes! They remember faces for years!","Crows can even teach other crows which humans to avoid.","Be nice to crows. They have a group chat about you."]},{"id":"B","label":"Only their names","reply":["Crows don''t do names. They do faces.","They recognize individual human faces for years.","And share warnings with other crows. Wild."]},{"id":"C","label":"Nothing, they forget instantly","reply":["Oh no, they remember everything!","Crows recognize individual faces and remember for years.","Their friends learn your face too. Be kind."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"American crows remember threatening human faces and transmit this socially (Marzluff et al.).","coupleReplies":{}}'::jsonb),
('BC-V11','adventure_friend_bc','Preference','{"id":"BC-V11","friendId":"adventure_friend_bc","type":"Preference","scene":"Biscuit holds her phone at arm''s length, practicing her video-call smile.","lines":["Call with Pip in an hour. It''s 6 a.m. for him. What time is it there? Oh. Here."],"question":"Missing each other: video call, or voice note?","selfQuestion":null,"choices":[{"id":"A","label":"Video call","reply":["Video call! Seeing their face is everything.","Even when the Wi-Fi freezes them mid-sneeze."]},{"id":"B","label":"Voice note","reply":["Voice note. Cozy, personal, replayable.","Listening to one 14 times is totally normal. I checked."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Video calls for both of you. Face-to-face people.","I bet you and {partner} have fallen asleep on a call at least once.","Pip and I do that. He snores. I keep the call on anyway."],"A:B":["Voice notes for you. {partner} wants a video call.","They miss your face. Like, your actual face. That''s sweet.","Pick a ''face day'' each week. The rest can be voice notes."],"B:A":["Video for you. {partner} prefers voice notes.","So you want their face and they want your voice on repeat.","Trade: one call for every three voice notes. Very fair. Very cute."],"B:B":["Voice notes for both of you. Little audio love letters.","So you and {partner} basically have a private podcast about each other.","Save the best ones in a folder. Future you will thank you."]}}'::jsonb),
('BC-V12','adventure_friend_bc','Preference','{"id":"BC-V12","friendId":"adventure_friend_bc","type":"Preference","scene":"Biscuit checks both watches, then softly hums a lullaby.","lines":["It''s bedtime for Pip right now. My bedtime is in four hours."],"question":"Goodnight ritual: a call, a song, or a ''sleep well'' text?","selfQuestion":null,"choices":[{"id":"A","label":"A call","reply":["A call. Their voice is the best lullaby.","Even if it''s 2 a.m. for one of you."]},{"id":"B","label":"A song","reply":["A song. Romantic AND sleepy.","Pip sings off-key on purpose. I think it''s on purpose."]},{"id":"C","label":"A ''sleep well'' text","reply":["A ''sleep well'' text. Short, steady, sweet.","Every night, no matter what. That''s devotion."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Calls for both of you. Voice-before-sleep people.","Honestly, you and {partner} definitely do the ''no, you hang up first'' thing.","Never stop. It''s annoying to everyone else, which is the point."],"A:B":["A song for you. {partner} wants a call.","Sing it on the call. Combo achieved.","Pip would cry. Happy tears. Then fall asleep mid-tear."],"A:C":["A text for you. {partner} wants a call.","They want your voice. You want your pillow. Fair.","Call on Fridays. Text the other nights. Everyone''s happy."],"B:A":["A call for you. {partner} would rather get a song.","So call, and halfway through, ask them to sing.","Or you sing. Badly. They''ll fall asleep laughing."],"B:B":["Songs for both of you. A lullaby couple.","I can picture it: you and {partner} should build a shared goodnight playlist.","Add one song each per week. In a year, it''s your love story."],"B:C":["A text for you. {partner} wants a song.","Text them one line of a song lyric.","Sneaky romance. They''ll hum it all night."],"C:A":["A call for you. {partner} likes a simple ''sleep well'' text.","They text, you call. Double goodnight.","Extra love never hurt anyone. Except my phone bill."],"C:B":["A song for you. {partner} prefers a quick text.","Text them one song link before bed.","Romantic, low effort, zero voice cracks. Perfect."],"C:C":["Texts for both of you. Low-key and lovely.","Pretty sure you and {partner} have never once missed a ''sleep well.''","Consistency is so underrated. It''s basically a love language."]}}'::jsonb),
('BC-V13','adventure_friend_bc','Preference','{"id":"BC-V13","friendId":"adventure_friend_bc","type":"Preference","scene":"Biscuit tapes a box shut with an alarming amount of tape.","lines":["Care package for Pip! Eleven kinds of crackers. He''s going to cry."],"question":"Care package: hometown snacks, or something handmade?","selfQuestion":null,"choices":[{"id":"A","label":"Hometown snacks","reply":["Hometown snacks. A taste of home in a box.","Love you can literally eat."]},{"id":"B","label":"Something handmade","reply":["Something handmade. Heart in a box.","Every crooked stitch says ''I miss you.''"]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Snacks for both of you. A delicious couple.","Lowkey, you and {partner} probably trade snacks like rare treasure.","Add a ranking list. ''Eat this one when you miss me most.''"],"A:B":["Handmade for you. {partner} wants snacks.","Knit them a little snack pouch. Then fill it.","Craft plus crunch. They''ll love both, but mostly the crunch."],"B:A":["Snacks for you. {partner} prefers handmade.","Bake something. Now it''s a snack AND handmade.","Homemade cookies: the long-distance cheat code."],"B:B":["Handmade for both of you. Crafty hearts.","I bet you and {partner} have a whole drawer of each other''s creations.","Never throw any of it away. Even the lumpy ones. Especially those."]}}'::jsonb),
('BC-V14','adventure_friend_bc','Preference','{"id":"BC-V14","friendId":"adventure_friend_bc","type":"Preference","scene":"Biscuit draws an X on a paper calendar. Then another. Then a heart.","lines":["Twelve days till I see Pip. Not that I''m counting. I''m counting."],"question":"Time apart: count down the days, or try not to look?","selfQuestion":null,"choices":[{"id":"A","label":"Count down","reply":["Count down. Every X is a tiny party.","The calendar becomes your best friend."]},{"id":"B","label":"Try not to look","reply":["Don''t look. Time moves faster when you''re not staring.","Very zen. I could never."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["A countdown couple. You both love the calendar.","You and {partner} probably text ''one less day!'' every single morning.","That''s the cutest kind of math."],"A:B":["You don''t look. {partner} counts every day.","They''ll send updates. ''Nine days!'' ''Eight days!''","Reply with a heart each time. That''s their whole morning."],"B:A":["You count down. {partner} tries not to look.","So when they ask ''how long?'', you''ll answer before they finish.","Be their calendar. Send a countdown sticker each day."],"B:B":["You both avoid the calendar. Calm, collected.","So you and {partner} just let the days pass. Then suddenly, reunion!","Honestly, that sounds peaceful. Teach me."]}}'::jsonb),
('BC-V15','adventure_friend_bc','Preference','{"id":"BC-V15","friendId":"adventure_friend_bc","type":"Preference","scene":"Biscuit backs up to your doorway and runs at a couch cushion, arms open.","lines":["Reunion practice! I''m getting good."],"question":"Airport reunion: run and jump into their arms, or play it cool?","selfQuestion":null,"choices":[{"id":"A","label":"Run and jump","reply":["Run and jump! Slow motion! Strangers clap!","Movie scene. You''re the main character."]},{"id":"B","label":"Play it cool","reply":["Play it cool. Then cry in the car.","Classic. Composed outside, puddle inside."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both run and jump. Crash landing incoming.","Honestly, you and {partner} will collide in the middle of arrivals. Gloriously.","Stretch first. Romance is a contact sport."],"A:B":["You play it cool. {partner} runs and jumps.","Brace yourself. They''re coming in at full speed.","Catch them. Your cool act ends right there anyway."],"B:A":["You run and jump. {partner} plays it cool.","They''ll try to look calm. Then you''ll knock them over.","Their cool act lasts about half a second. Worth it."],"B:B":["You both play it cool. Until the car door closes.","I can picture it: you and {partner} nod politely, then sob in the parking lot.","Very real. Very cute. Bring tissues."]}}'::jsonb),
('BC-V16','adventure_friend_bc','Guess','{"id":"BC-V16","friendId":"adventure_friend_bc","type":"Guess","scene":"Biscuit''s phone buzzes: a photo of a cloud. Then a cat. Then a sandwich. No caption.","lines":["Pip sends me everything when he misses me. Even sandwiches."],"question":"When your partner misses you, what do they do?","selfQuestion":"When you miss your partner, what do you do?","choices":[{"id":"A","label":"Sends photos of random things","reply":["Random photos. Love in sandwich form.","Every pic secretly means ''wish you were here.''"]},{"id":"B","label":"Goes quiet and a little mopey","reply":["Quiet and mopey. Aww, soft heart.","Missing someone is heavy. That''s okay."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Random photo spam, and {partner} knew it.","They''ve received at least 47 pictures of clouds from you.","Each cloud is an ''I miss you.'' They know. They save them."],"A:B":["You go quiet. {partner} expected a flood of photos.","They''re refreshing the chat waiting for a random cat pic.","Send one. Even a blurry one. It''ll make their day."],"B:A":["You send random photos. {partner} expected you to go quiet.","They didn''t realize the sandwich pics were love letters.","Tell them. ''Every sandwich means I miss you.'' Life-changing."],"B:B":["Quiet and mopey, and {partner} knew it.","They notice when your texts suddenly get shorter.","Next time, send one hug emoji. It says everything."]}}'::jsonb),
('BC-V17','adventure_friend_bc','Guess','{"id":"BC-V17","friendId":"adventure_friend_bc","type":"Guess","scene":"Biscuit wraps her arms around herself, eyes closed, imagining a very long hug.","lines":["First thing after being apart. I''ve planned mine for weeks."],"question":"After time apart, what''s the first thing your partner wants to do?","selfQuestion":"After time apart, what''s the first thing you want to do?","choices":[{"id":"A","label":"Hug for five full minutes","reply":["A five-minute hug. No talking. Just squeezing.","Time stops. Luggage gets forgotten."]},{"id":"B","label":"Eat a favorite meal together","reply":["Favorite meal. Love tastes like that one dish.","Comfort food reunion. Perfect."]},{"id":"C","label":"Nap together immediately","reply":["Nap together. Travel is exhausting.","Reunite, then recharge."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["A five-minute hug, and {partner} knew it.","They''ll be waiting with open arms and zero plans to let go.","Set a timer. Then ignore the timer."],"A:B":["Meal for you. {partner} guessed a hug.","They''re coming in with open arms. You''re coming in hungry.","Hug first, then eat. Just let the hug happen."],"A:C":["Nap for you. {partner} guessed a hug.","They want five minutes of squeezing. You want five hours of sleep.","Hug while napping. Efficient love."],"B:A":["Hug for you. {partner} guessed a meal.","They''re thinking with their stomach. You''re thinking with your arms.","Hug in the restaurant doorway. Then eat. Everyone wins."],"B:B":["Favorite meal, and {partner} knew it.","They''ve probably already booked the table. Or the takeout.","Reunion dinner. Eat slowly. Stare a lot."],"B:C":["Nap for you. {partner} guessed a meal.","They booked dinner. You booked the pillow.","Nap first, then dinner. Rested and fed. Perfect."],"C:A":["Hug for you. {partner} guessed a nap.","Close! A nap is basically a horizontal hug.","Cuddle nap. Problem solved. You''re welcome."],"C:B":["Meal for you. {partner} guessed a nap.","Eat first, then nap. The perfect food coma.","Honestly, best reunion plan I''ve ever heard."],"C:C":["A nap together, and {partner} knew it.","They''re already fluffing the pillows. Romance.","Sleepy reunion. The most honest kind of love."]}}'::jsonb),
('BC-V18','adventure_friend_bc','Guess','{"id":"BC-V18","friendId":"adventure_friend_bc","type":"Guess","scene":"Biscuit holds her phone too close to her face, then too far, then at a weird upward angle.","lines":["Pip always gets my ceiling fan in the shot."],"question":"What does your partner look like on video calls?","selfQuestion":"What do you look like on video calls?","choices":[{"id":"A","label":"Perfect lighting, cute angle","reply":["Perfect lighting. A professional.","Ring light energy. Very glam."]},{"id":"B","label":"Chin cam, ceiling fan in view","reply":["Chin cam. Iconic.","The ceiling fan is basically part of the relationship now."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Perfect lighting, and {partner} knew it.","You''re a video call pro. They''re very lucky.","Teach them your angles. Or don''t. Keep the advantage."],"A:B":["Chin cam for you. {partner} expected perfect lighting.","They had such high hopes. Then the fan appeared.","Wave at the fan together. It''s a tradition now."],"B:A":["You''ve got perfect lighting. {partner} expected chin cam.","They''re shocked. They thought they''d see your ceiling again.","Next call, flip the camera on them. Show them the light."],"B:B":["Chin cam, and {partner} knew it.","They know your ceiling fan better than your face at this point.","Love truly is blind. And looking straight up your nose."]}}'::jsonb),
('BC-V19','adventure_friend_bc','Guess','{"id":"BC-V19","friendId":"adventure_friend_bc","type":"Guess","scene":"Biscuit''s phone plays a little song notification. She smiles at it like it''s a person.","lines":["Pip sends me songs at weird hours. Because time zones."],"question":"What''s your partner''s ''thinking of you'' move?","selfQuestion":"What''s your ''thinking of you'' move?","choices":[{"id":"A","label":"Sends a song","reply":["A song. Romantic. Every lyric is a hint.","Wake up to a love song. Best alarm."]},{"id":"B","label":"Sends a meme","reply":["A meme. Funny love.","Laughing together from far away still counts."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Songs, and {partner} knew it.","Your shared playlist is basically one long love letter.","Keep sending them. Even the dramatic ballads."],"A:B":["Memes from you. {partner} expected songs.","They''re waiting for lyrics. You send a cat falling off a couch.","Send one song next time. Watch them panic, happily."],"B:A":["Songs from you. {partner} expected memes.","They''re ready for a joke. You hit them with feelings.","Surprise romance attack. Very effective."],"B:B":["Memes, and {partner} knew it.","Their camera roll is half your humor at this point.","Laughter is love with better timing."]}}'::jsonb),
('BC-V20','adventure_friend_bc','Guess','{"id":"BC-V20","friendId":"adventure_friend_bc","type":"Guess","scene":"Biscuit closes her eyes, spins in a circle, and opens them. Still in your living room.","lines":["Didn''t work. Still in your living room. Teleport question!"],"question":"If your partner could teleport you both anywhere once, where would they pick?","selfQuestion":"If you could teleport you both anywhere once, where would you pick?","choices":[{"id":"A","label":"Somewhere totally new","reply":["Somewhere new. Adventure mode.","New memories, new snacks."]},{"id":"B","label":"Back to where you met","reply":["Where you met. Sentimental.","Full-circle romance."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Somewhere new, and {partner} knew it.","They know you''re always chasing the next adventure.","Pack light. Bring snacks. Text me."],"A:B":["Where you met for you. {partner} expected somewhere new.","They thought you''d want adventure. You want the beginning.","That''s so sweet. Tell them why. They''ll melt."],"B:A":["Somewhere new for you. {partner} expected the place you met.","They thought you''d be nostalgic. You''re thinking passports.","Do both. Start where you met, end somewhere new."],"B:B":["Where you met, and {partner} knew it.","They know you''re a sentimental soul.","Recreate the moment. Same spot. Same outfit if you dare."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_kk','["GUESS WHAT!! I’m not leaving till I see {partner}!! I have SO much to tell them!!","Where’s {partner}?? I’ve been here two minutes and I already miss them!!"]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('KK-V01','adventure_friend_kk','Trivia','{"id":"KK-V01","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki bursts through your door, stands up tall on his hind legs, and scans the room like a security camera.","lines":["GUESS WHAT!! I''m on lookout duty! Also quiz duty! Multitasking!!"],"question":"What job do meerkats take turns doing while the others eat?","selfQuestion":null,"choices":[{"id":"A","label":"Cooking dinner","reply":["Ha!! I wish! Moss would love a chef!","Nope, it''s sentry duty: one stands watch while the others forage.","They even call out ''all clear'' with little peeps. Tiny security guards!!"]},{"id":"B","label":"DJ-ing the party","reply":["Okay, that would slap. But no!!","The real job is sentry duty. One meerkat keeps watch for danger.","They peep softly to say ''all good.'' Best coworkers ever."]},{"id":"C","label":"Standing guard as a sentry","reply":["YES!! Sentry duty! My favorite job!","One meerkat climbs up high and watches for danger while the group eats.","They make little ''all clear'' peeps. I do that at parties too."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Meerkats take turns as sentinels while others forage.","coupleReplies":{}}'::jsonb),
('KK-V02','adventure_friend_kk','Trivia','{"id":"KK-V02","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki bleats like a goat, then giggles at himself.","lines":["GUESS WHAT!! Goats have accents! I''m not joking!"],"question":"What did scientists find about young goats'' calls?","selfQuestion":null,"choices":[{"id":"A","label":"They can sing in harmony","reply":["That would be iconic!! But no!","Their calls shift to sound like their social group''s.","Goat accents. Real science. Best fact ever."]},{"id":"B","label":"Their calls change to sound like their friends''","reply":["YES!! Goat accents!!","Young goats in the same group start to sound more alike.","Peer pressure but make it adorable. I''d have the loudest accent."]},{"id":"C","label":"They only bleat at night","reply":["Nope! They bleat all day!","Kid goats'' calls become more similar to their group mates''.","Friends influence how they sound. Like me and my vocabulary."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Briefer & McElligott (2012): pygmy goat kids'' calls converge within social groups.","coupleReplies":{}}'::jsonb),
('KK-V03','adventure_friend_kk','Trivia','{"id":"KK-V03","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki tiptoes, very quietly, which for him is still kind of loud.","lines":["This one''s about Moss! He''s a dormouse!"],"question":"How long can a hazel dormouse hibernate?","selfQuestion":null,"choices":[{"id":"A","label":"Around six months or more","reply":["YES!! Half the year!","Dormice can hibernate from autumn until spring.","I miss him SO much in winter. I text him anyway. He reads them in April."]},{"id":"B","label":"About one week","reply":["Ha!! Moss would be OFFENDED!","Hazel dormice can hibernate for around six months, sometimes more.","Half the year asleep. Moss calls it ''peak introvert.''"]},{"id":"C","label":"They never hibernate","reply":["Oh, they absolutely do!!","Hazel dormice hibernate around six months, sometimes longer.","Their name may even come from an old word for ''sleepy.'' Moss agrees."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Hazel dormice hibernate roughly Oct–Apr, around 6+ months.","coupleReplies":{}}'::jsonb),
('KK-V04','adventure_friend_kk','Trivia','{"id":"KK-V04","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki tickles the air near your side, then laughs.","lines":["Guess what!! Rats laugh!! When you tickle them!!"],"question":"What do rats do when they''re tickled?","selfQuestion":null,"choices":[{"id":"A","label":"Run away screaming","reply":["Nope!! They come back for more!","They make ultrasonic laughing sounds, too high for us to hear.","They even chase the tickling hand. Adorable."]},{"id":"B","label":"Make high-pitched ''laughing'' squeaks","reply":["YES!! Rat giggles!!","They make ultrasonic chirps, and even seek more tickles.","Tickle fights are universal. I''m so happy."]},{"id":"C","label":"Fall asleep instantly","reply":["Ha!! No!!","They make high-pitched chirps, like laughter.","Scientists found they love being tickled. Same."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Panksepp''s research: rats emit 50-kHz ultrasonic chirps when tickled and seek it out.","coupleReplies":{}}'::jsonb),
('KK-V05','adventure_friend_kk','Trivia','{"id":"KK-V05","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki whistles a little three-note tune, then points at himself.","lines":["That was my name! In whistle! Moss has his own whistle too. He never uses it."],"question":"How do bottlenose dolphins call each other by name?","selfQuestion":null,"choices":[{"id":"A","label":"They use signature whistles","reply":["YES!! Each dolphin has its own whistle name!","Others can copy a dolphin''s signature whistle to call it.","Name tags but make it music. I''m OBSESSED."]},{"id":"B","label":"They splash in Morse code","reply":["Okay, that''s genius, but no!","They use signature whistles that work like names.","Dolphins can copy a friend''s whistle to call them. Iconic."]},{"id":"C","label":"They don''t have names","reply":["They totally do!!","Each dolphin develops a signature whistle, basically its name.","Others whistle it back to get their attention. Group chat goals."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Bottlenose dolphins use individual signature whistles that function like names.","coupleReplies":{}}'::jsonb),
('KK-V06','adventure_friend_kk','Trivia','{"id":"KK-V06","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki spots a tiny bug on your wall, then crouches like he''s teaching a class.","lines":["Guess what!! Meerkat school is in session!"],"question":"How do adult meerkats teach pups to eat dangerous scorpions?","selfQuestion":null,"choices":[{"id":"A","label":"They draw diagrams in the sand","reply":["Ha!! Adorable! Not real!","Adults bring pups dead or de-stung scorpions to practice on.","As pups get older, the scorpions get more ''real.'' Level up!"]},{"id":"B","label":"They don''t. Pups figure it out alone","reply":["Nope! Meerkat parents are way more supportive!","Adults bring pups practice scorpions with the stinger removed.","Step by step. Very gentle parenting. Very Finch-approved."]},{"id":"C","label":"They bring practice scorpions with the stinger removed","reply":["CORRECT!! Training wheels for snacks!","Adults bring dead or stingless scorpions first, then gradually harder ones.","Real teaching! Scientists actually studied this. Smart teachers!!"]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Meerkat helpers teach pups by providing disabled scorpions (McAuliffe & Thornton studies).","coupleReplies":{}}'::jsonb),
('KK-V07','adventure_friend_kk','Trivia','{"id":"KK-V07","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki grins at you. Then grins wider. Then waits for you to grin back.","lines":["Guess what!! You just smiled back! I KNEW it!"],"question":"Why do people often smile back when someone smiles at them?","selfQuestion":null,"choices":[{"id":"A","label":"It''s rude not to","reply":["Manners help! But there''s more!","We automatically mimic facial expressions, often without noticing.","Smiles are basically emotional Wi-Fi."]},{"id":"B","label":"We naturally mimic others'' facial expressions","reply":["YES!! Smiles are contagious!","People often copy expressions without thinking, helping us connect.","That''s why I smile at everyone. Spreading the vibe!!"]},{"id":"C","label":"Smiling burns calories","reply":["Ha!! If only!","It''s because we naturally mimic others'' facial expressions.","Copying smiles helps us bond. Science of good vibes."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Facial mimicry: people spontaneously mimic observed expressions, including smiles.","coupleReplies":{}}'::jsonb),
('KK-V08','adventure_friend_kk','Trivia','{"id":"KK-V08","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki wiggles his whole body in a figure-eight on your rug.","lines":["Guess what!! This dance is a MAP!"],"question":"What does a honeybee''s ''waggle dance'' do?","selfQuestion":null,"choices":[{"id":"A","label":"Celebrates a bee''s birthday","reply":["Adorable!! But no!","It shows other bees where to find food.","The direction and duration of the waggle point to the flowers."]},{"id":"B","label":"Tells other bees where to find food","reply":["YES!! A dance that gives directions!","The angle and length of the waggle show direction and distance to flowers.","Imagine giving directions through choreography. I''d never stop dancing."]},{"id":"C","label":"Scares away wasps","reply":["Brave! But not it!","It tells hive-mates the direction and distance to food.","A whole dance-based map system. Bees are geniuses."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Honeybee waggle dance communicates direction and distance to food.","coupleReplies":{}}'::jsonb),
('KK-V09','adventure_friend_kk','Trivia','{"id":"KK-V09","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki fills your bathtub and sits in it, sighing dramatically, like a spa guest.","lines":["Guess what!! Monkeys do this! In SNOW!"],"question":"What do some Japanese macaques do in winter?","selfQuestion":null,"choices":[{"id":"A","label":"Soak in natural hot springs","reply":["YES!! Monkey spa day!!","Some groups bathe in hot springs to stay warm in snowy winters.","Studies even suggest it lowers their stress. Self-care queens."]},{"id":"B","label":"Build snowmen","reply":["That would be the cutest!! No!","They soak in hot springs to stay warm.","Steamy baths in the snow. Peak luxury."]},{"id":"C","label":"Migrate to the beach","reply":["Ha!! Too far!","Some soak in natural hot springs in winter.","Snow monkeys with spa routines. I''m jealous."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Some Japanese macaques bathe in hot springs in winter; linked to lower stress hormones.","coupleReplies":{}}'::jsonb),
('KK-V10','adventure_friend_kk','Trivia','{"id":"KK-V10","friendId":"adventure_friend_kk","type":"Trivia","scene":"Kiki rolls a tiny ball across the floor and chases it, delighted.","lines":["Guess what!! Bees PLAY! With BALLS! For FUN!"],"question":"What did a study find bumblebees do with tiny balls?","selfQuestion":null,"choices":[{"id":"A","label":"Use them to build hives","reply":["Nope!! Hives are wax!","They rolled them around with no reward, seemingly for fun.","Tiny bees, tiny balls, big joy."]},{"id":"B","label":"Throw them at wasps","reply":["Ha!! Bee dodgeball! No!","They just rolled them, with no food reward. Possibly play!","Even busy bees take breaks. Lesson learned."]},{"id":"C","label":"Roll them around, apparently just for fun","reply":["YES!! Bees playing!!","They rolled balls with no reward, and young bees did it most.","Play is for everyone. Even bees. I''m crying happy tears."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Dona et al. (2022): bumblebees rolled balls without reward, suggestive of play.","coupleReplies":{}}'::jsonb),
('KK-V11','adventure_friend_kk','Preference','{"id":"KK-V11","friendId":"adventure_friend_kk","type":"Preference","scene":"Kiki bounces on your couch holding two invitations: one glittery, one plain.","lines":["GUESS WHAT!! It''s Friday! Moss already said no."],"question":"Friday night: a big party, or a cozy night in?","selfQuestion":null,"choices":[{"id":"A","label":"A big party","reply":["A big party!! YES!! My people!","Music! Snacks! Forty new best friends!"]},{"id":"B","label":"A cozy night in","reply":["A cozy night in. Moss would adore you.","Blankets, a movie, and zero small talk. Honestly? Fair."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Big party for both of you!! Unstoppable!","So you and {partner} probably leave the party with three new group chats.","Bring me next time. I''ll bring confetti."],"A:B":["Cozy night for you. {partner} wants the party.","Let them go for an hour. You keep the couch warm.","They''ll come home with stories. You''ll have the snacks ready. Team."],"B:A":["Party for you!! {partner} wants a cozy night in.","Moss and I have this exact fight every week.","Our fix: party till ten, then home for blankets. Works every time."],"B:B":["Cozy night in for both of you. Very Moss of you.","Honestly, {partner} and you on the couch, phones down, snacks up. Peaceful.","I''m not crying. I''m just loud about feelings."]}}'::jsonb),
('KK-V12','adventure_friend_kk','Preference','{"id":"KK-V12","friendId":"adventure_friend_kk","type":"Preference","scene":"Kiki flops dramatically after dancing, then immediately springs back up.","lines":["Battery check!! Mine is at 200%!"],"question":"After a big social event: fully charged, or totally drained?","selfQuestion":null,"choices":[{"id":"A","label":"Fully charged","reply":["Fully charged!! Same!!","People are basically my phone charger."]},{"id":"B","label":"Totally drained","reply":["Totally drained. Valid! Moss is the same.","Social battery at 2%. Must lie down. Must not speak."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Both fully charged!! Extrovert power couple!","I can picture it: you and {partner} go to an afterparty after the afterparty.","Sleep is optional. Fun is mandatory."],"A:B":["You''re drained. {partner} is fully charged.","They''ll want to replay the whole night. You''ll want a blanket burrito.","Let them talk while you lie down. Listening counts. Nodding counts."],"B:A":["You''re fully charged. {partner} is totally drained.","You want to debrief every conversation. They want the void.","Give them one hour of quiet. THEN tell them all the gossip."],"B:B":["Both drained. Very understandable.","Pretty sure {partner} and you need a full day of silence after a wedding.","Honestly, a quiet Sunday together sounds perfect."]}}'::jsonb),
('KK-V13','adventure_friend_kk','Preference','{"id":"KK-V13","friendId":"adventure_friend_kk","type":"Preference","scene":"Kiki practices a handshake on the coat rack.","lines":["Guess what!! New people!!"],"question":"At a party full of strangers, what do you do?","selfQuestion":null,"choices":[{"id":"A","label":"Say hi to everyone","reply":["Say hi to everyone!! A legend!","Name tags? Who needs them. You remember everyone."]},{"id":"B","label":"Stick to people I know","reply":["Stick to people you know. Safe and smart.","Your circle, your comfort zone."]},{"id":"C","label":"Befriend the host''s pet","reply":["Befriend the pet. Moss''s strategy exactly.","Pets don''t ask ''so what do you do?''"]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both say hi to everyone!! Party tornado couple!","Lowkey, you and {partner} probably know the host''s cousin''s roommate by the end.","Networking but make it fun."],"A:B":["You stick to who you know. {partner} talks to everyone.","They''ll keep bringing new people over to meet you.","Smile. Nod. Let them do the heavy lifting."],"A:C":["You find the pet. {partner} greets everyone.","They''re networking. You''re making a lifelong friend with four paws.","Honestly, you''ll have the better story tomorrow."],"B:A":["You say hi to everyone. {partner} sticks to familiar faces.","You''re the social butterfly. They''re the home base.","Bring new friends back to them. One at a time. Gently."],"B:B":["You both stick to people you know. Cozy circle.","{partner} and you probably end up chatting in the same corner all night.","A two-person party within a party. Cute."],"B:C":["Pet for you. {partner} sticks to familiar faces.","They''re with friends. You''re with the dog. Everyone''s safe.","Bring the dog to their circle. Instant icebreaker."],"C:A":["You greet the whole room. {partner} finds the pet.","They''ll be on the floor with the cat while you work the crowd.","Check in on them. And the cat. Both deserve attention."],"C:B":["Familiar people for you. {partner} befriends the pet.","You''re in a cozy corner. They''re under the table with the dog.","Join them. Pets are great listeners."],"C:C":["You both go straight for the pet. Iconic.","So you and {partner} spend the whole party on the floor with a golden retriever.","Best party ever. No notes."]}}'::jsonb),
('KK-V14','adventure_friend_kk','Preference','{"id":"KK-V14","friendId":"adventure_friend_kk","type":"Preference","scene":"Kiki hides behind your door, then jumps out yelling ''SURPRISE!!''","lines":["Birthday planning! Moss hates surprises!"],"question":"Birthday: surprise party, or a small dinner you planned yourself?","selfQuestion":null,"choices":[{"id":"A","label":"Surprise party","reply":["Surprise party!! Confetti in your face! Love it!","Pure chaos. Pure love."]},{"id":"B","label":"Small planned dinner","reply":["Small planned dinner. Respect.","You choose the menu, the people, the vibe. Smart."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Surprise parties for both of you!! Chaos lovers!","Honestly, you and {partner} will spend every birthday trying to out-surprise each other.","Escalation is guaranteed. I''m here for it."],"A:B":["Small dinner for you. {partner} wants a surprise party.","Careful. They''re probably planning one for you RIGHT NOW.","Drop hints. Very clear hints. ''I don''t want a party.'' Repeatedly."],"B:A":["Surprise party for you!! {partner} wants a small dinner.","Throw them the dinner. Let them throw you the surprise.","Everyone gets the birthday they actually want. Wow, I''m good."],"B:B":["Small dinners for both of you. Thoughtful couple.","I can picture it: {partner} and you would rather have three close friends than thirty strangers.","Very mature. Very cozy. Very not me."]}}'::jsonb),
('KK-V15','adventure_friend_kk','Preference','{"id":"KK-V15","friendId":"adventure_friend_kk","type":"Preference","scene":"Kiki holds his phone up to his ear, then texts instead, then calls again.","lines":["I love phone calls! Moss doesn''t!"],"question":"Phone calls: love them, or please just text?","selfQuestion":null,"choices":[{"id":"A","label":"Love phone calls","reply":["Love calls!! Hearing voices is the best!","Why type when you can TALK?"]},{"id":"B","label":"Please just text","reply":["Please just text. Totally fair.","Phone ringing = mild panic. Same for Moss."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both love calls!! Long chats forever!","Pretty sure you and {partner} have three-hour calls about nothing.","That''s love. Also your phone bill."],"A:B":["You prefer text. {partner} loves calls.","They''ll call. You''ll stare at the phone. Classic.","Pick up once a week. They''ll be thrilled. You''ll survive."],"B:A":["You love calls. {partner} prefers texts.","They''ll see your name pop up and briefly panic.","Text first: ''can I call?'' Tiny warning, big kindness."],"B:B":["Both team text. Peaceful.","Lowkey, {partner} and you probably send voice notes only in emergencies.","Silence and emojis. Perfect communication."]}}'::jsonb),
('KK-V16','adventure_friend_kk','Guess','{"id":"KK-V16","friendId":"adventure_friend_kk","type":"Guess","scene":"Kiki stands on a chair, scanning the room like a lighthouse.","lines":["Guess what!! I''m the party detective now! I have a tiny notebook!"],"question":"One hour into a party, where do you find your partner?","selfQuestion":"One hour into a party, where are you?","choices":[{"id":"A","label":"Center of the dance floor","reply":["Dance floor!! Main character energy!","Everyone''s watching. Everyone''s jealous."]},{"id":"B","label":"In the kitchen by the snacks","reply":["Kitchen snacks. Smart.","The kitchen is where the real party is."]},{"id":"C","label":"Quietly petting the host''s cat","reply":["Petting the cat. Moss''s favorite move.","Cats are the best introvert support."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Dance floor, and {partner} knew it!","They''ve seen you take over a dance floor before.","Just grab them for the slow song. Mandatory."],"A:B":["Kitchen snacks for you. {partner} pictured you dancing.","They''re looking for you on the dance floor. You''re eating dip.","Dance in the kitchen. Everyone wins."],"A:C":["Petting the cat. {partner} pictured you dancing.","They''re looking at the dance floor. You''re upstairs with a fluffball.","Moss would do the exact same. You two should hang out."],"B:A":["You''re on the dance floor. {partner} pictured you by the snacks.","Surprise!! You''re out there dancing.","Grab a chip on your way to the next song."],"B:B":["Kitchen snacks, and {partner} knew it!","They know you''ll be guarding the guacamole.","Save them a plate. That''s love."],"B:C":["Cat for you. {partner} pictured you by the snacks.","Okay but the cat is technically next to the snacks.","You''re both kind of right. Bring the cat a treat."],"C:A":["Dance floor for you. {partner} pictured you with the cat.","They think you''re shy. You''re doing the worm.","Plot twist of the night. Iconic."],"C:B":["Snacks for you. {partner} pictured you with the cat.","Close! You and the cat are both near the food.","Share the cheese. With the cat. Lightly."],"C:C":["Petting the cat, and {partner} knew it!","They know you''d rather chat with a cat than a crowd.","Respect. Cats are elite company."]}}'::jsonb),
('KK-V17','adventure_friend_kk','Guess','{"id":"KK-V17","friendId":"adventure_friend_kk","type":"Guess","scene":"Kiki makes very intense eye contact, then tilts his head at the door.","lines":["That''s my ''let''s go'' face!"],"question":"How does your partner signal they''re ready to leave a party?","selfQuestion":"How do you signal you''re ready to leave a party?","choices":[{"id":"A","label":"Subtle secret eye contact","reply":["Secret eye contact. Spy couple!","One look. Mission understood."]},{"id":"B","label":"Announces it to the whole room","reply":["Announces it loudly. Honest!","''I''M TIRED, BYE EVERYONE.''"]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Secret eye contact, and {partner} knew!","Your one look means ''please get me out of here.'' They get it instantly.","Spy-level communication. I''m impressed."],"A:B":["You announce it loudly. {partner} expected subtle eye contact.","They''re waiting for your secret signal. You just yelled ''BYE.''","Efficient. Slightly chaotic. Very effective."],"B:A":["You use secret eye contact. {partner} expected an announcement.","They might miss your subtle look.","Upgrade to a gentle tug on their sleeve."],"B:B":["Loud announcement, and {partner} knew!","Everyone at the party now knows you''re leaving.","Honesty is a gift. A loud gift."]}}'::jsonb),
('KK-V18','adventure_friend_kk','Guess','{"id":"KK-V18","friendId":"adventure_friend_kk","type":"Guess","scene":"Kiki pretends to sleep for exactly three seconds, then pops up.","lines":["That''s how long I can nap! Moss naps for hours!"],"question":"After a busy week, how does your partner recharge?","selfQuestion":"After a busy week, how do you recharge?","choices":[{"id":"A","label":"A long solo nap","reply":["Long solo nap. Moss approves!","Silence, pillows, zero alarms."]},{"id":"B","label":"Brunch with friends","reply":["Brunch with friends!! Social recharge!","Mimosas and gossip. Ideal!"]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Long nap, and {partner} knew!","They tiptoe around the house while you sleep. True love.","Snore proudly. They''ll pretend it''s cute. It is."],"A:B":["Brunch for you. {partner} expected a nap.","They''re tiptoeing around the house. You''re out with friends.","Text them a pic of the pancakes. Bring one home."],"B:A":["You nap. {partner} expected you at brunch.","They imagined you with friends. You''re under a blanket.","Hang a ''do not disturb'' sign. They''ll understand."],"B:B":["Brunch with friends, and {partner} knew!","They know your social battery fills up with pancakes and gossip.","Bring them back a muffin. Mandatory."]}}'::jsonb),
('KK-V19','adventure_friend_kk','Guess','{"id":"KK-V19","friendId":"adventure_friend_kk","type":"Guess","scene":"Kiki squeezes into the middle of a group photo frame on your shelf.","lines":["Guess what!! Picture time! Moss always hides!"],"question":"Where is your partner in a group photo?","selfQuestion":"Where are you in a group photo?","choices":[{"id":"A","label":"Front row, peace sign","reply":["Front row!! Peace sign! Iconic!","Main character in every pic."]},{"id":"B","label":"Half hidden behind someone","reply":["Half hidden. Mysterious.","Just one eyebrow visible."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Front row, peace sign, and {partner} knew it!","Every group photo has you, center, mid-pose.","You''re the moment. Always."],"A:B":["You''re half hidden. {partner} pictured you front row.","They thought you''d be posing. You''re behind someone''s hat.","Next time, give them one peace sign. For them."],"B:A":["You''re front and center. {partner} pictured you hiding.","They''ll be scanning the back row. You''re doing a peace sign up front.","Steal the spot next to them. Photo-bomb with love."],"B:B":["Half hidden, and {partner} knew it!","They''ve zoomed in to find you behind someone''s shoulder.","Eyebrow-only cameo. Very exclusive. Very you."]}}'::jsonb),
('KK-V20','adventure_friend_kk','Guess','{"id":"KK-V20","friendId":"adventure_friend_kk","type":"Guess","scene":"Kiki holds up his phone, about to text a big announcement, finger hovering.","lines":["GUESS WHAT!! I have news! The news is this question!"],"question":"When your partner has big news, who hears it first?","selfQuestion":"When you have big news, who hears it first?","choices":[{"id":"A","label":"Partner first, always","reply":["Partner first. Sweet.","Inner circle of two."]},{"id":"B","label":"The group chat, all at once","reply":["Group chat! Everyone at once!","Efficient. Loud. Iconic."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Partner first, and {partner} knew it!","They know they''re your first call. Every time.","That''s a VIP spot. Treasure it."],"A:B":["Group chat for you. {partner} expected to hear first.","Oops. They found out with everyone else.","Next time, text them one minute earlier. Huge difference."],"B:A":["Partner first for you. {partner} expected the group chat.","They didn''t realize they''re your first call.","Tell them. They''ll be secretly thrilled."],"B:B":["Group chat, and {partner} knew it!","They know your news goes out to everyone at once.","Efficient. Still, save them a personal text."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_dl','["...I’ll wait for {partner}. If that’s okay. ...I’ll be quiet.","...Didn’t get to say hi to {partner} yet. I’ll stay a bit. ...Maybe."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('DL-V01','adventure_friend_dl','Trivia','{"id":"DL-V01","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon pulls out four identical small stickers and lines them up on the table.","lines":["...These are me and my siblings. We''re identical."],"question":"What''s unusual about how nine-banded armadillos are born?","selfQuestion":null,"choices":[{"id":"A","label":"Always just one baby","reply":["...Nope. Always four.","Nine-banded armadillos give birth to identical quadruplets.","One egg, split four ways. Built-in group chat."]},{"id":"B","label":"Always identical quadruplets","reply":["...Correct. Four of us. Same everything.","One egg splits into four identical babies. Every time.","Imagine four of me at a party. Silent. Very silent."]},{"id":"C","label":"They hatch from eggs","reply":["...No eggs. Live babies.","Nine-banded armadillos are born as identical quadruplets, every time.","Four matching shells. Family photos are confusing."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Nine-banded armadillos typically give birth to identical quadruplets.","coupleReplies":{}}'::jsonb),
('DL-V02','adventure_friend_dl','Trivia','{"id":"DL-V02","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon looks at a picture of a pink smiling salamander. He smiles back, a tiny bit.","lines":["...This one can heal. Like, really heal."],"question":"What can axolotls regrow?","selfQuestion":null,"choices":[{"id":"A","label":"Limbs, and even parts of their heart and brain","reply":["...Correct. Amazing.","Axolotls can regrow lost legs and even repair heart and brain tissue.","Healing takes time. But it happens. ...I like that."]},{"id":"B","label":"Only their tail","reply":["...More than that. Much more.","Axolotls can regrow whole limbs and parts of organs.","Scientists study them to learn about healing."]},{"id":"C","label":"Nothing at all","reply":["...No. They''re healing champions.","They regrow limbs and repair parts of organs.","Some wounds heal. That''s hopeful."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Axolotls regenerate limbs and parts of heart, spinal cord and brain.","coupleReplies":{}}'::jsonb),
('DL-V03','adventure_friend_dl','Trivia','{"id":"DL-V03","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon holds a seashell and gently taps it against his own shell.","lines":["...This one''s about moving homes. And trust. Kind of."],"question":"When a new shell washes up, what do hermit crabs sometimes do?","selfQuestion":null,"choices":[{"id":"A","label":"Fight until one crab wins all the shells","reply":["...Sometimes there''s drama. But not this time.","They line up by size and swap shells one after another.","It''s called a vacancy chain. Teamwork in tiny houses."]},{"id":"B","label":"Line up by size and swap shells in a chain","reply":["...Yes. It''s beautiful.","When a bigger shell appears, crabs queue up and each moves up a size.","Everyone gets a better home. Takes patience. Takes trust."]},{"id":"C","label":"Ignore it and stay in their old shell forever","reply":["...I relate. But no.","They line up by size and trade up, one crab at a time.","Letting go of an old shell. That''s growth. ...Maybe."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Hermit crabs form vacancy chains, swapping shells by size.","coupleReplies":{}}'::jsonb),
('DL-V04','adventure_friend_dl','Trivia','{"id":"DL-V04","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon blinks hard, then turns away. ''Dust,'' he says.","lines":["...Crying question. It''s not about me."],"question":"Which animal is known for crying emotional tears?","selfQuestion":null,"choices":[{"id":"A","label":"Humans, as far as we know","reply":["...Correct. As far as science knows.","Many animals make tears to clean their eyes, but emotional tears seem uniquely human.","So crying is part of being human. ...It''s okay to do it."]},{"id":"B","label":"Crocodiles","reply":["...That''s a myth phrase. ''Crocodile tears.''","Emotional tears seem to be uniquely human, as far as we know.","Crocodiles tear up to keep their eyes wet, not from feelings."]},{"id":"C","label":"Dogs","reply":["...Dogs show feelings. Not with tears, though.","Emotional crying seems to be uniquely human.","Dogs cry with their eyes in other ways. Big ones."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Emotional tearing appears to be unique to humans; other animals produce basal/reflex tears.","coupleReplies":{}}'::jsonb),
('DL-V05','adventure_friend_dl','Trivia','{"id":"DL-V05","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon taps his fingernail against his shell twice, thoughtfully.","lines":["...Another armored friend."],"question":"What are a pangolin''s scales made of?","selfQuestion":null,"choices":[{"id":"A","label":"Bone","reply":["...That''s more like my plates.","Pangolin scales are keratin, the same stuff as fingernails.","Imagine being covered in fingernails. ...Actually kind of cool."]},{"id":"B","label":"Tree bark","reply":["...Creative. No.","They''re keratin, like your fingernails.","Pangolins are the only mammals fully covered in scales."]},{"id":"C","label":"Keratin, like fingernails","reply":["...Correct. Nail armor.","Pangolins are the only mammals covered in keratin scales.","They roll up too. ...Better than me at it. Fine."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Pangolin scales are keratin; pangolins are the only mammals with scales covering most of the body.","coupleReplies":{}}'::jsonb),
('DL-V06','adventure_friend_dl','Trivia','{"id":"DL-V06","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon peeks at your fish tank, very still, very curious.","lines":["...Water question. Don''t worry. It''s safe. ...Mostly."],"question":"How do armadillos sometimes cross small streams?","selfQuestion":null,"choices":[{"id":"A","label":"They ride on turtles","reply":["...That would be a nice friendship. No.","They hold their breath and walk across the bottom.","Up to about six minutes without air. Very peaceful."]},{"id":"B","label":"They hold their breath and walk along the bottom","reply":["...Yes. Nice.","They can hold their breath for about six minutes.","Walking underwater is calming. No one can talk to you down there."]},{"id":"C","label":"They refuse to cross water, ever","reply":["...I wanted to. But we''re braver than that.","They hold their breath and stroll along the bottom.","Or gulp air to float across. Two options. Good options."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Armadillos can hold breath ~6 min and walk underwater, or inflate gut to float.","coupleReplies":{}}'::jsonb),
('DL-V07','adventure_friend_dl','Trivia','{"id":"DL-V07","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon pulls out a picture of a duck-billed creature with a beaver tail.","lines":["...This one is confusing. Like me."],"question":"What''s surprising about the platypus?","selfQuestion":null,"choices":[{"id":"A","label":"It can fly short distances","reply":["...That would be even more confusing.","Nope. It''s a mammal that lays eggs. Like a bird. But not.","Plus, males have venomous ankle spurs. ...Complex."]},{"id":"B","label":"It''s a mammal that lays eggs","reply":["...Correct. Breaks the rules.","Platypuses lay eggs but still make milk for their babies.","Weird and wonderful. ...Being different is okay."]},{"id":"C","label":"It''s actually a type of bird","reply":["...It has a bill, but no.","It''s a mammal that lays eggs.","One of the only egg-laying mammals."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Platypuses are monotremes: egg-laying mammals.","coupleReplies":{}}'::jsonb),
('DL-V08','adventure_friend_dl','Trivia','{"id":"DL-V08","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon sits very still, like he''s trying to survive something by not moving.","lines":["...This one''s about surviving things. ...Maybe I relate."],"question":"Which tiny animal can survive extreme cold, heat, and even space?","selfQuestion":null,"choices":[{"id":"A","label":"A tardigrade, or ''water bear''","reply":["...Yes. Tiny legend.","Tardigrades can dry out, curl up, and survive conditions that would destroy most life.","They''ve even survived the vacuum of space. ...Goals."]},{"id":"B","label":"A housefly","reply":["...Flies are tough, but not that tough.","It''s the tardigrade, also called a water bear.","They can survive drying out for years, then wake back up."]},{"id":"C","label":"A goldfish","reply":["...No. Please protect your goldfish.","It''s the tardigrade, a tiny ''water bear.''","Space, freezing, boiling-ish. They just shrug. Tiny armor."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Tardigrades survive extreme conditions in a dried ''tun'' state, including space exposure.","coupleReplies":{}}'::jsonb),
('DL-V09','adventure_friend_dl','Trivia','{"id":"DL-V09","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon touches a little seed pod in your plant pot. It bursts. He jumps a foot.","lines":["...I didn''t jump. Okay. I jumped. Plant question."],"question":"What happens when you touch a ripe ''touch-me-not'' seed pod?","selfQuestion":null,"choices":[{"id":"A","label":"It closes tighter","reply":["...That''s the shy plant. Different one.","The pod pops open and throws seeds.","Launching seeds away so they can grow somewhere new."]},{"id":"B","label":"It glows","reply":["...No. Scary enough without glowing.","The pod bursts and flings its seeds.","That''s how it spreads. Explosive. Startling."]},{"id":"C","label":"It bursts open and flings its seeds","reply":["...Correct. It startled me too.","The pod twists open fast and launches seeds away.","Very dramatic. Very relatable."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Impatiens (''touch-me-not'') pods dehisce explosively when touched.","coupleReplies":{}}'::jsonb),
('DL-V10','adventure_friend_dl','Trivia','{"id":"DL-V10","friendId":"adventure_friend_dl","type":"Trivia","scene":"Dillon closes one eye, keeps the other open, and stares at the door.","lines":["...Guarding. Half asleep. Ducks do it."],"question":"How can some ducks sleep while staying alert?","selfQuestion":null,"choices":[{"id":"A","label":"They don''t sleep at all","reply":["...They do. Just cleverly.","They can rest half the brain and keep one eye open.","The edge ducks guard the group. Teamwork."]},{"id":"B","label":"They take turns sitting on each other","reply":["...Cute. Not real.","They sleep with half their brain and one eye open.","Ducks on the edge stay most alert. Like a lookout."]},{"id":"C","label":"By sleeping with half their brain, one eye open","reply":["...Correct. Half on guard.","Ducks at the edge of a group often keep one eye open toward danger.","Resting while staying safe. ...I understand that."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Rattenborg et al. (1999): mallards use unihemispheric sleep with one eye open at group edges.","coupleReplies":{}}'::jsonb),
('DL-V11','adventure_friend_dl','Preference','{"id":"DL-V11","friendId":"adventure_friend_dl","type":"Preference","scene":"Dillon holds a small box. He opens it a crack, then closes it again.","lines":["...Secrets. They''re hard for me."],"question":"Sharing something personal: all at once, or a little at a time?","selfQuestion":null,"choices":[{"id":"A","label":"All at once","reply":["...All at once. Brave. Very brave.","Rip the bandage off. I''ve never done that. ...Yet."]},{"id":"B","label":"A little at a time","reply":["...A little at a time. Same. Very same.","Small doors before big doors."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...You both share all at once. Wow.","So {partner} and you just open the whole box. No warning.","That takes a lot of trust. ...I''m proud of you two."],"A:B":["...You go slow. {partner} shares everything at once.","They''ll hand you the whole story. You''ll offer a sentence.","That''s okay. One sentence from you probably means a lot to them."],"B:A":["...You share all at once. {partner} shares a little at a time.","You''ll open the whole box. They''ll hand you one page.","Be patient with their pages. They''re still worth reading."],"B:B":["...You both share slowly. Gentle couple.","Honestly, you and {partner} let each other in one small door at a time.","That''s how Ash and I are doing it. It works. ...Mostly."]}}'::jsonb),
('DL-V12','adventure_friend_dl','Preference','{"id":"DL-V12","friendId":"adventure_friend_dl","type":"Preference","scene":"Dillon checks his phone. A text from Ash says ''home safe?'' He smiles very slightly.","lines":["...Ash checks in on me. I pretend it''s no big deal. ...It''s a big deal."],"question":"When you''re apart: ''got home safe'' texts always, or only if it''s late?","selfQuestion":null,"choices":[{"id":"A","label":"Always","reply":["...Always. Every time. Even next door.","That''s the kind of thing that rebuilds trust."]},{"id":"B","label":"Only if it''s late","reply":["...Only if it''s late. Reasonable.","No need to report every grocery trip."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...Always, for both of you. Safe couple.","I can picture it: {partner} and you text ''home!'' even after a two-minute walk.","...That''s sweet. I like that. A lot."],"A:B":["...Only late for you. {partner} texts every time.","They''ll send ''home safe'' after the grocery store. Lean into it.","A one-word reply makes their whole day. ...Trust me."],"B:A":["...You''d text always. {partner} only when it''s late.","They might not reply to your daytime ''home!'' Don''t spiral.","It''s not about trust. It''s just their style. ...I''m learning that too."],"B:B":["...Only late at night for both of you. Relaxed couple.","Pretty sure you and {partner} trust the daytime. Fair.","Late night ''home safe?'' still hits different. ...Nice."]}}'::jsonb),
('DL-V13','adventure_friend_dl','Preference','{"id":"DL-V13","friendId":"adventure_friend_dl","type":"Preference","scene":"Dillon pulls a soft blanket over his shell. Only his nose sticks out.","lines":["...Everyone needs a safe place. Mine is under this blanket. Obviously."],"question":"Where do you feel safest talking with your partner?","selfQuestion":null,"choices":[{"id":"A","label":"On the couch at home","reply":["...The couch. Soft. Familiar.","No exits. In a good way."]},{"id":"B","label":"On a long car ride","reply":["...A long drive. Side by side.","No eye contact needed. Very helpful."]},{"id":"C","label":"On a night walk","reply":["...A night walk. Dark and quiet.","Easier to say hard things to the stars."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...The couch for both of you. Cozy.","Lowkey, {partner} and you probably have all your big talks there.","That couch has heard everything. ...Respect the couch."],"A:B":["...Long drive for you. {partner} likes the couch.","You talk better facing the road. They talk better facing you.","Start in the car. Park. Finish on the couch."],"A:C":["...Night walk for you. {partner} likes the couch.","You need the sky. They need the cushions.","Walk to a bench. Bring a blanket. Compromise."],"B:A":["...Couch for you. {partner} prefers a long drive.","You want the blanket. They want the open road.","Talk on the drive home, then finish on the couch."],"B:B":["...Long drives for both of you. Road talkers.","You and {partner} save the deep stuff for highway hour two.","No eye contact. Just honesty. ...It works."],"B:C":["...Night walk for you. {partner} likes long drives.","Drive somewhere pretty. Walk under the stars.","Best of both. ...Very nice."],"C:A":["...Couch for you. {partner} likes night walks.","You want cushions. They want streetlights.","Walk first, couch second. Big feelings, then blankets."],"C:B":["...Drives for you. {partner} likes night walks.","Both of you like moving while talking. ...Interesting.","Drive somewhere quiet. Then walk. Two safe spaces."],"C:C":["...Night walks for both of you. Starlit talks.","So {partner} and you probably solve life problems under streetlights.","Quiet sky. Loud hearts. ...I like that."]}}'::jsonb),
('DL-V14','adventure_friend_dl','Preference','{"id":"DL-V14","friendId":"adventure_friend_dl","type":"Preference","scene":"Dillon writes ''sorry'' on a napkin, then crosses it out, then writes it again.","lines":["...Apologies. I''m slow at them."],"question":"Saying sorry: right away, or once you know exactly what to say?","selfQuestion":null,"choices":[{"id":"A","label":"Right away","reply":["...Right away. Brave and fast.","Fixes things before they get heavy."]},{"id":"B","label":"Once I know what to say","reply":["...Once you know what to say. Thoughtful.","Better words, fewer regrets."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...Both of you say sorry right away. Healthy.","Honestly, {partner} and you never let things sit too long.","...That''s rare. Keep that."],"A:B":["...You need time. {partner} apologizes right away.","They''ll say sorry fast. You''ll still be drafting.","Say ''I''m thinking.'' Then take your time. ...That counts."],"B:A":["...You say sorry right away. {partner} needs time to find words.","You''ll apologize in seconds. They''ll take an afternoon.","Their sorry is coming. It''ll be a good one. ...Wait for it."],"B:B":["...Both of you need time to find the words. Gentle couple.","I can picture it: you and {partner} would rather say it right than fast.","Just let each other know you''re thinking. ...It helps."]}}'::jsonb),
('DL-V15','adventure_friend_dl','Preference','{"id":"DL-V15","friendId":"adventure_friend_dl","type":"Preference","scene":"Dillon flinches slightly when your doorbell rings.","lines":["...Surprises. They scare me. ...A little."],"question":"Surprises: love them, or warn me first?","selfQuestion":null,"choices":[{"id":"A","label":"Love them","reply":["...Love them. Fearless.","Confetti doesn''t scare you. Wow."]},{"id":"B","label":"Warn me first","reply":["...Warn me first. Same.","A heads-up is kindness."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...You both love surprises. Bold.","Pretty sure {partner} and you surprise each other constantly.","...Exciting. Exhausting. Mostly exciting."],"A:B":["...You want a warning. {partner} loves surprises.","They''ll plan secret things. You''ll sense it and panic.","Ask for one hint. Just one. ...Then enjoy it."],"B:A":["...You love surprises. {partner} wants a warning.","Give them a small heads-up. ''Something''s coming. It''s good.''","They''ll relax. Then enjoy it more. ...Trust me."],"B:B":["...You both want a warning. Safe couple.","Lowkey, you and {partner} say ''surprise on Friday!'' before the surprise. Love it.","Predictable is cozy. ...Very cozy."]}}'::jsonb),
('DL-V16','adventure_friend_dl','Guess','{"id":"DL-V16","friendId":"adventure_friend_dl","type":"Guess","scene":"Dillon''s paws fidget with a pebble the whole time he talks.","lines":["...I fidget when I''m nervous. You''ll notice the pebble. Don''t mention it."],"question":"When your partner is nervous, what do their hands do?","selfQuestion":"When you''re nervous, what do your hands do?","choices":[{"id":"A","label":"Fidget with anything nearby","reply":["...Fidget. Pens, sleeves, pebbles.","Relatable. Very relatable."]},{"id":"B","label":"Reach for a hand to hold","reply":["...Reach for a hand. Brave.","Asking for comfort is strong."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...Fidgeting, and {partner} knew it.","They''ve noticed you clicking the same pen twelve times.","Maybe hold their hand instead. ...Good fidget."],"A:B":["...You reach for a hand. {partner} expected fidgeting.","They didn''t realize their hand is your comfort.","Tell them. They''ll keep it free for you. ...Always."],"B:A":["...You fidget. {partner} thought you''d reach for their hand.","They''re waiting with an open hand. You''re holding a pebble.","Put the pebble down. Take the hand. ...Just try once."],"B:B":["...Reaching for a hand, and {partner} knew it.","They know your hand finds theirs when things get tense.","That''s trust. ...Real trust."]}}'::jsonb),
('DL-V17','adventure_friend_dl','Guess','{"id":"DL-V17","friendId":"adventure_friend_dl","type":"Guess","scene":"Dillon stares out the window at the road, deep in thought.","lines":["...Opening up is hard. Like a shell with a rusty hinge."],"question":"What helps your partner open up the most?","selfQuestion":"What helps you open up the most?","choices":[{"id":"A","label":"A late-night drive","reply":["...A drive. Side by side. Eyes on the road.","Easier to talk without staring."]},{"id":"B","label":"A long walk","reply":["...A walk. Moving helps the words.","Footsteps make room for feelings."]},{"id":"C","label":"Being under a blanket","reply":["...A blanket. Safe little cave.","Feelings come out when you''re cozy."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...A late-night drive, and {partner} knew it.","They''ve learned to take the long way home. On purpose.","...That''s kind of beautiful."],"A:B":["...A walk opens you up. {partner} guessed a drive.","They''re starting the car. You''re tying your shoes.","Drive to a park. Then walk. ...Both."],"A:C":["...A blanket opens you up. {partner} guessed a drive.","They''re grabbing car keys. You''re grabbing the throw.","Tell them: no keys needed. Just blankets."],"B:A":["...A drive opens you up. {partner} guessed a walk.","Close. You both like moving while talking.","Next time they say ''walk?'', say ''drive?''"],"B:B":["...A long walk, and {partner} knew it.","They know your best talks happen around mile two.","Comfortable shoes. Open hearts."],"B:C":["...A blanket opens you up. {partner} guessed a walk.","They''re waiting by the door. You''re on the couch.","Short walk, long blanket. ...Works for me."],"C:A":["...A drive opens you up. {partner} guessed a blanket.","They''re building a blanket fort. You''re grabbing the keys.","Bring the blanket in the car. ...Compromise."],"C:B":["...A walk opens you up. {partner} guessed a blanket.","They want you cozy. You want fresh air.","Walk first. Blanket after. ...Perfect evening."],"C:C":["...A blanket, and {partner} knew it.","They know you talk best when you''re wrapped up like a burrito.","...I''d do the same. Shell plus blanket."]}}'::jsonb),
('DL-V18','adventure_friend_dl','Guess','{"id":"DL-V18","friendId":"adventure_friend_dl","type":"Guess","scene":"Dillon shrugs one shoulder and says, very softly, ''...Maybe.''","lines":["...What does that mean? Good question."],"question":"When your partner says ''maybe,'' what do they usually mean?","selfQuestion":"When you say ''maybe,'' what do you usually mean?","choices":[{"id":"A","label":"Yes, but nervous","reply":["...Yes, but nervous. That''s my ''maybe.''","Means ''I want to. I''m scared.''"]},{"id":"B","label":"No, but polite","reply":["...No, but polite. Diplomatic.","''Maybe'' is the nicest ''no.''"]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...''Maybe'' means ''yes, nervously,'' and {partner} knew it.","They hear the hidden ''yes'' every time.","...That''s real understanding. Keep it."],"A:B":["...Your ''maybe'' means no. {partner} thought it meant yes.","Oops. They''ve been buying tickets.","Try ''probably not.'' ...Kinder in the long run."],"B:A":["...Your ''maybe'' means yes. {partner} thought it meant no.","They''ve been canceling plans you secretly wanted.","Next time, say ''maybe yes.'' ...Tiny upgrade."],"B:B":["...''Maybe'' means ''no, politely,'' and {partner} knew it.","They know not to buy the concert tickets.","...Saves everyone some money."]}}'::jsonb),
('DL-V19','adventure_friend_dl','Guess','{"id":"DL-V19","friendId":"adventure_friend_dl","type":"Guess","scene":"Dillon hands you the TV remote very slowly, like it''s a sacred object.","lines":["...This is a big deal. I don''t hand this to just anyone."],"question":"How does your partner show they really trust you?","selfQuestion":"How do you show your partner you really trust them?","choices":[{"id":"A","label":"Lets you see them cry","reply":["...Crying in front of someone. Huge.","That''s real armor coming off."]},{"id":"B","label":"Hands over the TV remote","reply":["...The remote. Sacred trust.","Giving up control. ...Huge too."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...Crying in front of them, and {partner} knew it.","They know your tears are the deepest trust you have.","...That means they''re safe. Very safe."],"A:B":["...You show trust with the remote. {partner} guessed tears.","They think it''s deep. It''s... also deep. In a TV way.","Both count. ...Remote trust is real trust."],"B:A":["...You show trust through tears. {partner} guessed the remote.","They think it''s the remote. It''s much deeper.","Tell them. ...They''ll treasure it."],"B:B":["...The remote, and {partner} knew it.","They know handing over the remote is basically a marriage proposal.","...Ha. Respect."]}}'::jsonb),
('DL-V20','adventure_friend_dl','Guess','{"id":"DL-V20","friendId":"adventure_friend_dl","type":"Guess","scene":"A door slams down the hall. Dillon jumps a full foot, lands, and stares at you.","lines":["...Obviously relevant. Don''t laugh."],"question":"When your partner gets startled, what happens?","selfQuestion":"When you get startled, what happens?","choices":[{"id":"A","label":"Jumps like an armadillo","reply":["...Jumps. Fellow jumper.","Vertical panic. I respect it."]},{"id":"B","label":"Freezes completely","reply":["...Freezes. Statue mode.","If I don''t move, it can''t see me."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["...Jumper, and {partner} knew it.","They''ve seen you leave the ground over a sneeze.","...Welcome to the club. I''m the president."],"A:B":["...You freeze. {partner} thought you''d jump.","They''re waiting for a leap. You just... stop.","...Statue mode. Also valid. Also scary."],"B:A":["...You jump. {partner} thought you''d freeze.","They''re about to see you hit the ceiling.","...Warn them. Or don''t. It''s funnier."],"B:B":["...Freezer, and {partner} knew it.","They know you turn into a statue when a door slams.","...Very calm. Very still. Very scared."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_dc','["Oh, dear, I couldn’t possibly leave without seeing {partner}. I’ll put the kettle on.","Oh, dear, I’ll just wait right here for {partner}. These scones won’t eat themselves."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('DC-V01','adventure_friend_dc','Trivia','{"id":"DC-V01","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess hesitates, then leans in delicately.","lines":["Oh, dear, this one''s a bit cheeky. But it''s true!"],"question":"Where do badgers go to the toilet?","selfQuestion":null,"choices":[{"id":"A","label":"In special pits called latrines","reply":["Oh, quite right, darling!","Badgers dig latrine pits, often near the edges of their territory.","They even double as boundary markers. Practical and polite."]},{"id":"B","label":"Right in the bedroom","reply":["Oh, dear heavens, NO.","They dig special pits called latrines, away from the sett.","We have standards. Very high standards."]},{"id":"C","label":"In a neighbor''s garden","reply":["Oh, dear, how rude! Though, occasionally...","They dig latrine pits away from the sett.","Tidy homes, tidy manners."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Badgers use dug latrine pits, often at territory boundaries.","coupleReplies":{}}'::jsonb),
('DC-V02','adventure_friend_dc','Trivia','{"id":"DC-V02","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess places a rose and an apple side by side, with a knowing smile.","lines":["Oh, dear, these two are related. Family secrets."],"question":"What do roses and apples have in common?","selfQuestion":null,"choices":[{"id":"A","label":"They both grow underground","reply":["Oh, dear, no.","They''re in the same plant family, the rose family.","Along with pears, cherries, and strawberries. A big, sweet family."]},{"id":"B","label":"They''re in the same plant family","reply":["Oh, splendid! Cousins indeed!","Roses, apples, pears, cherries, and strawberries are all in the rose family.","Bartholomew brings me both on our anniversary. Now I know why."]},{"id":"C","label":"Nothing at all","reply":["Oh, dear, they''re family!","Roses and apples are both in the rose family.","So an apple is, in a way, a rose''s cousin. Lovely."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Roses and apples are both in the family Rosaceae.","coupleReplies":{}}'::jsonb),
('DC-V03','adventure_friend_dc','Trivia','{"id":"DC-V03","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess pours two cups of tea and slides one to you.","lines":["Tea question! My specialty."],"question":"Black, green, white, and oolong tea all come from what?","selfQuestion":null,"choices":[{"id":"A","label":"The same plant: Camellia sinensis","reply":["Oh, well done!","It''s all how the leaves are dried, rolled, and oxidized.","One plant, many personalities. Like Bartholomew."]},{"id":"B","label":"Different plants for each kind","reply":["Oh, dear, it surprises everyone!","They all come from the same plant, Camellia sinensis.","The difference is how the leaves are processed. One plant, many moods."]},{"id":"C","label":"Lavender bushes","reply":["Oh, dear, lovely smell, wrong plant.","All true teas come from Camellia sinensis.","Herbal ''teas'' like chamomile are technically infusions."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Black, green, white and oolong teas come from Camellia sinensis.","coupleReplies":{}}'::jsonb),
('DC-V04','adventure_friend_dc','Trivia','{"id":"DC-V04","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess opens a tiny jar of golden-red threads, very carefully.","lines":["Oh, dear, this cost more than my hat. Spice question."],"question":"What is saffron, actually?","selfQuestion":null,"choices":[{"id":"A","label":"Ground-up golden rocks","reply":["Oh, dear, no rocks in my paella.","It''s the dried stigmas of a crocus flower.","Each flower has just three. Hand-picked. Very fancy."]},{"id":"B","label":"Tree sap","reply":["Oh, dear, sticky, but no.","It''s dried threads from crocus flowers.","Thousands of flowers make a small jar. Worth every penny."]},{"id":"C","label":"The dried thread-like parts of a crocus flower","reply":["Oh, well done, dear!","Each flower has just three threads, all picked by hand.","It takes thousands of flowers for a small amount. Precious."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Saffron is the dried stigmas of Crocus sativus, three per flower.","coupleReplies":{}}'::jsonb),
('DC-V05','adventure_friend_dc','Trivia','{"id":"DC-V05","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess touches a very old wooden table with deep respect.","lines":["About things that last. Like my marriage."],"question":"Bristlecone pines are among the oldest living things. How old can they get?","selfQuestion":null,"choices":[{"id":"A","label":"About 100 years","reply":["Oh, dear, far older!","Some bristlecone pines are over 4,000 years old.","Older than the pyramids. Puts my wrinkles in perspective."]},{"id":"B","label":"Over 4,000 years","reply":["Oh, splendid! Some are older than the pyramids!","One bristlecone pine is estimated at over 4,800 years old.","And I thought forty years was a long time."]},{"id":"C","label":"About 500 years","reply":["Oh, dear, keep going!","Some are over 4,800 years old.","Patient, twisty, and still growing. Inspiring."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Some Great Basin bristlecone pines exceed 4,800 years.","coupleReplies":{}}'::jsonb),
('DC-V06','adventure_friend_dc','Trivia','{"id":"DC-V06","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess shows you a sketch of a badger and a coyote side by side.","lines":["An unlikely friendship. My favorite kind."],"question":"Which animal sometimes hunts alongside American badgers?","selfQuestion":null,"choices":[{"id":"A","label":"The swan","reply":["Oh, dear, what a picture. But no.","It''s the coyote! They sometimes hunt together.","The badger digs, the coyote chases. Very efficient."]},{"id":"B","label":"The coyote","reply":["Oh, how thrilling! Yes!","The badger digs underground, the coyote waits above. Teamwork.","An odd couple. The best couples usually are."]},{"id":"C","label":"The house cat","reply":["Oh, dear, cats don''t share.","It''s the coyote. One digs, one chases.","Even wild animals know: teamwork makes the dream work."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"American badgers and coyotes sometimes hunt cooperatively.","coupleReplies":{}}'::jsonb),
('DC-V07','adventure_friend_dc','Trivia','{"id":"DC-V07","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess stirs her tea with a cinnamon stick, smiling.","lines":["Oh, dear, my secret ingredient. Do you know where it comes from?"],"question":"What is cinnamon?","selfQuestion":null,"choices":[{"id":"A","label":"The inner bark of a tree","reply":["Oh, splendid! Bark, indeed!","It curls into sticks as it dries.","Bartholomew thought it grew on bushes. Forty years and he still surprises me."]},{"id":"B","label":"A dried root","reply":["Oh, dear, close, but no.","Cinnamon is the inner bark of a tree.","It curls up into quills as it dries."]},{"id":"C","label":"A seed pod","reply":["Oh, dear, that''s vanilla or cardamom.","Cinnamon is tree bark.","Rolled up and dried. Simple and lovely."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Cinnamon is the dried inner bark of Cinnamomum trees.","coupleReplies":{}}'::jsonb),
('DC-V08','adventure_friend_dc','Trivia','{"id":"DC-V08","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess stands, bows to you, then does a slow little twirl.","lines":["Oh, dear, this one''s about a dance that lasts a lifetime."],"question":"What do Laysan albatross couples do to bond?","selfQuestion":null,"choices":[{"id":"A","label":"Build a nest of shiny things","reply":["Oh, dear, that''s a bowerbird.","Albatrosses do a whole synchronized dance together.","Partners often stay together for life. Lovely."]},{"id":"B","label":"Sing duets at night","reply":["Oh, how romantic. Not quite.","They perform an elaborate courtship dance.","Many pairs stay together for decades."]},{"id":"C","label":"A synchronized courtship dance","reply":["Oh, yes, darling! Bows, clacks, sky-pointing!","Pairs perform elaborate dances, and many stay together for decades.","Bartholomew and I still dance. Badly. Lovingly."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Laysan albatrosses perform synchronized courtship dances; pairs often bond for life.","coupleReplies":{}}'::jsonb),
('DC-V09','adventure_friend_dc','Trivia','{"id":"DC-V09","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess holds up an old photo of her and Bartholomew, then a recent one.","lines":["Oh, dear, people say old couples start to look alike. Do we?"],"question":"Do long-term couples'' faces really grow more alike over time?","selfQuestion":null,"choices":[{"id":"A","label":"Yes, they become identical","reply":["Oh, dear, Bartholomew has whiskers. I do not.","A large study found no real facial convergence over time.","Couples might just choose similar-looking partners to begin with."]},{"id":"B","label":"Only if they share toothbrushes","reply":["Oh, dear! Never!","A large study found no real evidence of faces converging.","We look alike in spirit, darling. Not in snout."]},{"id":"C","label":"A big study found no real evidence of it","reply":["Oh, how surprising!","A large 2020 study found couples'' faces don''t converge over the years.","People may pick partners who look alike from the start. Fancy that."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Tea-makorn & Kosinski (2020): no evidence of facial convergence in long-term couples.","coupleReplies":{}}'::jsonb),
('DC-V10','adventure_friend_dc','Trivia','{"id":"DC-V10","friendId":"adventure_friend_dc","type":"Trivia","scene":"Duchess knits a tiny cow-shaped tea cozy and holds it up.","lines":["Oh, dear, cows have best friends. I adore this."],"question":"What did a study find when cows were with their best friends?","selfQuestion":null,"choices":[{"id":"A","label":"They mooed louder","reply":["Oh, dear, perhaps, but no.","Cows were calmer and less stressed with their favorite buddy.","Friendship is a comfort, darling."]},{"id":"B","label":"They were calmer and less stressed","reply":["Oh, how sweet!","Cows showed lower stress when paired with a preferred buddy.","Everyone needs a best friend. Even cows. Even badgers."]},{"id":"C","label":"They ate less","reply":["Oh, dear, quite the opposite of stress-eating, but no.","Being with a preferred partner made cows calmer.","Lower heart rates. Happier hearts."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"McLennan (2013): heifers paired with preferred partners showed reduced stress responses.","coupleReplies":{}}'::jsonb),
('DC-V11','adventure_friend_dc','Preference','{"id":"DC-V11","friendId":"adventure_friend_dc","type":"Preference","scene":"Duchess flips through a worn photo album, landing on a café.","lines":["Bartholomew and I went here every Friday for 30 years."],"question":"Date night after years together: the old favorite spot, or somewhere brand new?","selfQuestion":null,"choices":[{"id":"A","label":"The old favorite","reply":["The old favorite. Oh, how lovely.","Same table, same order, same smile."]},{"id":"B","label":"Somewhere new","reply":["Somewhere new. Oh, adventurous!","New memories keep old love young."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Oh, the old favorite for both of you. How sweet.","Oh, I can just picture it: {partner} and you order without the menu now.","Tradition is a love language, darling."],"A:B":["Somewhere new for you. {partner} loves the old spot.","Oh, dear, take them somewhere new, then end at the old place for dessert.","Best of both. I''ve done this. It works."],"B:A":["The old favorite for you. {partner} wants somewhere new.","Oh, dear, alternate! Odd Fridays old, even Fridays new.","Or try a new dish at the old place. Gentle adventure."],"B:B":["Oh, somewhere new for both. How exciting!","Darling, you and {partner} are still exploring together. That''s the secret.","Bartholomew and I just started trying new places. At 70. Never too late."]}}'::jsonb),
('DC-V12','adventure_friend_dc','Preference','{"id":"DC-V12","friendId":"adventure_friend_dc","type":"Preference","scene":"Duchess unfolds a yellowed letter tied with ribbon.","lines":["This was from Bartholomew. In 1986."],"question":"Love letters: on paper, or in a text?","selfQuestion":null,"choices":[{"id":"A","label":"On paper","reply":["On paper. Oh, timeless.","Something to keep in a shoebox forever."]},{"id":"B","label":"In a text","reply":["In a text. Oh, modern and quick.","Instant love. My grandcubs approve."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Paper for both of you. Oh, how romantic.","I''d wager {partner} and you have a box of letters somewhere.","Read them again when you''re 80. You''ll cry. Happily."],"A:B":["Texts for you. {partner} prefers paper.","They want something to hold.","Print your favorite text. Hand it over. Sneaky and sweet."],"B:A":["Paper for you. {partner} prefers texts.","Oh, dear, write them one letter a year. Just one.","They''ll pretend it''s old-fashioned. They''ll keep it forever."],"B:B":["Texts for both of you. Oh, efficient love.","So you and {partner} probably screenshot the good ones.","My granddaughter says ''that''s the new shoebox.'' Clever girl."]}}'::jsonb),
('DC-V13','adventure_friend_dc','Preference','{"id":"DC-V13","friendId":"adventure_friend_dc","type":"Preference","scene":"Duchess strikes a match and lights a small candle on your table.","lines":["Oh, dear, keeping the spark alive. After 40 years, I''m an expert."],"question":"Keeping the spark: weekly date night, little daily surprises, or one big trip a year?","selfQuestion":null,"choices":[{"id":"A","label":"Weekly date night","reply":["Weekly date night. Oh, reliable romance.","Never let a week go by without each other."]},{"id":"B","label":"Little daily surprises","reply":["Daily surprises. Oh, how charming.","A note in a lunchbox, a flower on a pillow."]},{"id":"C","label":"One big trip a year","reply":["A big trip. Oh, how grand!","A whole year of looking forward to it."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Weekly date nights for both. Oh, how steady.","{partner} and you will never run out of Fridays.","Bartholomew and I never skipped one. Except for the flood of ''94."],"A:B":["Daily surprises for you. {partner} prefers a weekly date.","Oh, dear, sneak a surprise into every date night.","They''ll never see it coming. Every week."],"A:C":["Big trip for you. {partner} prefers weekly dates.","Oh, dear, plan the trip on your date nights.","Map out the adventure together. Very romantic."],"B:A":["Weekly dates for you. {partner} loves daily surprises.","Oh, dear, combine them! A tiny surprise on every date night.","A flower on the table. A note in the menu. Lovely."],"B:B":["Daily surprises for both. Oh, delightful.","Oh, I can just picture it: you and {partner} are always leaving little notes, aren''t you?","Small things, every day. That''s the real magic."],"B:C":["Big trip for you. {partner} loves daily surprises.","Oh, dear, hide trip hints in their daily surprises.","By the end of the year, they''ll know where you''re going."],"C:A":["Weekly dates for you. {partner} dreams of a big trip.","Oh, dear, save a little each date night for the big trip.","Romance and savings. Very sensible."],"C:B":["Daily surprises for you. {partner} wants a big trip.","Oh, dear, leave clues to the trip in little daily notes.","A treasure hunt to the airport. Charming!"],"C:C":["Big trips for both. Oh, adventurers!","Darling, {partner} and you probably plan the next one on the way home.","Send me a postcard, darling."]}}'::jsonb),
('DC-V14','adventure_friend_dc','Preference','{"id":"DC-V14","friendId":"adventure_friend_dc","type":"Preference","scene":"Duchess sits in your rocking chair and rocks slowly, smiling at the ceiling.","lines":["Let''s dream about growing old together."],"question":"Growing old together: rocking chairs on a porch, or a tiny adventure van?","selfQuestion":null,"choices":[{"id":"A","label":"Rocking chairs","reply":["Rocking chairs. Oh, I''m with you.","Slow evenings, lemonade, waving at neighbors."]},{"id":"B","label":"Adventure van","reply":["Adventure van. Oh, how daring!","Wrinkles and road trips."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Rocking chairs for both of you. Oh, so peaceful.","I''d wager {partner} and you will wave at every neighbor, every evening.","Bring a blanket. Porches get chilly."],"A:B":["The van for you. {partner} wants rocking chairs.","Oh, dear, roam first, rock later.","Bring the rocking chairs IN the van. Problem solved."],"B:A":["Rocking chairs for you. {partner} wants the van.","Oh, dear, take the van to visit porches!","Rock a little, roam a little."],"B:B":["Adventure van for both. Oh, how bold!","So you and {partner} will be the coolest grandparents ever.","Bartholomew wants one now. Oh, dear."]}}'::jsonb),
('DC-V15','adventure_friend_dc','Preference','{"id":"DC-V15","friendId":"adventure_friend_dc","type":"Preference","scene":"Duchess hums a waltz and sways slightly in your kitchen.","lines":["We still dance, Bartholomew and I."],"question":"Dancing in the kitchen: constantly, or only on special occasions?","selfQuestion":null,"choices":[{"id":"A","label":"Constantly","reply":["Constantly. Oh, how wonderful.","Dishes get done slower, but who cares."]},{"id":"B","label":"Only on special occasions","reply":["Special occasions. Oh, saving the magic.","Makes it feel extra special."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both dance constantly. Oh, how joyful!","{partner} and you probably waltz while the pasta boils.","Never stop. Even when your knees complain."],"A:B":["Special occasions for you. {partner} dances constantly.","Darling, they''re twirling while you''re stirring.","Join them once. Just one spin. You''ll see."],"B:A":["You dance constantly. {partner} saves it for special occasions.","Oh, dear, make every Tuesday a special occasion.","They''ll catch on. Then join in."],"B:B":["Special occasions only, both of you. Oh, how sweet.","Oh, I can just picture it: you and {partner} save the magic for birthdays and anniversaries.","When you do dance, it must feel like a movie."]}}'::jsonb),
('DC-V16','adventure_friend_dc','Guess','{"id":"DC-V16","friendId":"adventure_friend_dc","type":"Guess","scene":"Duchess settles in with tea and a look that says ''story time.''","lines":["Oh, dear, every couple has a favorite story."],"question":"What story does your partner love telling about you two?","selfQuestion":"What story do you love telling about you two?","choices":[{"id":"A","label":"How we met","reply":["How you met. Oh, the classic.","Every detail, every time."]},{"id":"B","label":"The time something went hilariously wrong","reply":["Something hilariously wrong. Oh, the best kind.","Disasters make the best stories."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["How you met, and {partner} knew it.","Oh, they''ve heard you tell it at every dinner party.","And they still smile. That''s love."],"A:B":["The disaster story for you. {partner} expected how you met.","Oh, dear, they think you''re sentimental. You''re a comedian.","Tell both. Start sweet, end with the disaster."],"B:A":["How you met for you. {partner} expected the disaster story.","Well, they think you''re all comedy. You''re a romantic.","Tell the sweet version tonight."],"B:B":["The disaster story, and {partner} knew it.","Ha! They''ve laughed at it a hundred times.","Bartholomew still tells the canoe story. I still blush."]}}'::jsonb),
('DC-V17','adventure_friend_dc','Guess','{"id":"DC-V17","friendId":"adventure_friend_dc","type":"Guess","scene":"Duchess tucks a quilt over your knees, very gently.","lines":["Caring for each other is everything."],"question":"When you''re sick, what would your partner bring you?","selfQuestion":"When your partner is sick, what would you bring them?","choices":[{"id":"A","label":"Soup and tea","reply":["Soup and tea. Oh, a classic healer.","Warm hands, warm bowls."]},{"id":"B","label":"A stack of comics","reply":["Comics. Oh, how fun!","Laughter is medicine."]},{"id":"C","label":"Every blanket in the house","reply":["Every blanket. Oh, a nest builder!","Burrito mode, activated."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Soup and tea, and {partner} knew it.","Oh, they know you''d arrive with a pot of soup and a teapot, both steaming.","Old-fashioned remedies. Bartholomew swears by my leek soup. Swears."],"A:B":["Comics for you. {partner} guessed soup and tea.","They think you''re the serious caretaker.","Laughter first, soup second. A balanced recovery."],"A:C":["Every blanket for you. {partner} guessed soup and tea.","Darling, they expected a bowl. You brought a blizzard of quilts.","Add one bowl. Make it perfect."],"B:A":["Soup and tea for you. {partner} guessed comics.","Bless them, they think you''re the fun one.","Bring both. Soup in one hand, comics in the other."],"B:B":["Comics, and {partner} knew it.","Oh, they know you''d prescribe a stack of comics and a silly voice for every character.","Laughter really is medicine, darling. The fun kind."],"B:C":["Every blanket for you. {partner} guessed comics.","Ha! They expected jokes. You brought warmth.","Read them comics from inside the fort."],"C:A":["Soup and tea for you. {partner} guessed blankets.","They think you''d smother them in quilts.","You''d smother them in soup. Lovely either way."],"C:B":["Comics for you. {partner} guessed blankets.","Oh, dear, comics under a blanket fort. Best sick day ever.","They''ll recover just to thank you."],"C:C":["Every blanket, and {partner} knew it.","Oh, they know you''ll build a fort around them.","Nobody stays cold on your watch."]}}'::jsonb),
('DC-V18','adventure_friend_dc','Guess','{"id":"DC-V18","friendId":"adventure_friend_dc","type":"Guess","scene":"Duchess hums softly while stirring her tea, then catches herself.","lines":["Bartholomew loves when I do that."],"question":"Which little habit of yours does your partner secretly love?","selfQuestion":"Which little habit of your partner''s do you secretly love?","choices":[{"id":"A","label":"Humming while cooking","reply":["Humming while cooking. Oh, how sweet.","The kitchen becomes a little concert."]},{"id":"B","label":"Talking to plants","reply":["Talking to plants. Oh, how charming.","The ferns are listening."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Humming, and {partner} knew it.","Oh, they love the background music of your kitchen.","Keep humming. Never stop."],"A:B":["Plant chats for you. {partner} guessed humming.","Oh, dear, they think it''s the humming. It''s the ferns.","Tell them which plant is your favorite."],"B:A":["Humming for you. {partner} guessed plant chats.","Well, they think it''s the plants. It''s the humming.","Hum to the plants. Double charm."],"B:B":["Talking to plants, and {partner} knew it.","Oh, they love how you say good morning to the ferns.","The ferns love it too, darling."]}}'::jsonb),
('DC-V19','adventure_friend_dc','Guess','{"id":"DC-V19","friendId":"adventure_friend_dc","type":"Guess","scene":"Duchess pulls a leather notebook from her bag. ''My memoir,'' she whispers.","lines":["Oh, dear, if love were a book..."],"question":"If your partner wrote your love story, what genre would it be?","selfQuestion":"If you wrote your love story, what genre would it be?","choices":[{"id":"A","label":"Cozy romance","reply":["Cozy romance. Oh, how lovely.","Candlelight, rain, and tea."]},{"id":"B","label":"Comedy of errors","reply":["Comedy of errors. Oh, how fun!","Chaos and laughter, chapter after chapter."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Cozy romance, and {partner} knew it.","Oh, they''d write chapter after chapter of cuddles.","A bestseller, I''m sure."],"A:B":["Comedy for you. {partner} guessed cozy romance.","They think it''s all candles. You remember the chaos.","Both are true. That''s the secret of 40 years."],"B:A":["Cozy romance for you. {partner} guessed comedy.","They think you see the chaos. You see the candlelight.","Co-write it. Romance with a funny chapter."],"B:B":["Comedy of errors, and {partner} knew it.","Bless them, they''d include every disaster.","The best love stories are the funny ones."]}}'::jsonb),
('DC-V20','adventure_friend_dc','Guess','{"id":"DC-V20","friendId":"adventure_friend_dc","type":"Guess","scene":"Duchess gazes out the window, smiling at something far away.","lines":["Forty years from now. Picture it, darling."],"question":"Forty years from now, what will your partner still do every morning?","selfQuestion":"Forty years from now, what will you still do every morning?","choices":[{"id":"A","label":"Make the tea for two","reply":["Tea for two. Oh, how lovely.","A morning ritual for a lifetime."]},{"id":"B","label":"Steal all the blankets","reply":["Steal the blankets. Oh, dear, a classic.","Some things never change."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Tea for two, and {partner} knew it.","Oh, a morning cup together forever.","Bartholomew makes mine. Forty years. Never missed one."],"A:B":["Blanket thief. {partner} guessed tea.","Well, they expected a warm cup. They got cold toes.","Make them tea as an apology. Every morning."],"B:A":["Tea for you. {partner} guessed blanket theft.","Ha! They think you''re a thief. You''re a tea maker.","Make the tea. Leave the blankets."],"B:B":["Blanket theft, and {partner} knew it.","Darling, they''ve accepted their fate.","Forty more years of cold toes. That''s commitment."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_ar','["Small thing, but I’d really like to say hi to {partner} before I go. Cracker?","Small thing, but I saved {partner} the best cracker. I’m guarding it till they’re back."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('AR-V01','adventure_friend_ar','Trivia','{"id":"AR-V01","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo shuffles in, sniffing your floorboards like they owe him money.","lines":["Small thing, but I brought a quiz. And crackers. Mostly crackers. Okay, question!"],"question":"What does the name ''aardvark'' mean?","selfQuestion":null,"choices":[{"id":"A","label":"Ant vacuum","reply":["Honestly accurate. Not the answer though.","It means ''earth pig,'' from Afrikaans.","We''re not pigs. We''re just enthusiastic about dirt."]},{"id":"B","label":"Earth pig","reply":["Yes! Earth pig. Pia calls me that when I hog the blanket.","It comes from Afrikaans: ''aarde'' means earth, ''vark'' means pig.","Not a pig, by the way. Just digs like one. Eats like one too."]},{"id":"C","label":"Snout king","reply":["I''ll take it as a compliment! But no.","It means ''earth pig'' in Afrikaans.","Pia says snout king is my royal title now. No take-backs."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"''Aardvark'' = ''earth pig'' (Afrikaans).","coupleReplies":{}}'::jsonb),
('AR-V02','adventure_friend_ar','Trivia','{"id":"AR-V02","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo holds up a red coffee cherry from a plant, squinting.","lines":["Small thing, but this is where coffee comes from. I didn''t know."],"question":"What are coffee beans, actually?","selfQuestion":null,"choices":[{"id":"A","label":"The seeds inside a cherry-like fruit","reply":["Yes! Coffee beans are seeds!","They grow inside red ''coffee cherries,'' usually two per fruit.","Pia''s morning mood depends on a fruit seed. Respect the seed."]},{"id":"B","label":"Beans from a bean plant, like green beans","reply":["Nope! Not related to green beans!","They''re seeds inside a red, cherry-like fruit.","The fruit is edible too. Sweet, even."]},{"id":"C","label":"Tree roots","reply":["Ha! No!","Coffee beans are seeds inside a red coffee cherry.","Pia would be very upset if coffee were roots."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Coffee beans are seeds of the coffee cherry (Coffea fruit).","coupleReplies":{}}'::jsonb),
('AR-V03','adventure_friend_ar','Trivia','{"id":"AR-V03","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo picks up a building block from your shelf and studies it.","lines":["This one is weird. Very weird."],"question":"Which animal makes cube-shaped poop?","selfQuestion":null,"choices":[{"id":"A","label":"Penguin","reply":["Penguins are elegant! No cubes!","It''s the wombat. Their poop comes out cube-shaped.","Their intestines have stretchy and stiff sections that form the corners."]},{"id":"B","label":"Giraffe","reply":["Ha! Imagine dropping that from that height.","It''s the wombat! Cubes!","They use the cubes to mark territory, and cubes don''t roll away. Genius."]},{"id":"C","label":"Wombat","reply":["YES. Wombat cubes! Nature''s dice!","Their intestines shape it into cubes as it dries.","They stack them to mark territory. Pia wants me to stop telling this at dinner."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Wombats produce cube-shaped feces.","coupleReplies":{}}'::jsonb),
('AR-V04','adventure_friend_ar','Trivia','{"id":"AR-V04","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo boops your nose with his paw, then looks at the paw.","lines":["Small thing, but dogs have a special ID system. Right there on their nose."],"question":"What''s unique about a dog''s nose print?","selfQuestion":null,"choices":[{"id":"A","label":"It changes color with the weather","reply":["Ha! Mood nose! No!","Every dog''s nose print has a unique pattern.","Like fingerprints, but cuter and wetter."]},{"id":"B","label":"Its pattern is unique, like a fingerprint","reply":["Yes! Unique nose prints!","Each dog''s nose has its own pattern of ridges and bumps.","Some places even use them for identification. Boop ID."]},{"id":"C","label":"All dogs have the same nose print","reply":["Nope! Every dog''s is different!","Nose prints are unique, like fingerprints.","Boop with confidence. Each boop is unique."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Dog nose prints have unique ridge patterns, comparable to fingerprints.","coupleReplies":{}}'::jsonb),
('AR-V05','adventure_friend_ar','Trivia','{"id":"AR-V05","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo puts his ear to the ground, eyes wide.","lines":["Small thing, but this happens only every 13 or 17 years."],"question":"What do periodical cicadas do between their emergences?","selfQuestion":null,"choices":[{"id":"A","label":"Migrate south for the winter","reply":["No flying south! They stay put. Underground.","Periodical cicadas spend 13 or 17 years underground feeding on root sap.","Then they all come up at once. Huge, loud party."]},{"id":"B","label":"Live underground, sipping tree roots, for 13 or 17 years","reply":["Yes! Long underground lives!","They drink sap from tree roots, then emerge all at once.","Billions sometimes. It''s like a surprise party that took 17 years to plan."]},{"id":"C","label":"Sleep in tree branches","reply":["Nope, they''re underground the whole time!","13 or 17 years below ground, sipping root sap.","Then they all pop up at once and sing their hearts out."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Periodical cicadas live underground 13 or 17 years feeding on xylem from roots.","coupleReplies":{}}'::jsonb),
('AR-V06','adventure_friend_ar','Trivia','{"id":"AR-V06","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo sticks his tongue out, very far, then quickly pulls it back in. Embarrassed.","lines":["Don''t be weird about this."],"question":"About how long can an aardvark''s tongue get?","selfQuestion":null,"choices":[{"id":"A","label":"About 12 inches","reply":["Yep! Basically a ruler!","Around 30 centimeters, long and sticky for scooping termites.","Pia once asked me to grab the remote with it. I did. We don''t talk about it."]},{"id":"B","label":"About 2 inches","reply":["Ha! Cute. Way longer.","Aardvark tongues can reach around 12 inches.","Perfect for slurping termites. Terrible for kissing. Pia disagrees."]},{"id":"C","label":"About 6 feet","reply":["Okay, that''s a garden hose, not a tongue!","It''s around 12 inches. Still very long!","Long enough to slurp tens of thousands of termites in a night."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Aardvark tongues reach ~30 cm (about 12 in).","coupleReplies":{}}'::jsonb),
('AR-V07','adventure_friend_ar','Trivia','{"id":"AR-V07","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo eats bamboo-flavored crackers very slowly, one after another.","lines":["Small thing, but pandas would beat me in a snack contest."],"question":"About how many hours a day can giant pandas spend eating?","selfQuestion":null,"choices":[{"id":"A","label":"About 1 hour","reply":["Way more! Way, way more!","Pandas can eat 10 to 16 hours a day.","Bamboo isn''t very nutritious, so they eat constantly."]},{"id":"B","label":"They don''t eat at all","reply":["A panda on a diet? Never!","They eat 10 to 16 hours a day.","Bamboo all day. The ultimate snack schedule."]},{"id":"C","label":"About 10 to 16 hours","reply":["Yes! Most of the day!","Bamboo has few nutrients, so pandas eat a LOT of it.","They''re basically professional snackers. Goals."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Giant pandas spend roughly 10–16 hours a day feeding.","coupleReplies":{}}'::jsonb),
('AR-V08','adventure_friend_ar','Trivia','{"id":"AR-V08","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo spots a photo of two prairie dogs touching faces on your wall.","lines":["This is the cutest greeting ever."],"question":"How do prairie dogs greet family members?","selfQuestion":null,"choices":[{"id":"A","label":"They high-five","reply":["Ha! Love it. Not it.","They touch teeth and noses, like a little kiss.","It helps them recognize their own family members."]},{"id":"B","label":"They ignore each other","reply":["Nope! Super social!","They greet with a ''kiss,'' touching teeth.","Family recognition. Very wholesome."]},{"id":"C","label":"They touch teeth, like a little kiss","reply":["Yes! A prairie dog kiss!","They press their mouths together to recognize family.","Pia and I tried. It was mostly nose. Still cute."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Prairie dogs greet relatives with ''greet kisses'' (touching teeth).","coupleReplies":{}}'::jsonb),
('AR-V09','adventure_friend_ar','Trivia','{"id":"AR-V09","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo fans himself with a paper plate.","lines":["Termites are smarter than my thermostat."],"question":"How do some termite mounds stay cool in hot weather?","selfQuestion":null,"choices":[{"id":"A","label":"The termites flap their wings constantly","reply":["Ha! Exhausting! No.","The mound''s tunnels and chimneys move air around.","Natural ventilation. Engineers took notes."]},{"id":"B","label":"Tunnels and chimneys move air through the mound","reply":["Yes! Natural air conditioning!","Air flows through chimneys and tunnels, helping keep the nest comfortable.","Architects have even copied the idea for buildings. Termites: honored."]},{"id":"C","label":"They put ice in the middle","reply":["Where would they get ice?!","The mound is built with air channels that help control temperature.","It''s basically a breathing building."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Termite mounds use passive ventilation; inspired Eastgate Centre design.","coupleReplies":{}}'::jsonb),
('AR-V10','adventure_friend_ar','Trivia','{"id":"AR-V10","friendId":"adventure_friend_ar","type":"Trivia","scene":"Arlo grabs your hand, then lets go, very shy.","lines":["Small thing, but this is the cutest fact ever."],"question":"What do sea otters sometimes do while they sleep?","selfQuestion":null,"choices":[{"id":"A","label":"Hold hands so they don''t drift apart","reply":["YES. I''m crying. They hold hands.","Sea otters often hold paws or wrap in kelp so they don''t float away.","Pia and I tried it. Our burrow doesn''t have currents. Still nice."]},{"id":"B","label":"Sleep on the beach in a pile","reply":["Nope! They sleep in the water.","They hold paws so they don''t drift apart.","Sometimes they wrap themselves in kelp too. Ocean blankets."]},{"id":"C","label":"Snore really loudly","reply":["Maybe! But that''s not the fact.","Sea otters hold hands so they don''t drift apart.","Love that keeps you anchored. Literally."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Sea otters sometimes hold paws or wrap in kelp while resting.","coupleReplies":{}}'::jsonb),
('AR-V11','adventure_friend_ar','Preference','{"id":"AR-V11","friendId":"adventure_friend_ar","type":"Preference","scene":"Arlo eyes your toothbrush cup with deep suspicion.","lines":["This matters to me. A lot."],"question":"Toothpaste: squeeze from the middle, from the end, or roll it up?","selfQuestion":null,"choices":[{"id":"A","label":"From the middle","reply":["A middle squeezer! No judgment.","Okay, a tiny bit of judgment. Pia does it too."]},{"id":"B","label":"From the end","reply":["From the end. Neat and tidy, I respect it.","The tube is calm. The tube feels safe."]},{"id":"C","label":"Roll it up","reply":["Rolled up?! You''re an artist.","Pia would like to meet you. Professionally."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["So you and {partner} are both middle squeezers! That''s lovely.","No tube wars in your house. Just chaos, shared equally.","Honestly, that''s what love is."],"A:B":["Neat and tidy from the end. I respect it.","But {partner} might still squeeze from the middle. Don''t fight, okay?","Think of their messy tube as a love note. A squished one."],"A:C":["Rolled up, so fancy.","{partner} squeezes from the middle. An artist and a rebel!","Be gentle when you fix it every morning. It''s love maintenance."],"B:A":["A middle squeezer, no judgment.","But {partner} squeezes from the end. Tiny tube war ahead.","Buy two tubes. Trust me. It saved my relationship."],"B:B":["You both squeeze from the end! A tidy household.","The tube in your bathroom is living its best life with {partner}.","Pia and I could never. We''ve tried. Twice."],"B:C":["You roll it up. {partner} squeezes from the end.","Two tidy approaches. That''s a strong team.","Just don''t swap tubes by accident. It''ll confuse everyone."],"C:A":["Middle squeezer! Rebel energy.","But {partner} rolls it up like a pro.","Let them fix the tube. You bring the snacks. Fair trade."],"C:B":["From the end, so neat.","{partner} rolls it up. You''re both tidy people. Rare!","Different technique, same energy. Tube-approved couple."],"C:C":["You both roll it up! Gallery-worthy bathroom.","Honestly, {partner} and you probably fold towels into swans too.","Pia and I are officially jealous. Teach us."]}}'::jsonb),
('AR-V12','adventure_friend_ar','Preference','{"id":"AR-V12","friendId":"adventure_friend_ar","type":"Preference","scene":"Arlo notices your window cracked open and sniffs the breeze.","lines":["Pia and I fight about this every single night."],"question":"Bedroom window at night: open a crack, or sealed shut?","selfQuestion":null,"choices":[{"id":"A","label":"Open a crack","reply":["Brave! Fresh air and a cold nose.","Pia would sleep with the window open in a snowstorm."]},{"id":"B","label":"Sealed shut","reply":["Cozy fortress mode. Respect.","A sealed burrow is a happy burrow."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both sleep with a crack open! Matching cold noses.","Nobody negotiates the window in your house. {partner} and you just agree.","Must be nice. Pia and I have a treaty."],"A:B":["Sealed shut for you. Cozy fortress.","But {partner} wants fresh air. Classic Pia-and-me energy.","Half-open window, extra blanket for you. Done. You''re welcome."],"B:A":["A crack of fresh air for you. Brave!","But {partner} wants it sealed shut. Cold nose versus warm blanket.","Try a tiny crack and an extra blanket on their side. Peace achieved."],"B:B":["You both like it sealed shut! A warm little fortress.","I can picture it: {partner} and you sleep like toasty burritos. No drafts allowed.","Sweet dreams, you two. Very jealous."]}}'::jsonb),
('AR-V13','adventure_friend_ar','Preference','{"id":"AR-V13","friendId":"adventure_friend_ar","type":"Preference","scene":"Arlo looks at your couch, then out the window, torn.","lines":["Small thing, but this is a big decision."],"question":"Perfect lazy day: stay in all day, or a picnic outside?","selfQuestion":null,"choices":[{"id":"A","label":"Stay in all day","reply":["Blanket fort life. I''m already there.","Snacks within arm''s reach. No shoes required."]},{"id":"B","label":"Picnic outside","reply":["Fresh air and cracker crumbs!","Ants as guests. They''ll bring friends."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Stay-in day for both of you! Blankets, snacks, zero plans.","{partner} and you don''t leave the couch. That''s an order.","Honestly the best kind of date."],"A:B":["Picnic for you. Yay sunshine!","But {partner} wants to stay in the blanket fort. Classic.","Take the blanket outside and nap in the sun. Both win."],"B:A":["Stay in for you. Blanket fort time.","But {partner} wants a picnic. Hmm.","Picnic in the living room. Crumbs included. Everyone''s happy."],"B:B":["Picnic for both of you! Fresh air date locked in.","Lowkey, you and {partner} probably have a picnic blanket ready by the door.","Pack crackers. Pack extra crackers. Ants are coming."]}}'::jsonb),
('AR-V14','adventure_friend_ar','Preference','{"id":"AR-V14","friendId":"adventure_friend_ar","type":"Preference","scene":"Arlo spots a sticky note on your fridge and smiles knowingly.","lines":["Apologies are my specialty. I do a lot of them."],"question":"After a small fight, what feels best?","selfQuestion":null,"choices":[{"id":"A","label":"A note","reply":["A note! Soft and sweet.","Written words can hug too."]},{"id":"B","label":"Saying it out loud","reply":["Out loud. Brave. Face to face.","Hard to say, easy to feel."]},{"id":"C","label":"A snack first, words after","reply":["The snack rule! Genius.","A crunch before a big feeling."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both pick notes! Tiny letter exchange.","{partner} and you probably have a drawer full of ''sorry'' notes.","Keep them. Read them on anniversaries. Cry a little."],"A:B":["Out loud for you. Brave!","But {partner} would rather get a note.","Say it, then leave a sticky note on their pillow. Double sorry."],"A:C":["Snack first, genius.","But {partner} would love a note.","Tuck the note under the snack plate. Crunch and read."],"B:A":["A note for you. Soft and sweet.","But {partner} needs to hear it out loud.","Write it, then read it to them. Both love languages covered."],"B:B":["You both say it out loud! Brave couple.","So you and {partner} just look each other in the eye and fix it.","That''s rare. Pia and I need snacks first."],"B:C":["A snack first for you. Smart.","{partner} wants to hear it out loud.","Snack, then talk. The full apology combo. Patent pending."],"C:A":["A note for you. Nice.","But {partner} wants a snack first.","Tape the note to a cookie. Perfect delivery system."],"C:B":["Out loud for you. So brave.","{partner} wants a snack first. Honestly, snacks make words easier.","Bring a cracker. Then speak. Trust the process."],"C:C":["Snack first, words after! You two follow the Arlo Rule.","Honestly, {partner} and you probably have a designated ''sorry snack.''","Pia and I are so proud of you."]}}'::jsonb),
('AR-V15','adventure_friend_ar','Preference','{"id":"AR-V15","friendId":"adventure_friend_ar","type":"Preference","scene":"Arlo peeks into your kitchen, humming off-key.","lines":["Kitchens are where relationships are tested."],"question":"Dinner at home: cook together, or one cooks and one cleans?","selfQuestion":null,"choices":[{"id":"A","label":"Cook together","reply":["Elbows and spoons! Chaos with kisses.","The soup might be bad. The night will be great."]},{"id":"B","label":"One cooks, one cleans","reply":["A well-oiled machine!","Efficient and secretly romantic."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both want to cook together! Elbows, spoons, chaos.","Every dinner with {partner} is a date. Soup optional.","Pia and I tried. The smoke alarm joined us."],"A:B":["One cooks, one cleans for you. Efficient.","But {partner} wants to cook side by side.","Let them stir the soup while you set the table. Close enough."],"B:A":["Cook together for you. So cute.","But {partner} likes one cooks, one cleans.","Cook together, then split the dishes. Or bribe them with dessert."],"B:B":["You both like split duty. Well-oiled team.","I can picture it: {partner} and you never argue about who does what. Efficient love.","Somebody give you two a trophy."]}}'::jsonb),
('AR-V16','adventure_friend_ar','Guess','{"id":"AR-V16","friendId":"adventure_friend_ar","type":"Guess","scene":"Arlo finds a party hat on your shelf and puts it on, very seriously.","lines":["Small thing, but this could go very wrong."],"question":"If you threw your partner a surprise party, how would they react?","selfQuestion":"If your partner threw you a surprise party, how would you react?","choices":[{"id":"A","label":"Love it","reply":["A party lover! Confetti everywhere.","They''ll be glowing all night."]},{"id":"B","label":"Hate it","reply":["Yikes, a quiet soul.","A surprise party is a gamble. Noted."]},{"id":"C","label":"Pretend to love it","reply":["The polite smile! I know it well.","Smiles outside, panic inside."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You''d love it, and {partner} called it!","They know you well. Start planning the confetti.","Pia threw me one. I cried. Happy tears."],"A:B":["You''d hate it, but {partner} guessed you''d love it. Yikes!","There might be a surprise party in your future.","Tell them now. Before the balloons arrive."],"A:C":["You''d pretend. But {partner} guessed you''d love it.","Your polite smile is very convincing. Too convincing.","Maybe tell them the truth gently. Over snacks."],"B:A":["You''d love it! But {partner} guessed you''d hate it.","They''ve been protecting you from parties for no reason.","Tell them you love surprises. Prepare for confetti."],"B:B":["You''d hate it, and {partner} knew!","They read you perfectly. No parties, ever.","Surprise quiet dinner instead. Much safer."],"B:C":["You''d pretend. But {partner} guessed you''d hate it.","They suspect more than you think.","Close enough. They''ll probably plan something small."],"C:A":["You''d love it, but {partner} thought you''d just pretend.","Your real joy looked fake to them. Oops!","Tell them it''s real. Then let them plan one."],"C:B":["You''d hate it. {partner} thought you''d pretend. So close!","They know you''d be polite. They just don''t know how much you''d suffer.","Be honest. They''ll plan a quiet dinner instead."],"C:C":["You''d pretend to love it, and {partner} guessed it! Busted.","They see right through your polite smile.","That''s real love. Seeing through the smile."]}}'::jsonb),
('AR-V17','adventure_friend_ar','Guess','{"id":"AR-V17","friendId":"adventure_friend_ar","type":"Guess","scene":"Arlo sniffs a glowing mushroom by your door, eyes wide.","lines":["This is a personality test."],"question":"Your partner finds a pretty glowing mushroom. What do they do?","selfQuestion":"You find a pretty glowing mushroom. What do you do?","choices":[{"id":"A","label":"Bring it home to share","reply":["A romantic! Glowing gifts are the best gifts.","Pia would cry."]},{"id":"B","label":"Tuck it away as a secret treasure","reply":["A collector! They have plans.","A secret mushroom museum is coming."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You''d bring it home to share, and {partner} knew!","They know you share every shiny thing you find.","Glowing gifts for everyone."],"A:B":["You''d keep it as a treasure. {partner} guessed you''d share.","They''re waiting for a glowing gift. It''s in your drawer.","Let them admire it. Just for a minute. Then hide it again."],"B:A":["You''d bring it home to share. {partner} guessed you''d keep it.","They think you''re a secret collector. You''re a sharer!","Surprise them tonight with the glow."],"B:B":["You''d keep it as a treasure, and {partner} called it!","They know about the secret collection. They''ve seen the drawer.","The mushroom museum is officially open."]}}'::jsonb),
('AR-V18','adventure_friend_ar','Guess','{"id":"AR-V18","friendId":"adventure_friend_ar","type":"Guess","scene":"Arlo notices a blanket draped over your couch and nods slowly.","lines":["Rough days happen. Pia had one yesterday. I brought crackers. It helped. Mostly."],"question":"After a rough day, what does your partner want?","selfQuestion":"After a rough day, what do you want?","choices":[{"id":"A","label":"Space and quiet","reply":["Quiet mode. Understood.","Sometimes a closed door is a hug."]},{"id":"B","label":"A big hug","reply":["A hugger! Arms ready.","Hugs fix half of everything."]},{"id":"C","label":"A snack and a rant","reply":["Snack and rant combo. Classic.","Bring the good crackers."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You want quiet, and {partner} knew!","That''s real attention. They give you space before you ask.","Gold star for {partner}. Quiet gold star."],"A:B":["You want a hug. {partner} guessed space.","They''re giving you room when you want arms.","Ask for the hug out loud. They''ll be so relieved."],"A:C":["You want a snack and a rant. {partner} guessed space.","They''re tiptoeing away. You''re holding crackers and complaints.","Call them back. Hand them a cracker. Start ranting."],"B:A":["You want quiet. {partner} guessed a hug.","They''re coming in with open arms. You need ten minutes alone.","Tell them: quiet first, hug later. A delayed hug still counts."],"B:B":["You want a big hug, and {partner} knew it!","Their arms were already open before you walked in.","That''s the dream, honestly."],"B:C":["You want a snack and a rant. {partner} guessed a hug.","They want to hold you. You want to vent.","Rant into the hug. Best of both."],"C:A":["You want quiet. {partner} guessed a snack and a rant.","They''re ready to listen. You''re ready to be silent.","Say ''quiet first, snacks later.'' They''ll get it."],"C:B":["You want a hug. {partner} guessed a snack and rant.","Close! Just add a hug to the snack.","Hug while ranting. Multitasking."],"C:C":["You want a snack and a rant, and {partner} guessed it!","They''ll bring the crackers and nod at every complaint.","Pia and I do this every Tuesday."]}}'::jsonb),
('AR-V19','adventure_friend_ar','Guess','{"id":"AR-V19","friendId":"adventure_friend_ar","type":"Guess","scene":"Arlo eyes a single cookie on your counter. He doesn''t move. Neither do you.","lines":["Small thing, but this one''s life or death."],"question":"One cookie left. What would your partner do?","selfQuestion":"One cookie left. What would you do?","choices":[{"id":"A","label":"Offer it to the other one","reply":["Aww, a generous soul.","I''d cry at the cookie."]},{"id":"B","label":"Eat it immediately","reply":["Ruthless! A real cookie monster.","No regrets. Delicious."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You''d offer it, and {partner} knew it!","They know you''d give away the last cookie every time.","Bake two next time. Everyone gets one."],"A:B":["You''d eat it immediately. {partner} thought you''d share.","They believed in your generosity. Oops.","Next time, break it in half. Rebuild their trust."],"B:A":["You''d offer it. {partner} thought you''d eat it immediately.","They underestimated your sweetness.","Hand it over. Watch them melt. Like the chocolate chips."],"B:B":["You''d eat it immediately, and {partner} knew!","They''ve watched you inhale it before. No hesitation.","Respect. Cookies wait for no one."]}}'::jsonb),
('AR-V20','adventure_friend_ar','Guess','{"id":"AR-V20","friendId":"adventure_friend_ar","type":"Guess","scene":"Arlo yawns very loudly, then looks at you like he''s sorry.","lines":["Sleep habits say everything. Everything."],"question":"How does your partner fall asleep?","selfQuestion":"How do you fall asleep?","choices":[{"id":"A","label":"Instantly, mid-sentence","reply":["Instantly! A sleep champion.","One second awake, next second gone."]},{"id":"B","label":"After scrolling for an hour","reply":["Scrolling for an hour. Relatable.","Just one more video. Then twelve more."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Instant sleeper, and {partner} knew!","They''ve watched you fall asleep mid-sentence. Many times.","Pia says I do it mid-word. Very efficient."],"A:B":["You scroll for an hour. {partner} thought you''d sleep instantly.","They''re asleep. You''re watching cooking videos.","Put the phone down. Or send them one in the morning."],"B:A":["You fall asleep instantly. {partner} thought you''d scroll.","They didn''t realize you''re gone the second your head hits the pillow.","Lucky you. Maybe teach them the trick."],"B:B":["Scrolling for an hour, and {partner} knew!","They''ve seen the glow of your phone at 1 a.m.","Respect. Just one more video, right?"]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_fn','["I can’t leave without seeing {partner}! What if it’s a SIGN?","I’ll just wait here for {partner}. Romantically. On your windowsill."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('FN-V01','adventure_friend_fn','Trivia','{"id":"FN-V01","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn holds a glass of water up to the light, gazing through it dreamily.","lines":["Imagine being so open your heart is visible."],"question":"Which frog has see-through skin on its belly?","selfQuestion":null,"choices":[{"id":"A","label":"The glass frog","reply":["YES! You can see its heart beating!","Glass frogs have transparent bellies showing their organs.","Literally wearing their heart on their skin. Goals."]},{"id":"B","label":"The bullfrog","reply":["Too chunky for transparency!","It''s the glass frog.","You can actually watch its heart beat. Iconic."]},{"id":"C","label":"The tree frog","reply":["Close, they''re cousins!","The glass frog has the see-through belly.","Visible heart. The most romantic frog alive."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Glass frogs have translucent ventral skin.","coupleReplies":{}}'::jsonb),
('FN-V02','adventure_friend_fn','Trivia','{"id":"FN-V02","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn clutches his stomach and flutters around your room.","lines":["Ribbit! I have butterflies! Real ones! Not real ones. Science ones!"],"question":"What causes the ''butterflies in your stomach'' feeling when you''re nervous or crushing?","selfQuestion":null,"choices":[{"id":"A","label":"Actual tiny butterflies","reply":["Ribbit! Imagine! No!","It''s adrenaline shifting blood away from your stomach.","Your body treats crushes like a big event. Because they are."]},{"id":"B","label":"Eating too fast","reply":["Sometimes that too! But not this!","It''s your stress response, sending blood away from your gut.","Nervous excitement. Heart racing. Stomach fluttering. Romance!"]},{"id":"C","label":"Stress hormones like adrenaline shifting blood away from your gut","reply":["YES! Your body''s fight-or-flight mode!","Adrenaline sends blood to your muscles, so your stomach feels fluttery.","It''s a SIGN your body thinks love is an emergency. It kind of is."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Butterflies are linked to sympathetic arousal (adrenaline), diverting blood from the digestive tract.","coupleReplies":{}}'::jsonb),
('FN-V03','adventure_friend_fn','Trivia','{"id":"FN-V03","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn blinks a flashlight on and off in a secret pattern.","lines":["That means ''I love you'' in firefly. Probably."],"question":"Why do fireflies flash their lights?","selfQuestion":null,"choices":[{"id":"A","label":"To scare away birds","reply":["They might warn predators too, but that''s not the main thing.","The flashing is mostly how they find mates.","Each species has its own blinking pattern."]},{"id":"B","label":"To find and attract mates","reply":["YES! Love lights!","Each species has its own flash pattern, like a love code.","Romance at night with built-in fairy lights. Swoon."]},{"id":"C","label":"To read at night","reply":["Ha! A tiny library!","It''s how they find and attract mates.","Every flash says ''Hey cutie.'' In firefly."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Fireflies use species-specific flash patterns for courtship.","coupleReplies":{}}'::jsonb),
('FN-V04','adventure_friend_fn','Trivia','{"id":"FN-V04","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn stares at a photo of Lily and his pupils go huge.","lines":["My brain is doing something. Something chemical. It''s LOVE."],"question":"What happens in the brain when you''re newly in love?","selfQuestion":null,"choices":[{"id":"A","label":"The brain goes completely quiet","reply":["Opposite! It''s a party in there!","Early love activates reward areas powered by dopamine.","Love is literally a natural high. It''s a SIGN."]},{"id":"B","label":"Reward areas light up with dopamine","reply":["YES! Love lights up the reward system!","Brain scans show early love activates dopamine-rich reward areas.","Lily is basically my dopamine. Is that romantic? It''s romantic."]},{"id":"C","label":"You forget your own name","reply":["Feels like it! But no.","Reward regions rich in dopamine become very active.","Brain scans proved it. Love is real chemistry."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"fMRI (Fisher, Aron et al.) shows early romantic love activates dopamine-rich reward regions (VTA, caudate).","coupleReplies":{}}'::jsonb),
('FN-V05','adventure_friend_fn','Trivia','{"id":"FN-V05","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn grabs your hands and does a slow little twirl with you.","lines":["It''s about a morning dance. It''s a SIGN."],"question":"What do seahorse couples do each morning?","selfQuestion":null,"choices":[{"id":"A","label":"Do a greeting dance together","reply":["YES! Every morning! A dance!","Seahorse partners greet each other with a little dance, sometimes changing color.","Lily and I started doing this. She''s better than me."]},{"id":"B","label":"Swim in opposite directions","reply":["Ouch! No!","They do a morning greeting dance together.","Twirling, color changes, tail holding. Romance."]},{"id":"C","label":"Sleep in until noon","reply":["Ha! Relatable. But no!","They meet each morning for a greeting dance.","Some even link tails. I''m crying."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Seahorse pairs perform daily greeting rituals.","coupleReplies":{}}'::jsonb),
('FN-V06','adventure_friend_fn','Trivia','{"id":"FN-V06","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn wraps a scarf around his neck and shivers dramatically.","lines":["Winter is coming. Like my feelings."],"question":"What can wood frogs do to survive winter?","selfQuestion":null,"choices":[{"id":"A","label":"Fly south with the birds","reply":["Frogs can''t fly. Tragically.","They freeze almost solid and thaw out in spring.","Natural antifreeze protects their cells. Science romance."]},{"id":"B","label":"Knit a sweater","reply":["Ha! Cozy, but no.","They freeze almost solid and thaw in spring.","Their bodies make natural antifreeze to protect their cells."]},{"id":"C","label":"Freeze solid, then thaw in spring","reply":["YES! It''s wild!","Their hearts stop, they freeze, then thaw and hop away in spring.","Like love after a breakup. It always comes back."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Wood frogs survive partial freezing and thaw in spring.","coupleReplies":{}}'::jsonb),
('FN-V07','adventure_friend_fn','Trivia','{"id":"FN-V07","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn holds up a photo of a tiny round rodent couple snuggling.","lines":["These are my favorite romantics after frogs. Prairie voles!"],"question":"Why are prairie voles famous in love research?","selfQuestion":null,"choices":[{"id":"A","label":"They''re the fastest runners","reply":["Not really known for speed!","They form lifelong pair bonds, unlike most rodents.","Scientists learned a lot about bonding hormones from them."]},{"id":"B","label":"They change color when in love","reply":["Ribbit! I wish! No!","They form strong, often lifelong pair bonds.","They''re used to study oxytocin and vasopressin. Love science."]},{"id":"C","label":"They form strong lifelong pair bonds","reply":["YES! Little lovebirds, but voles!","They pair up for life, and scientists study them to understand bonding hormones.","Oxytocin heroes. I aspire to be a vole."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Prairie voles are socially monogamous and a model for pair-bonding neurobiology (oxytocin/vasopressin).","coupleReplies":{}}'::jsonb),
('FN-V08','adventure_friend_fn','Trivia','{"id":"FN-V08","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn crawls through your yard on his hands and knees, searching the clover.","lines":["I''m looking for a sign. A four-leaf sign. Very rare."],"question":"About how rare is a four-leaf clover?","selfQuestion":null,"choices":[{"id":"A","label":"1 in 4","reply":["Too common! Not a sign at all!","It''s roughly 1 in 5,000 to 10,000 clovers.","Rare enough to feel magical."]},{"id":"B","label":"Roughly 1 in 5,000 to 10,000","reply":["YES! Very rare! A real SIGN!","Most clovers have three leaves. Four is a rare genetic quirk.","If you find one, it''s basically the universe winking at you."]},{"id":"C","label":"They don''t exist","reply":["They exist! I''ve found three! Signs!","About 1 in 5,000 to 10,000 clovers have four leaves.","Keep searching. It''s worth it."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Estimates commonly cite ~1 in 5,000–10,000 white clovers as four-leaved.","coupleReplies":{}}'::jsonb),
('FN-V09','adventure_friend_fn','Trivia','{"id":"FN-V09","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn flaps his arms frantically, trying to hover in place. He fails.","lines":["These little birds can do something even I can''t. And I''m a frog."],"question":"What can hummingbirds do that no other birds can?","selfQuestion":null,"choices":[{"id":"A","label":"Fly backwards","reply":["YES! Backward flying!","Hummingbirds can hover, fly backward, and even briefly upside down.","Imagine flying backward into someone''s arms. Romantic AND efficient."]},{"id":"B","label":"Swim underwater","reply":["Ribbit, that''s my job!","Hummingbirds are the only birds that can truly fly backward.","Wings beating dozens of times a second. Tiny powerhouses."]},{"id":"C","label":"Sleep while flying","reply":["Some birds can! But not this one!","Hummingbirds are the only birds that can fly backward.","They hover like tiny helicopters. Precious."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Hummingbirds can hover and fly backward, unique among birds.","coupleReplies":{}}'::jsonb),
('FN-V10','adventure_friend_fn','Trivia','{"id":"FN-V10","friendId":"adventure_friend_fn","type":"Trivia","scene":"Fenn stares into the eyes of a puppy in a photo, smiling dreamily.","lines":["Love isn''t just for frogs. It''s for dogs too. And their humans."],"question":"What happens when dogs and their owners gaze into each other''s eyes?","selfQuestion":null,"choices":[{"id":"A","label":"The dog gets sleepy","reply":["Maybe! But that''s not the finding!","Mutual gazing increased oxytocin in both dog and owner.","Bonding through eyes. Pure romance."]},{"id":"B","label":"Both get a boost of oxytocin, the bonding hormone","reply":["YES! Love hormone for both!","A study found mutual gazing raised oxytocin in dogs and their owners.","Eye contact equals love. It''s a SIGN. For everyone."]},{"id":"C","label":"The owner sneezes","reply":["Allergies! But no!","Both dog and owner showed a boost in oxytocin.","Your dog loves you scientifically."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Nagasawa et al. (2015): owner–dog mutual gaze increased oxytocin in both.","coupleReplies":{}}'::jsonb),
('FN-V11','adventure_friend_fn','Preference','{"id":"FN-V11","friendId":"adventure_friend_fn","type":"Preference","scene":"Fenn collapses onto your couch with both hands over his heart.","lines":["Brace your heart. Love stories. Mine was love at first sight. Obviously."],"question":"Your love story: love at first sight, or friends first?","selfQuestion":null,"choices":[{"id":"A","label":"Love at first sight","reply":["Love at first sight! Fireworks! Violins!","Zing. I knew it the moment Lily croaked hello."]},{"id":"B","label":"Friends first","reply":["Friends first. Oh, that''s so sweet.","Best friend turned love. My favorite plot."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Love at first sight for both of you! It''s a SIGN!","{partner} saw you and you saw them and the universe just... clicked.","I''m crying. Ribbit. Sorry. Crying."],"A:B":["Friends first for you. {partner} says love at first sight.","They were head over heels on day one. You were just being friendly.","They''ve been patient this whole time. Give them a big hug."],"B:A":["Love at first sight for you. {partner} says friends first.","So you were in love from day one, and they took the scenic route.","Plot twist: you were waiting for them to catch up. Romantic!"],"B:B":["Friends first for both of you. Slow burn magic.","So you and {partner} were best friends who slowly fell. Movie plot.","The best love stories start with ''we were just friends.''"]}}'::jsonb),
('FN-V12','adventure_friend_fn','Preference','{"id":"FN-V12","friendId":"adventure_friend_fn","type":"Preference","scene":"Fenn holds up a ukulele with one string. He strums it. It''s bad.","lines":["Ribbit! Sorry. Excited. Grand gestures. I''m practicing one."],"question":"Grand gesture: a public serenade, or a private candlelit picnic?","selfQuestion":null,"choices":[{"id":"A","label":"Public serenade","reply":["Public serenade! Bold! Iconic! Terrifying!","Strangers clapping. Partner blushing. Perfect."]},{"id":"B","label":"Private picnic","reply":["Private picnic. Candles, cheese, whispers.","Intimate. Classy. Swoon."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Public serenade for both of you! Showstoppers!","Honestly, {partner} and you would serenade each other in the middle of a mall.","Bring a tambourine. For backup."],"A:B":["Private picnic for you. {partner} wants a public serenade.","They want the spotlight. You want the candlelight.","Let them sing at your picnic. Just you, them, and the moon."],"B:A":["Public serenade for you. {partner} wants a private picnic.","You''ll sing in a crowd. They''ll want to hide behind a basket.","Serenade them AT the picnic. Private concert. Audience of one."],"B:B":["Private picnic for both of you. Intimate love.","I can picture it: you and {partner} would light candles in a secret meadow.","Just watch for ants. They crash every picnic."]}}'::jsonb),
('FN-V13','adventure_friend_fn','Preference','{"id":"FN-V13","friendId":"adventure_friend_fn","type":"Preference","scene":"Fenn points at the sky, then the window, then the pond outside, overwhelmed.","lines":["Oh my lily pads. Dream date. I have too many ideas."],"question":"Dream date: under the stars, dancing in the rain, or by the water?","selfQuestion":null,"choices":[{"id":"A","label":"Under the stars","reply":["Under the stars! Constellations as witnesses!","I''d name a star after Lily. I did. It''s unofficial."]},{"id":"B","label":"Dancing in the rain","reply":["Dancing in the rain! Movie scene!","Wet hair, big smiles, zero regrets."]},{"id":"C","label":"By the water","reply":["By the water! My home turf!","Ripples, reflections, and a gentle breeze."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Stars for both of you! It''s a SIGN!","Lie on a blanket with {partner} and count the stars.","Wish on a shooting star. Wish for each other. Done."],"A:B":["Rain for you. {partner} wants to stargaze.","Dance in the rain until it clears. Then look up.","The stars come out just for you two."],"A:C":["Water for you. {partner} wants the stars.","Find a lake with an open sky.","Reflections and constellations. A cosmic date."],"B:A":["Stars for you. {partner} wants to dance in the rain.","Wait for the rain to stop. Then stargaze in wet clothes.","It''s a SIGN of commitment."],"B:B":["Rain for both of you! Movie couple!","Pretty sure you and {partner} will splash in puddles while everyone else runs for cover.","Umbrellas are for people without romance."],"B:C":["Water for you. {partner} wants to dance in the rain.","Rain on a lake. The prettiest sound.","Splash, dance, kiss. Repeat."],"C:A":["Stars for you. {partner} wants to be by the water.","A lake at night. Stars reflected in the water.","Double the stars. Double the romance."],"C:B":["Rain for you. {partner} wants to be by the water.","Dance in the rain by a lake. Water everywhere.","Very wet. Very romantic. Very froggy."],"C:C":["Water for both of you! Pond people!","Picture it: {partner} and you by a lake at sunset. Postcard material.","Skip stones. Make wishes. I''ll provide the frogs."]}}'::jsonb),
('FN-V14','adventure_friend_fn','Preference','{"id":"FN-V14","friendId":"adventure_friend_fn","type":"Preference","scene":"Fenn writes ''Month 47'' on your calendar in glitter pen.","lines":["Listen. LISTEN. Anniversaries. I celebrate them monthly. Lily thinks I''m extra."],"question":"Anniversaries: celebrate the monthly ones too, or just the yearly one?","selfQuestion":null,"choices":[{"id":"A","label":"Monthly too","reply":["Monthly too! YES! Every month is a gift!","Twelve chances a year to be cheesy."]},{"id":"B","label":"Just yearly","reply":["Just yearly. Save the magic.","One big day. Very special."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Monthly celebrations for both of you! Extra couple!","{partner} and you probably have a cupcake every month.","It''s a SIGN you''re both as extra as me. I love it."],"A:B":["Yearly for you. {partner} wants monthly too.","They''ll show up with a cupcake every month. Brace yourself.","Let them. Eat the cupcake. Say thank you. It''s love."],"B:A":["Monthly for you. {partner} prefers just yearly.","They''ll be surprised every month. You''ll be delighted.","Keep monthly ones tiny. A note. A cookie. Not a parade."],"B:B":["Yearly for both of you. Classic and meaningful.","So you and {partner} make one day a year really count.","Big, beautiful, once a year. Like a comet."]}}'::jsonb),
('FN-V15','adventure_friend_fn','Preference','{"id":"FN-V15","friendId":"adventure_friend_fn","type":"Preference","scene":"Fenn finds a heart-shaped pebble and gasps loudly.","lines":["Ribbit. Do you see what I see? It''s a SIGN."],"question":"Do you believe in signs?","selfQuestion":null,"choices":[{"id":"A","label":"Absolutely","reply":["Absolutely! Welcome to my world!","Heart-shaped clouds, matching songs. Signs everywhere."]},{"id":"B","label":"Not really","reply":["Not really. Grounded. Practical.","Maybe the signs will find you anyway."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both believe in signs! It''s a SIGN!","Honestly, {partner} and you probably screenshot every lucky coincidence.","Cosmic couple. I''m adopting you both."],"A:B":["You don''t believe. {partner} totally does.","They''ll see signs everywhere. You''ll see coincidences.","Let them have it. Their joy is the real sign."],"B:A":["You believe. {partner} doesn''t.","You''ll point out heart-shaped clouds. They''ll say ''it''s a cloud.''","Keep pointing. One day they''ll see it."],"B:B":["Neither of you believes in signs. Practical love.","I can picture it: you and {partner} don''t need signs. You chose each other.","Honestly, that''s the biggest sign of all."]}}'::jsonb),
('FN-V16','adventure_friend_fn','Guess','{"id":"FN-V16","friendId":"adventure_friend_fn","type":"Guess","scene":"Fenn stares into your eyes intensely. Then blushes and looks away.","lines":["Don''t laugh. First impressions."],"question":"What did your partner notice first about you?","selfQuestion":"What did you notice first about your partner?","choices":[{"id":"A","label":"The smile","reply":["The smile! Heart-melting.","One smile and it''s over."]},{"id":"B","label":"The laugh","reply":["The laugh! Musical!","A laugh you can''t forget."]},{"id":"C","label":"The outfit","reply":["The outfit! Fashion romance.","Love at first fit."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["The smile, and {partner} knew it!","They''ve always known your smile had power over them.","It''s a SIGN. Smile at them right now."],"A:B":["It was the laugh for you. {partner} guessed the smile.","They think it was the smile. It was the sound.","Laugh together. Prove it."],"A:C":["It was the outfit for you. {partner} guessed the smile.","They think you fell for their smile. You fell for their jacket.","Honest. Fashion matters. It''s a SIGN."],"B:A":["It was the smile for you. {partner} guessed the laugh.","They think it was the laugh. It was the smile.","Tell them. Watch them smile again."],"B:B":["The laugh, and {partner} knew it!","They know your laugh is your secret weapon.","Laugh at their next joke. Even the bad ones."],"B:C":["It was the outfit for you. {partner} guessed the laugh.","They think you heard them first. You saw them first.","Wear that outfit on your next date."],"C:A":["It was the smile for you. {partner} guessed the outfit.","They think you noticed the clothes. You noticed the face.","Tell them their outfit was nice, but the smile won."],"C:B":["It was the laugh for you. {partner} guessed the outfit.","They think it was the fashion. It was the giggle.","Laughing in a cute outfit. Combo."],"C:C":["The outfit, and {partner} knew it!","They know they dressed to impress that day.","Wear it again on your anniversary. Full circle."]}}'::jsonb),
('FN-V17','adventure_friend_fn','Guess','{"id":"FN-V17","friendId":"adventure_friend_fn","type":"Guess","scene":"Fenn leans close and whispers, ''Are you a pond? Because I''m drowning.''","lines":["Okay. Deep breath. Pickup lines."],"question":"How does your partner react to a cheesy pickup line?","selfQuestion":"How do you react to a cheesy pickup line?","choices":[{"id":"A","label":"Groans, but blushes","reply":["Groans but blushes! Classic!","Pretends to hate it. Secretly loves it."]},{"id":"B","label":"Fires one right back","reply":["Fires one right back! A worthy opponent!","Pickup line battle. Nobody wins. Everyone giggles."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Groan-and-blush, and {partner} knew it!","They know your eye-roll always ends in a smile.","Keep the cheesy lines coming. It''s a love language."],"A:B":["You fire one back. {partner} expected a blushing groan.","They thought you''d melt. You came back swinging.","Your comeback game is strong. Respect."],"B:A":["You groan and blush. {partner} expected you to fire back.","They''re ready for battle. You''re just pink.","Fire one back next time. Shock them."],"B:B":["Firing one right back, and {partner} knew it!","Pickup line duels are your thing.","It''s a SIGN you''re both ridiculous. Perfect match."]}}'::jsonb),
('FN-V18','adventure_friend_fn','Guess','{"id":"FN-V18","friendId":"adventure_friend_fn","type":"Guess","scene":"Fenn sniffles into a tissue, holding a rom-com DVD.","lines":["Oh, this one''s good. Rom-com endings. They destroy me."],"question":"How does your partner react to a rom-com ending?","selfQuestion":"How do you react to a rom-com ending?","choices":[{"id":"A","label":"Cries every single time","reply":["Cries every time! A true romantic!","Tissues on standby. Always."]},{"id":"B","label":"Rolls eyes, secretly loved it","reply":["Eye-roll, secret love. Classic!","Too cool to cry. Too soft to hate it."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You cry every time, and {partner} knew it!","They hand you tissues before the airport scene.","Cry proudly. I do. Every time."],"A:B":["You roll your eyes. {partner} expected tears.","They''re ready with tissues. You''re judging the plot.","Next time, cry a little. For them."],"B:A":["You cry every time. {partner} expected an eye-roll.","They thought you were too cool. You''re a puddle.","Show them your tears. It''s a SIGN of a big heart."],"B:B":["The eye-roll, and {partner} knew it!","They know you secretly loved it.","They saw you smile. You can''t hide."]}}'::jsonb),
('FN-V19','adventure_friend_fn','Guess','{"id":"FN-V19","friendId":"adventure_friend_fn","type":"Guess","scene":"Fenn kisses the air, then blows another kiss toward the window.","lines":["I''m emotional already. Rituals. I have 14."],"question":"Which daily ritual would your partner never skip?","selfQuestion":"Which daily ritual would you never skip?","choices":[{"id":"A","label":"Goodnight kiss","reply":["Goodnight kiss! Every single night!","Sleep doesn''t count without it."]},{"id":"B","label":"Morning ''good morning'' text","reply":["Good morning text! Sunrise love!","First thing they think of: you."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Goodnight kiss, and {partner} knew it!","They know no night ends without one.","Never skip. It''s a SIGN of forever."],"A:B":["Morning text for you. {partner} guessed a goodnight kiss.","They think it''s the kiss. It''s the text.","Kiss them tonight anyway. Bonus love."],"B:A":["Goodnight kiss for you. {partner} guessed a morning text.","They think mornings matter. You think nights matter.","Do both. Text at sunrise. Kiss at moonrise."],"B:B":["Good morning text, and {partner} knew it!","Their phone lights up with your love every morning.","Sunrise and you. Perfect start."]}}'::jsonb),
('FN-V20','adventure_friend_fn','Guess','{"id":"FN-V20","friendId":"adventure_friend_fn","type":"Guess","scene":"Fenn gasps and points at the window. ''A shooting star!'' It was a plane.","lines":["Ribbit, ribbit. Wishes!"],"question":"If your partner saw a shooting star, what would they wish for?","selfQuestion":"If you saw a shooting star, what would you wish for?","choices":[{"id":"A","label":"Something for you two","reply":["Something for you two. Aww!","Their wish is about you. Swoon."]},{"id":"B","label":"Unlimited snacks","reply":["Unlimited snacks! Honest!","Priorities. Respect."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Something for you two, and {partner} knew it!","They know your wishes always include them.","It''s a SIGN. Forever and ever."],"A:B":["Unlimited snacks. {partner} thought you''d wish for you two.","They''re touched. Then confused. Then hungry.","Share your wish snacks. Romance saved."],"B:A":["Something for you two. {partner} guessed unlimited snacks.","They thought you''d wish for snacks. You wished for them.","Tell them. They''ll melt like chocolate."],"B:B":["Unlimited snacks, and {partner} knew it!","They know your heart, and your stomach.","Share the snacks. That''s love."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_os','["Okay, hear me out. I’ll wait for {partner}. Unless that’s weird. Is it weird? I’ll wait.","I rehearsed my ‘hi {partner}’ three times. I’m ready. Just waiting now."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('OS-V01','adventure_friend_os','Trivia','{"id":"OS-V01","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin glides in, lands on your lamp, and stares at the room for slightly too long.","lines":["Okay, hear me out. I rehearsed this quiz four times. In the mirror. At 3 a.m."],"question":"About how far can an owl turn its head?","selfQuestion":null,"choices":[{"id":"A","label":"A full 360 degrees","reply":["Close, but owls aren''t horror movie props.","It''s about 270 degrees, thanks to extra neck vertebrae.","Still enough to see behind me. Constantly. Anxiously."]},{"id":"B","label":"Only 90 degrees","reply":["That would really limit my overthinking.","It''s about 270 degrees. Owls have 14 neck vertebrae.","Humans have seven. Owls have double the neck. Double the worry."]},{"id":"C","label":"About 270 degrees","reply":["Correct. Three-quarters of a circle. Great for looking back on my mistakes.","Extra neck bones and special blood vessels make it possible.","Juno says I could look over my shoulder and still worry about what''s ahead."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Owls can rotate their heads ~270°; they have 14 cervical vertebrae.","coupleReplies":{}}'::jsonb),
('OS-V02','adventure_friend_os','Trivia','{"id":"OS-V02","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin hears a low humming in the night outside and tilts his head.","lines":["Okay, hear me out. Giraffes might be humming right now."],"question":"What did researchers discover giraffes do at night?","selfQuestion":null,"choices":[{"id":"A","label":"Sing loud opera","reply":["Dramatic. Not accurate.","They hum at night, in a low tone.","The reason is still a mystery. I love a mystery."]},{"id":"B","label":"Hum at a very low pitch","reply":["Correct. Night humming.","Researchers recorded giraffes humming at night, though no one is sure why yet.","Maybe they''re overthinking too. Same, giraffe. Same."]},{"id":"C","label":"Sleep standing on one leg","reply":["That''s flamingos.","Giraffes have been recorded humming at night.","Nobody knows why. Possibly existential humming."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Baotic et al. (2015) recorded giraffes producing low-frequency hums at night.","coupleReplies":{}}'::jsonb),
('OS-V03','adventure_friend_os','Trivia','{"id":"OS-V03","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin turns off your lights, then points at a faintly glowing log in the corner.","lines":["I brought this. It glows. I''ve been staring at it since midnight."],"question":"What makes some rotting wood glow in the dark?","selfQuestion":null,"choices":[{"id":"A","label":"Fireflies stuck inside","reply":["Poor fireflies. But no.","It''s glowing fungi, called foxfire.","The glow comes from a chemical reaction in the fungus."]},{"id":"B","label":"Glowing fungi","reply":["Correct. It''s called foxfire.","Certain fungi produce a soft green bioluminescent glow.","Nature''s night-light. Perfect for 3 a.m. thoughts."]},{"id":"C","label":"Moonlight trapped in the bark","reply":["Poetic. Wrong.","Some fungi glow, a phenomenon called foxfire.","It''s bioluminescence. Like fireflies, but mushrooms."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Foxfire is bioluminescence from fungi on decaying wood.","coupleReplies":{}}'::jsonb),
('OS-V04','adventure_friend_os','Trivia','{"id":"OS-V04","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin stares at an octopus documentary on your TV, wide-eyed.","lines":["This creature has blue blood. And I thought I was dramatic."],"question":"Why is an octopus''s blood blue?","selfQuestion":null,"choices":[{"id":"A","label":"It uses copper, not iron, to carry oxygen","reply":["Correct. Copper-based blood.","Their blood uses hemocyanin, which contains copper and turns blue with oxygen.","Plus three hearts. Overachiever."]},{"id":"B","label":"They drink blue water","reply":["Creative. No.","It''s because their blood carries oxygen with copper.","Hemocyanin. Very fancy."]},{"id":"C","label":"They''re cold","reply":["Cold-blooded joke. Ha. No.","Copper-based hemocyanin makes their blood blue.","Three hearts, blue blood. Very aristocratic."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Octopus blood uses copper-based hemocyanin, which is blue when oxygenated.","coupleReplies":{}}'::jsonb),
('OS-V05','adventure_friend_os','Trivia','{"id":"OS-V05","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin gazes at a pale flower by your window that just opened.","lines":["Night bloomers are my people. We open up after dark. Emotionally, too."],"question":"When do moonflowers usually bloom?","selfQuestion":null,"choices":[{"id":"A","label":"At noon","reply":["Too much sun for them. And me.","They bloom in the evening and close in the morning.","Night flowers for night creatures."]},{"id":"B","label":"Only during thunderstorms","reply":["Dramatic. Not true.","Moonflowers open in the evening.","Their pale petals glow in the moonlight. Very romantic."]},{"id":"C","label":"At night","reply":["Correct. Fellow night owl.","Moonflowers open in the evening and close in the morning sun.","Night-blooming flowers often attract moths. My safe word. Coincidence?"]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Moonflowers (Ipomoea alba) bloom at night.","coupleReplies":{}}'::jsonb),
('OS-V06','adventure_friend_os','Trivia','{"id":"OS-V06","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin flies across your room without a single sound. You don''t even notice until he''s beside you.","lines":["Sorry. Habit. Silent entrances. I forget other people have heartbeats."],"question":"Why can owls fly so quietly?","selfQuestion":null,"choices":[{"id":"A","label":"They flap very slowly and politely","reply":["Polite, yes. But that''s not it.","The secret is soft, fringed feathers that muffle airflow.","Engineers even study them for quieter fans."]},{"id":"B","label":"They hold their breath while flying","reply":["I''d faint. Honestly, I''d overthink fainting.","It''s the soft, fringed feathers that muffle airflow.","Nature''s noise cancellation. Better than headphones."]},{"id":"C","label":"Soft fringed feathers break up the sound","reply":["Exactly. You''re quiet-smart too.","Velvety, comb-edged feathers break up the airflow noise.","Juno says I''m silent everywhere except in my own head."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Owl feathers'' serrated edges and velvety surfaces reduce flight noise.","coupleReplies":{}}'::jsonb),
('OS-V07','adventure_friend_os','Trivia','{"id":"OS-V07","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin wrinkles his beak at a photo of a giant red flower.","lines":["This flower smells like rotting meat. On purpose. Bold strategy."],"question":"Why does the corpse flower smell like rotting meat?","selfQuestion":null,"choices":[{"id":"A","label":"To scare away humans","reply":["It works on me. Not the reason.","The smell attracts carrion flies and beetles for pollination.","It''s also huge. One of the largest flowers. Show-off."]},{"id":"B","label":"To attract flies and beetles that pollinate it","reply":["Correct. Smelly strategy.","The stench draws pollinators that normally visit dead animals.","It blooms rarely, sometimes only every several years. Dramatic and rare."]},{"id":"C","label":"Because it''s sick","reply":["Healthy. Just smelly.","It attracts pollinators like flies and beetles.","Gross, but efficient."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Amorphophallus titanum''s odor attracts carrion beetles and flesh flies.","coupleReplies":{}}'::jsonb),
('OS-V08','adventure_friend_os','Trivia','{"id":"OS-V08","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin flaps once, hovers, then lands, looking thoughtful.","lines":["I''ve rewritten this question six times. Seven. Seven times."],"question":"Which mammals can truly fly?","selfQuestion":null,"choices":[{"id":"A","label":"Bats","reply":["Correct. The only mammals with true powered flight.","Flying squirrels just glide. Bats actually flap.","Fellow night flyer. We wave at each other."]},{"id":"B","label":"Flying squirrels","reply":["Close, but they glide, not fly.","Bats are the only mammals with true powered flight.","Hazel would be offended. Gliding is still impressive."]},{"id":"C","label":"Sugar gliders","reply":["They glide. Gracefully. But don''t fly.","Bats are the only mammals capable of true flight.","Gliders are cool too. Just gravity-assisted."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Bats are the only mammals capable of true powered flight.","coupleReplies":{}}'::jsonb),
('OS-V09','adventure_friend_os','Trivia','{"id":"OS-V09","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin stares at a starfish photo, deep in thought.","lines":["Okay, hear me out. This creature has no brain. And it''s fine. I''m jealous."],"question":"Do starfish have brains?","selfQuestion":null,"choices":[{"id":"A","label":"Yes, five tiny brains","reply":["Close in spirit. No.","Starfish have no brain, just a nerve network.","Five arms, zero brains, zero worries."]},{"id":"B","label":"No, they have no central brain","reply":["Correct. No brain. No overthinking.","They use a network of nerves instead.","Imagine never replaying a conversation. Never. Wow."]},{"id":"C","label":"Yes, one giant brain","reply":["That would be ironic. No.","Starfish have no central brain.","They still do fine. Inspiring. Upsetting."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Sea stars lack a centralized brain; they have a decentralized nerve net.","coupleReplies":{}}'::jsonb),
('OS-V10','adventure_friend_os','Trivia','{"id":"OS-V10","friendId":"adventure_friend_os","type":"Trivia","scene":"Oswin holds up a daisy, staring at its center for a long time.","lines":["This is actually hundreds of flowers. I''ve been thinking about this for hours."],"question":"What''s surprising about a daisy?","selfQuestion":null,"choices":[{"id":"A","label":"Each ''flower'' is actually many tiny flowers","reply":["Correct. A flower crowd.","The center and each ''petal'' are separate tiny flowers.","A whole community pretending to be one. Very relatable."]},{"id":"B","label":"It closes when you look at it","reply":["Shy flower. Not daisies.","A daisy head is made of many tiny flowers.","Dozens to hundreds. Group project, flower edition."]},{"id":"C","label":"It glows in the dark","reply":["That would be nice. No.","Each daisy ''flower'' is actually many tiny flowers.","The center ones and the petal ones. Teamwork."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Daisies are composite flowers (capitula) of many disc and ray florets.","coupleReplies":{}}'::jsonb),
('OS-V11','adventure_friend_os','Preference','{"id":"OS-V11","friendId":"adventure_friend_os","type":"Preference","scene":"Oswin paces on your windowsill, mouthing words to himself.","lines":["Bear with me. I made a pros and cons list for breakfast. Toast won. Barely."],"question":"Big decision: sleep on it, or decide right now?","selfQuestion":null,"choices":[{"id":"A","label":"Sleep on it","reply":["Sleep on it. Wise. Pillow-tested decisions.","Though I usually just stay awake thinking about it."]},{"id":"B","label":"Decide right now","reply":["Decide right now? Brave. Fearless. Terrifying.","I''d need a minute. Or a week."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both sleep on it. Relief.","So {partner} and you will never rush into anything, and that''s lovely.","Just don''t both stay awake overthinking. One of you should actually sleep."],"A:B":["You decide right now. {partner} sleeps on it.","You''ve already chosen. They''re still thinking. Possibly forever.","Give them until morning. Then gently say ''well?''"],"B:A":["You sleep on it. {partner} decides right now.","They''ll have picked a couch while you''re still dreaming about fabric.","Agree on a 24-hour rule. Quick enough for them, slow enough for you."],"B:B":["You both decide right now. Whoa. Fearless.","Honestly, you and {partner} are quick as a hoot. I''m in awe.","Teach me. Actually, don''t. I''d overthink the lesson."]}}'::jsonb),
('OS-V12','adventure_friend_os','Preference','{"id":"OS-V12","friendId":"adventure_friend_os","type":"Preference","scene":"Oswin stares at his phone. He''s typed a message. Deleted it. Typed it again.","lines":["It''s 2 a.m. somewhere. I''ve written a message. Okay, hear me out."],"question":"2 a.m. thought: send the text, or save it as a draft?","selfQuestion":null,"choices":[{"id":"A","label":"Send it","reply":["Send it? Wow. Brave and honest.","2 a.m. you has courage that daytime you lacks."]},{"id":"B","label":"Save as draft","reply":["Save as draft. Relatable. Very relatable.","Drafts are safe little feelings in a drawer."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both send it. No secrets.","Honesty at 2 a.m. from you and {partner}. Beautiful chaos.","Just make sure someone''s awake to read it."],"A:B":["You save it. {partner} sends it.","Their 2 a.m. texts will arrive. Your drafts will wait.","Show them one of your drafts. In daylight. It''ll mean a lot."],"B:A":["You send it. {partner} saves it as a draft.","They''ll wake up to your 2 a.m. honesty. And have feelings.","Add ''no pressure to reply!'' They''ll still overthink. But less."],"B:B":["You both save it as a draft. Same.","A drawer of unsent feelings for you and {partner}.","Maybe swap drafts once a year. Like a time capsule."]}}'::jsonb),
('OS-V13','adventure_friend_os','Preference','{"id":"OS-V13","friendId":"adventure_friend_os","type":"Preference","scene":"Oswin ruffles his feathers, clearly worried about something imaginary.","lines":["When I worry, I reorganize my feathers. Alphabetically. What about you two?"],"question":"When you''re worried: talk it out, write it out, or walk it out?","selfQuestion":null,"choices":[{"id":"A","label":"Talk it out","reply":["Talk it out. Healthy. I''m impressed.","Words untangle knots."]},{"id":"B","label":"Write it out","reply":["Write it out. Yes. Same.","Paper listens without interrupting."]},{"id":"C","label":"Walk it out","reply":["Walk it out. Very efficient.","Feet move, worries shrink."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both talk it out. Great teamwork.","Two voices, one solution. {partner} is your sounding board.","Juno and I talk until 4 a.m. Healthy? Mostly."],"A:B":["You write it out. {partner} talks it out.","Read them your page aloud. They''ll love it.","Your notebook and their voice. A team."],"A:C":["You walk it out. {partner} talks it out.","Walk while they talk. Perfect pairing.","A listening walk. Very therapeutic."],"B:A":["You talk it out. {partner} writes it out.","Ask them to share a page. Then talk about it.","Words on paper, words out loud. Double processing."],"B:B":["You both write it out. Lovely.","I can picture it: you and {partner} could swap notebooks and feel less alone.","Journals are therapy with no appointments."],"B:C":["You walk it out. {partner} writes it out.","Walk to a café. Let them write. You watch the street.","Two coping styles, one cozy afternoon."],"C:A":["You talk it out. {partner} walks it out.","Walk and talk together. Two birds, one stroll.","Movement helps the words come out anyway."],"C:B":["You write it out. {partner} walks it out.","Write while they walk. Then swap notes.","Or bring your notebook on the walk. Pause on a bench."],"C:C":["You both walk it out. Synchronized worrying.","Pretty sure {partner} and you have a ''worry route'' around the neighborhood.","Walking side by side. Very healing."]}}'::jsonb),
('OS-V14','adventure_friend_os','Preference','{"id":"OS-V14","friendId":"adventure_friend_os","type":"Preference","scene":"Oswin whispers ''moth,'' then looks around, embarrassed.","lines":["That''s our safe word. Juno''s and mine. For arguments. It works. Weirdly well."],"question":"Mid-argument pause: a silly safe word, or a calm 10-minute break?","selfQuestion":null,"choices":[{"id":"A","label":"Silly safe word","reply":["A silly safe word. Yes. Mine is ''moth.''","It makes everyone laugh and reset."]},{"id":"B","label":"Calm 10-minute break","reply":["A calm break. Very wise.","Fresh air before hard words."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both pick a silly safe word.","Choose one with {partner}. Not ''moth.'' That''s taken.","Laughing mid-argument is underrated."],"A:B":["Calm break for you. {partner} wants a silly safe word.","Let them say the word. Then take your ten minutes.","Their word, your break. Fair compromise."],"B:A":["Safe word for you. {partner} prefers a calm break.","Say the safe word, THEN take the break.","Laugh first, breathe second."],"B:B":["You both pick a calm break.","Ten minutes apart, then back to {partner} with clearer heads.","Mature. Very mature. I''m jealous."]}}'::jsonb),
('OS-V15','adventure_friend_os','Preference','{"id":"OS-V15","friendId":"adventure_friend_os","type":"Preference","scene":"Oswin yawns, then checks whether yawning was rude.","lines":["It''s late. My brain is loud. Let''s make it louder."],"question":"Late-night mode: deep talks, or silly memes?","selfQuestion":null,"choices":[{"id":"A","label":"Deep talks","reply":["Deep talks. Oh, I''m in.","The best truths come out at midnight."]},{"id":"B","label":"Silly memes","reply":["Silly memes. Perfect.","Laughter heals overthinking."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both love deep talks.","Stay up with {partner} and let the big questions bloom.","Like ''what are we?'' and ''do fish get thirsty?'' Both important."],"A:B":["Memes for you. {partner} wants deep talks.","Send a meme about existentialism. Both covered.","Then answer their deep question. Just one."],"B:A":["Deep talks for you. {partner} wants memes.","Start with a meme. Then sneak in a deep question.","Meme to the meaning of life pipeline."],"B:B":["You both love silly memes.","Send {partner} the worst one you can find. Tonight.","Laughter at 1 a.m. is a love language."]}}'::jsonb),
('OS-V16','adventure_friend_os','Guess','{"id":"OS-V16","friendId":"adventure_friend_os","type":"Guess","scene":"Oswin squints at you, studying your face like it''s a puzzle.","lines":["Hoo. Okay. I''m a certified overthinker. This is my area."],"question":"What does your partner overthink the most?","selfQuestion":"What do you overthink the most?","choices":[{"id":"A","label":"Texts","reply":["Texts. Punctuation panic is real.","''Was that period aggressive?''"]},{"id":"B","label":"Plans","reply":["Plans. Spreadsheets of feelings.","Plan A, B, C, D."]},{"id":"C","label":"Something they said three days ago","reply":["Something from three days ago. That''s me.","The replay machine runs all night."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Texts, and {partner} guessed it.","They know you agonize over every ''ok.'' vs ''okay!''","Send them a text without editing. Just once."],"A:B":["You overthink plans. {partner} guessed texts.","They see you agonize over messages. It''s really the calendar.","Plan one thing. Text ''done.'' Breathe."],"A:C":["You replay old conversations. {partner} guessed texts.","They see the typing. They don''t see the replay.","Tell them. ''I''m still thinking about Tuesday.'' They''ll get it."],"B:A":["You overthink texts. {partner} guessed plans.","They don''t see your punctuation spiral. Lucky them.","Tell them about the period panic. They''ll laugh."],"B:B":["Plans, and {partner} guessed it.","They know you have seventeen backup plans.","Let them pick one. Just one. Breathe."],"B:C":["You replay old conversations. {partner} guessed plans.","They think you''re planning. You''re reliving.","Ask them about it. They probably don''t even remember."],"C:A":["You overthink texts. {partner} guessed old conversations.","Close. It''s the texts about the old conversations.","Send ''no pressure, just overthinking.'' It helps."],"C:B":["You overthink plans. {partner} guessed old conversations.","Your brain is in the future. They think it''s in the past.","Plan a cozy debrief. Covers both."],"C:C":["Something from three days ago, and {partner} knew it.","They''ve caught you replaying a conversation at 2 a.m.","Tell them. They probably forgot it. In a good way."]}}'::jsonb),
('OS-V17','adventure_friend_os','Guess','{"id":"OS-V17","friendId":"adventure_friend_os","type":"Guess","scene":"Oswin glances out the window at the moon, wide awake.","lines":["Insomnia talk. I''m extremely qualified. Sadly."],"question":"When your partner can''t sleep, what do they do?","selfQuestion":"When you can''t sleep, what do you do?","choices":[{"id":"A","label":"Scroll their phone","reply":["Scroll the phone. Blue light buddies.","The glow of regrets and cat videos."]},{"id":"B","label":"Whisper ''are you awake?''","reply":["Whisper ''are you awake?'' Brave.","Hoping for company at 3 a.m."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Scrolling, and {partner} knew it.","They''ve seen the phone glow under the blanket.","Share a cat video. Then both try to sleep."],"A:B":["You whisper ''are you awake?'' {partner} thought you''d scroll.","Surprise! They didn''t know you wanted company.","They''ll answer next time. Probably groggy. Still sweet."],"B:A":["You scroll. {partner} thought you''d whisper to them.","They''re waiting for your whisper. You''re watching reels.","Wake them up once. They''d like the company."],"B:B":["Whispering ''are you awake?'', and {partner} knew it.","They''ve been woken up many, many times.","They still answer. That''s love."]}}'::jsonb),
('OS-V18','adventure_friend_os','Guess','{"id":"OS-V18","friendId":"adventure_friend_os","type":"Guess","scene":"Oswin dips his head shyly when you compliment his feathers.","lines":["Compliments make me weird. Please don''t give me one right now. Or do. No. Yes."],"question":"How does your partner react to a compliment?","selfQuestion":"How do you react to a compliment?","choices":[{"id":"A","label":"Says ''thank you''","reply":["Says thank you. Healthy. Mature.","Accepting kindness is a skill."]},{"id":"B","label":"Deflects with a joke","reply":["Deflects with a joke. Relatable.","Humor shield, activated."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Thank you, and {partner} knew it.","They know you can take a compliment without combusting. Impressive.","Keep accepting love. I''m practicing. I''m at ''thanks, I guess.''"],"A:B":["You deflect with a joke. {partner} expected a ''thank you.''","They''re waiting for you to accept it.","Say thank you after the joke. Two-step."],"B:A":["You say thank you. {partner} expected a joke.","They''re ready for comedy. You just accept it.","They''ll be so pleased. Accept more often."],"B:B":["A joke, and {partner} knew it.","They know every compliment gets a punchline.","They still hear the blush behind the joke."]}}'::jsonb),
('OS-V19','adventure_friend_os','Guess','{"id":"OS-V19","friendId":"adventure_friend_os","type":"Guess","scene":"Oswin flaps his wings once, then freezes, as if surprised by his own movement.","lines":["Sudden plan changes. I have feelings. Several. In a spreadsheet."],"question":"If plans suddenly change, how does your partner react?","selfQuestion":"If plans suddenly change, how do you react?","choices":[{"id":"A","label":"Rolls with it","reply":["Rolls with it. Impressive.","A bendy soul."]},{"id":"B","label":"Needs a minute to recalibrate","reply":["Needs a minute. Same.","Brain reboot required."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Rolling with it, and {partner} knew it.","They know you''re the chill one. Unbothered. A rare bird.","Teach me. Slowly. I''ll take notes. Then overthink the notes."],"A:B":["You need a minute. {partner} thought you''d roll with it.","They''re already on Plan B. You''re still processing Plan A.","Say ''one sec.'' It''s okay. Really."],"B:A":["You roll with it. {partner} thought you''d need a minute.","They''re tiptoeing around you. You''re already on Plan B.","Tell them you''re fine. Actually fine. Not owl-fine."],"B:B":["Needing a minute, and {partner} knew it.","They know to give you a moment before Plan B.","Reboot time is self-care."]}}'::jsonb),
('OS-V20','adventure_friend_os','Guess','{"id":"OS-V20","friendId":"adventure_friend_os","type":"Guess","scene":"Oswin sits very still, then slowly turns to look at you.","lines":["Okay, hear me out. A big one. Reassurance."],"question":"When your partner needs reassurance, what do they do?","selfQuestion":"When you need reassurance, what do you do?","choices":[{"id":"A","label":"Asks directly","reply":["Asks directly. Brave. Clear.","No guessing games."]},{"id":"B","label":"Drops a tiny hint","reply":["Drops a tiny hint. The owl way.","Very subtle. Very me."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Asking directly, and {partner} knew it.","They know you''ll just say ''do you still like me?''","Healthy. Clear. I''m in awe."],"A:B":["You drop hints. {partner} expected you to ask directly.","They''re waiting for words. You''re sending signals.","Make the hint bigger. Or just ask. Juno taught me that."],"B:A":["You ask directly. {partner} expected hints.","They''re out here decoding clues. You just say it.","Less detective work for them. They''re probably relieved."],"B:B":["Dropping a hint, and {partner} decoded it.","They know your ''I''m fine'' means ''reassure me, please.''","Impressive translation skills."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_br','["Gotta give {partner} a big hug before I go. Big feelings. Big wait.","I brought {partner} some honey. I’ll wait to give it in person. I might cry."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('BR-V01','adventure_friend_br','Trivia','{"id":"BR-V01","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno ducks through your door in a tiny knitted hat, holding a jar of honey like a trophy.","lines":["Hi hi! Clover made me this hat. I cried. Anyway, quiz! Big feelings. Big hugs."],"question":"About how much does a newborn bear cub weigh?","selfQuestion":null,"choices":[{"id":"A","label":"About as much as a watermelon","reply":["Aww, that would be easier to hold! But no.","Newborn cubs weigh about a pound. Like a loaf of bread.","Such tiny beans. I''m already emotional."]},{"id":"B","label":"About one pound","reply":["Yes!! One tiny pound!","Mama bear can be hundreds of times heavier than her newborn cub.","Clover''s cubs will be that small. I''m going to hold them so gently. I''m crying."]},{"id":"C","label":"About as much as a grown wolf","reply":["Whoa, no! That would be a huge baby!","Newborn cubs weigh about one pound.","They start tiny and blind. Then they grow, and grow, and grow."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Newborn bear cubs typically weigh around 0.5 kg (about a pound).","coupleReplies":{}}'::jsonb),
('BR-V02','adventure_friend_br','Trivia','{"id":"BR-V02","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno squeezes you in a gentle hug and holds on. Then sniffles.","lines":["Big feelings. Big hugs. And science says hugs are good for you!"],"question":"Which hormone is released during warm touch and hugs?","selfQuestion":null,"choices":[{"id":"A","label":"Adrenaline","reply":["That''s the scary one! Not hugs!","Hugs and touch can boost oxytocin.","It helps people feel close and calm. Big warm feelings."]},{"id":"B","label":"Oxytocin, often called the ''cuddle hormone''","reply":["Yes!! The cuddle hormone!","Warm touch can raise oxytocin, linked to bonding and calm.","So hugging Clover is basically medicine. I''m prescribing more."]},{"id":"C","label":"Caffeine","reply":["Ha! That''s coffee, not hugs!","Oxytocin, the ''cuddle hormone,'' rises with warm touch.","Hug more. Coffee less. Kidding. Both."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Warm partner contact is associated with higher oxytocin (Grewen et al. 2005).","coupleReplies":{}}'::jsonb),
('BR-V03','adventure_friend_br','Trivia','{"id":"BR-V03","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno balances an egg on his feet very carefully. It wobbles. He panics.","lines":["This is practice. For a reason."],"question":"How do emperor penguin dads care for their egg?","selfQuestion":null,"choices":[{"id":"A","label":"They balance it on their feet for about two months","reply":["Yes!! Dad goals!","They keep the egg warm on their feet under a fold of skin.","Through freezing winter, barely eating. I''m sobbing. Clover, I''m ready."]},{"id":"B","label":"They bury it in snow","reply":["No!! It''d freeze!","Dads balance the egg on their feet under a warm skin flap.","For about two months, in the middle of winter."]},{"id":"C","label":"They hand it to a babysitter","reply":["Aww, no! Dad duty!","Dads keep it on their feet, under a warm fold of skin.","Huddled together through blizzards. Hero dads."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Male emperor penguins incubate eggs on their feet for ~2 months.","coupleReplies":{}}'::jsonb),
('BR-V04','adventure_friend_br','Trivia','{"id":"BR-V04","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno hums happily while munching a cookie.","lines":["When I eat, I hum. Clover says gorillas do this too!"],"question":"What do gorillas sometimes do while eating food they love?","selfQuestion":null,"choices":[{"id":"A","label":"Throw it at friends","reply":["Not the polite thing! No!","They hum and sing while eating.","Happy eating sounds. Same as me with honey."]},{"id":"B","label":"Eat in total silence","reply":["The opposite! They''re musical!","Gorillas hum and sing while eating favorite foods.","Snack symphony!"]},{"id":"C","label":"Hum and sing","reply":["Yes!! Snack songs!","Researchers recorded gorillas humming and ''singing'' while eating.","Happy food sounds. I knew I wasn''t weird."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Luef et al. (2016) documented gorillas humming/singing during feeding.","coupleReplies":{}}'::jsonb),
('BR-V05','adventure_friend_br','Trivia','{"id":"BR-V05","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno counts on his claws. Then counts again. Then gives up.","lines":["How long do elephants wait for babies? I''ll be impatient for days."],"question":"How long is an elephant pregnancy?","selfQuestion":null,"choices":[{"id":"A","label":"About 9 months","reply":["That''s humans! Elephants wait longer!","Elephant pregnancy lasts about 22 months.","Almost two years! I can''t even wait for cookies to cool."]},{"id":"B","label":"About 3 weeks","reply":["Way too short!","Elephants carry babies for about 22 months.","That''s a long time to plan a nursery."]},{"id":"C","label":"About 22 months","reply":["Yes! Almost two years!","It''s the longest pregnancy of any land mammal.","Patience is a big feeling too."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"African elephant gestation is about 22 months.","coupleReplies":{}}'::jsonb),
('BR-V06','adventure_friend_br','Trivia','{"id":"BR-V06","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno peeks at his own paw, curious.","lines":["This one surprised me. Like, big surprise."],"question":"What color is a polar bear''s skin?","selfQuestion":null,"choices":[{"id":"A","label":"White","reply":["That''s what I thought too!","Polar bear skin is actually black, under that white-looking fur.","Their fur is clear, not white. Mind blown."]},{"id":"B","label":"Black","reply":["Yes!! Black skin!","Dark skin helps soak up the sun''s warmth.","Their fur is actually see-through. It just looks white. Science is wild."]},{"id":"C","label":"Pink","reply":["Aww, cute, but no!","Polar bear skin is black underneath.","Their fur looks white but is actually hollow and clear."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Polar bears have black skin; fur hairs are translucent.","coupleReplies":{}}'::jsonb),
('BR-V07','adventure_friend_br','Trivia','{"id":"BR-V07","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno holds up a photo of a koala, then his own paw, comparing.","lines":["These are SO similar to human fingerprints. I''m in awe."],"question":"What''s surprising about koala fingerprints?","selfQuestion":null,"choices":[{"id":"A","label":"They look almost identical to human fingerprints","reply":["Yes!! Almost identical!","Even under a microscope, they''re very hard to tell apart.","Imagine a koala solving a crime. Or committing one. Cute crime."]},{"id":"B","label":"Koalas don''t have fingerprints","reply":["They do! Very human-like!","Their prints look almost exactly like ours.","Nature is full of surprises."]},{"id":"C","label":"They glow pink","reply":["That''s the flying squirrel!","Koala fingerprints are nearly identical to humans''.","Hugging trees with human-like prints. Adorable."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Koala fingerprints closely resemble human fingerprints (Henneberg et al.).","coupleReplies":{}}'::jsonb),
('BR-V08','adventure_friend_br','Trivia','{"id":"BR-V08","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno holds up a jellybean between two claws, looking at it very tenderly.","lines":["This tiny thing is a baby. Kind of. I''m emotional."],"question":"How big is a newborn kangaroo joey?","selfQuestion":null,"choices":[{"id":"A","label":"About the size of a puppy","reply":["Close! Way smaller!","A newborn joey is about the size of a jellybean.","It climbs into the pouch all on its own."]},{"id":"B","label":"About the size of a jellybean","reply":["Yes!! A jellybean!","A newborn joey crawls into mom''s pouch and grows there for months.","Tiny and brave. I''m crying again. Big feelings."]},{"id":"C","label":"About the size of a basketball","reply":["Whoa, no!","It''s about the size of a jellybean.","It grows in the pouch for months. Nature is amazing."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Newborn kangaroo joeys are roughly jellybean-sized.","coupleReplies":{}}'::jsonb),
('BR-V09','adventure_friend_br','Trivia','{"id":"BR-V09","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno wipes a tear looking at a jellyfish video.","lines":["This tiny jellyfish can start its life over. I''m emotional."],"question":"What can the ''immortal jellyfish'' do?","selfQuestion":null,"choices":[{"id":"A","label":"Turn back into a younger stage when stressed","reply":["Yes!! It can reverse its age!","When injured or stressed, it can revert to its baby polyp stage.","Starting over. Big feelings."]},{"id":"B","label":"Live in the desert","reply":["Too dry! No!","It can revert back to a young polyp stage.","A natural do-over button."]},{"id":"C","label":"Glow brighter as it ages","reply":["Pretty! Not it!","It can turn back into a younger form.","Life, round two. So hopeful."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Turritopsis dohrnii can revert to the polyp stage (transdifferentiation).","coupleReplies":{}}'::jsonb),
('BR-V10','adventure_friend_br','Trivia','{"id":"BR-V10","friendId":"adventure_friend_br","type":"Trivia","scene":"Bruno sniffs a pineapple and sighs patiently.","lines":["Pineapples take forever to grow. Like waiting for cubs. Okay, not that long."],"question":"About how long does it take for a pineapple to grow?","selfQuestion":null,"choices":[{"id":"A","label":"About 2 weeks","reply":["Way longer!","Pineapples take about 18 months to 2 years.","One fruit per plant at a time. Precious."]},{"id":"B","label":"They grow on trees in one day","reply":["Ha! No! Not trees, and not fast!","They grow on short plants, taking about 18 months to 2 years.","Worth the wait."]},{"id":"C","label":"About 18 months to 2 years","reply":["Yes!! A really long time!","Each plant usually produces just one pineapple at a time.","Patience is love. Clover says I need more."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"A pineapple typically takes ~18–24 months to mature.","coupleReplies":{}}'::jsonb),
('BR-V11','adventure_friend_br','Preference','{"id":"BR-V11","friendId":"adventure_friend_br","type":"Preference","scene":"Bruno opens his arms wide, then waits kindly for an answer.","lines":["Big feelings. Big hugs. But which first?"],"question":"When feelings get big: hug it out, or talk it out?","selfQuestion":null,"choices":[{"id":"A","label":"Hug it out","reply":["Hug it out!! Big hugs for big feelings!","No words needed. Just warmth."]},{"id":"B","label":"Talk it out","reply":["Talk it out. Brave and honest.","Words can make big feelings smaller."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["You both hug it out!! Big bear hug energy!","{partner} wraps you up, you wrap them up. No talking needed.","I''m tearing up. That''s beautiful."],"A:B":["Talk it out for you. {partner} wants to hug it out.","They''ll come in for a squeeze. You''ll want words.","Talk while hugging. Totally allowed. Very effective."],"B:A":["Hug it out for you. {partner} wants to talk it out.","You''ll open your arms. They''ll open their mouth. Both are love.","Hug first, then talk. Best combo. Trust a bear."],"B:B":["You both talk it out! Big feelings, big words.","So you and {partner} untangle things together. Out loud. Bravely.","Then hug anyway. Just for the bonus points."]}}'::jsonb),
('BR-V12','adventure_friend_br','Preference','{"id":"BR-V12","friendId":"adventure_friend_br","type":"Preference","scene":"Bruno shows you a closet stuffed with tiny socks, hats, and blankets. For cubs not born yet.","lines":["I may have overprepared. A little. A lot."],"question":"Getting ready for something big: prepare everything early, or figure it out as you go?","selfQuestion":null,"choices":[{"id":"A","label":"Prepare early","reply":["Prepare early! Like me! Twelve tiny hats!","Being ready feels safe."]},{"id":"B","label":"Figure it out as we go","reply":["Figure it out as you go. Brave!","Flexible hearts handle surprises."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Prepare-early couple! Matching checklists!","Honestly, {partner} and you probably packed for a trip three weeks ahead.","Clover would love you. I already do."],"A:B":["You go with the flow. {partner} prepares early.","They''ll have a list. You''ll have vibes.","Let them prepare. You make it fun. Team bear."],"B:A":["You prepare early. {partner} figures it out as they go.","You''ll pack the bag. They''ll pack the snacks. Last minute.","Balance! You''re the plan. They''re the fun."],"B:B":["Figure-it-out couple! Chill bears!","I can picture it: you and {partner} trust you''ll handle whatever comes.","Teach me. I have 47 tiny socks and no chill."]}}'::jsonb),
('BR-V13','adventure_friend_br','Preference','{"id":"BR-V13","friendId":"adventure_friend_br","type":"Preference","scene":"Bruno drizzles honey onto a spoon and hums contentedly.","lines":["Honey question. The most important question."],"question":"Honey goes best on: toast, pancakes, or straight from the spoon?","selfQuestion":null,"choices":[{"id":"A","label":"Toast","reply":["Toast! Crunchy sweet perfection.","Butter, then honey. Classic."]},{"id":"B","label":"Pancakes","reply":["Pancakes! Fluffy golden dreams.","A honey waterfall."]},{"id":"C","label":"Straight from the spoon","reply":["Straight from the spoon! A true bear!","No middleman. Pure love."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Toast for both of you! Breakfast twins!","Pretty sure {partner} and you fight over the crust. Cute fight.","Honey toast for two. Breakfast in bed. Go."],"A:B":["Pancakes for you! {partner} picks toast.","Pancake toast? Is that a thing? Make it a thing.","Honey brunch for two. Perfect."],"A:C":["Straight from the spoon! {partner} prefers toast.","They''re civilized. You''re a bear. Respect.","Hand them toast. Keep the spoon."],"B:A":["Toast for you! {partner} picks pancakes.","Crunchy versus fluffy. The great breakfast debate.","Make both and drizzle honey on everything. Even the plates. Okay, not the plates."],"B:B":["Pancakes for both of you! Fluffy couple!","Lowkey, you and {partner} make a pancake tower on Sundays, don''t you?","Stack them high. Pour honey everywhere."],"B:C":["Spoon for you! {partner} wants pancakes.","They''re making breakfast. You''re eating the honey.","Save some for the pancakes. Some."],"C:A":["Toast for you! {partner} eats it from the spoon.","They''ll lick the spoon while you butter the toast.","Share the jar. Love is sticky."],"C:B":["Pancakes for you! {partner} goes straight to the spoon.","You pour it on pancakes. They pour it in their mouth.","Both valid. Both sticky. Both love."],"C:C":["Straight from the spoon! Both of you! Bear souls!","{partner} and you sneak spoonfuls at midnight. I know it.","Two spoons, one jar. True love."]}}'::jsonb),
('BR-V14','adventure_friend_br','Preference','{"id":"BR-V14","friendId":"adventure_friend_br","type":"Preference","scene":"Bruno pulls out two pictures: a fluffy puppy and a sleepy cat.","lines":["Clover and I talk about pets. A lot. Big decision."],"question":"Someday pet: a dog, or a cat?","selfQuestion":null,"choices":[{"id":"A","label":"A dog","reply":["A dog! Walks, wags, and zoomies!","A best friend that greets you like it''s been ten years."]},{"id":"B","label":"A cat","reply":["A cat! Independent, cozy, majestic.","They love you on their own terms."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Dog for both of you! Zoomies forever!","So {partner} and you will walk a happy pup every morning.","Name it something silly. Like Biscuit. Sorry, Biscuit."],"A:B":["Cat for you. {partner} wants a dog.","They want zoomies. You want purrs.","Both! A cat and dog cuddle pile. I''m crying."],"B:A":["Dog for you. {partner} wants a cat.","One barks, one judges. The classic household.","Get both. Raise them together. They''ll be best friends. Maybe."],"B:B":["Cat for both of you! Purr-fect couple!","Honestly, you and {partner} will lose arguments to a cat. Every day.","Get a sunny window. Cats need sunny windows."]}}'::jsonb),
('BR-V15','adventure_friend_br','Preference','{"id":"BR-V15","friendId":"adventure_friend_br","type":"Preference","scene":"Bruno sniffles into a tissue during a commercial about puppies.","lines":["I cry at everything now. Is that normal?"],"question":"Crying at movies: proudly, or secretly?","selfQuestion":null,"choices":[{"id":"A","label":"Proudly","reply":["Proudly! Like me! Tears are big feelings!","Let them flow. No shame."]},{"id":"B","label":"Secretly","reply":["Secretly. Sneaky tear wipe.","''Something in my eye.'' Classic."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Proud criers, both of you! Tissue box couple!","I can picture it: {partner} and you sob together at every sad dog movie.","That''s beautiful. Truly. I''m crying about it."],"A:B":["You cry secretly. {partner} cries proudly.","They''re openly sobbing. You''re coughing suspiciously.","Join them. It feels so good. Big feelings, big tears."],"B:A":["You cry proudly. {partner} cries secretly.","You''ll be sobbing. They''ll be ''fixing their eyelash.''","Hand them a tissue. Don''t say anything. Love."],"B:B":["Secret criers, both of you!","Pretty sure you and {partner} both pretend there''s dust in the air.","Next time, cry together. Honestly. It''s nice."]}}'::jsonb),
('BR-V16','adventure_friend_br','Guess','{"id":"BR-V16","friendId":"adventure_friend_br","type":"Guess","scene":"Bruno gives you a questioning look, arms half open.","lines":["How do you like your hugs? This matters to me deeply."],"question":"How does your partner like to be hugged?","selfQuestion":"How do you like to be hugged?","choices":[{"id":"A","label":"Tight bear hug","reply":["Tight bear hug! My specialty!","Squeeze that love in."]},{"id":"B","label":"Gentle and soft","reply":["Gentle and soft. So tender.","Like holding a cloud."]},{"id":"C","label":"Long and swaying","reply":["Long and swaying. Slow dance hug!","Rock back and forth. Forever."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Tight bear hug, and {partner} knew it!","They squeeze you like they mean it.","Professional hugger recognizes professional hugger."],"A:B":["Gentle for you. {partner} guessed bear hug.","They''re squeezing too hard. Lovingly too hard.","Tell them: soft like a cloud. They''ll adjust."],"A:C":["Long and swaying for you. {partner} guessed bear hug.","They squeeze and let go. You want to rock forever.","Hold on longer. They''ll get the hint."],"B:A":["Bear hug for you. {partner} guessed gentle.","They''re holding back. You want the full squeeze.","Tell them: ''Squeeze harder.'' Best instruction ever."],"B:B":["Gentle and soft, and {partner} knew it!","They hold you like something precious. Because you are.","I''m tearing up. Of course I am."],"B:C":["Long and swaying for you. {partner} guessed gentle.","They''re soft but quick. You want slow.","Sway them next time. They''ll love it."],"C:A":["Bear hug for you. {partner} guessed long and swaying.","They''re swaying. You want squeezing.","Squeeze AND sway. The ultimate hug."],"C:B":["Gentle for you. {partner} guessed long and swaying.","Close! Soft and slow. Almost perfect.","Gentle sway. That''s a dreamy hug."],"C:C":["Long and swaying, and {partner} knew it!","They sway with you like a slow dance in the kitchen.","Hug with music. Never stop."]}}'::jsonb),
('BR-V17','adventure_friend_br','Guess','{"id":"BR-V17","friendId":"adventure_friend_br","type":"Guess","scene":"Bruno sits beside you with a soft rumble, offering a cookie.","lines":["Sad days happen. What helps?"],"question":"When your partner is sad, what helps most?","selfQuestion":"When you''re sad, what helps most?","choices":[{"id":"A","label":"A hug, no words","reply":["A hug, no words. Just being there.","Sometimes that''s everything."]},{"id":"B","label":"Their favorite snack","reply":["Favorite snack. Comfort food heals.","Cookies fix hearts. Science. Probably."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["A wordless hug, and {partner} knew it!","They just hold you. No questions. No fixes.","That''s the most loving thing. I''m crying."],"A:B":["A snack helps you. {partner} guessed a hug.","They''re opening their arms. You''re opening the pantry.","Hug them while eating. Efficient comfort."],"B:A":["A hug helps you. {partner} guessed snacks.","They''re bringing cookies. You need arms.","Take the cookie. Then ask for the hug. Both work."],"B:B":["Favorite snack, and {partner} knew it!","They show up with your comfort food before you even ask.","Snack love is real love."]}}'::jsonb),
('BR-V18','adventure_friend_br','Guess','{"id":"BR-V18","friendId":"adventure_friend_br","type":"Guess","scene":"Bruno opens a drawer full of tiny jars, buttons, and spoons.","lines":["My collection. Clover calls it ''the bear hoard.''"],"question":"What does your partner secretly hoard?","selfQuestion":"What do you secretly hoard?","choices":[{"id":"A","label":"Cute mugs","reply":["Cute mugs! A cabinet full!","One for every mood."]},{"id":"B","label":"Snacks in hidden places","reply":["Hidden snacks! A secret stash!","In coat pockets. In drawers. Everywhere."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Cute mugs, and {partner} knew it!","They''ve seen the overflowing cabinet.","Buy them one more. They''ll pretend they don''t need it."],"A:B":["You hoard snacks. {partner} guessed mugs.","They don''t know about the secret chocolate drawer.","Tell them. Or don''t. Snack secrets are sacred."],"B:A":["You hoard mugs. {partner} guessed snacks.","They''re looking for food. Your cabinet is just mugs.","Hide snacks in the mugs. Two hoards, one shelf."],"B:B":["Hidden snacks, and {partner} knew it!","They''ve found the chips behind the cereal.","Share the stash. Or find a better hiding spot."]}}'::jsonb),
('BR-V19','adventure_friend_br','Guess','{"id":"BR-V19","friendId":"adventure_friend_br","type":"Guess","scene":"Bruno practices rocking a tiny teddy bear, very carefully.","lines":["I keep imagining what kind of parent I''ll be. You two?"],"question":"As a parent (or pet parent), what would your partner be like?","selfQuestion":"As a parent (or pet parent), what would you be like?","choices":[{"id":"A","label":"The fun one","reply":["The fun one! Pillow forts! Ice cream for dinner!","Every day is an adventure."]},{"id":"B","label":"The worrier who packs everything","reply":["The worrier! Snacks, band-aids, sunscreen!","Ready for anything. Like me."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["The fun one, and {partner} knew it!","They know you''ll be building blanket forts every weekend.","Bring me. I''ll bring honey."],"A:B":["You''d be the worrier. {partner} guessed the fun one.","They imagine you jumping in puddles. You''d be holding umbrellas.","That''s okay. Worry is love too. I know."],"B:A":["You''d be the fun one. {partner} guessed the worrier.","They think you''d pack everything. You''d pack only fun.","They''ll handle the band-aids. You handle the giggles."],"B:B":["The worrier, and {partner} knew it!","They know you''ll pack three backup snacks for a ten-minute walk.","Same. Clover laughs at me. Lovingly."]}}'::jsonb),
('BR-V20','adventure_friend_br','Guess','{"id":"BR-V20","friendId":"adventure_friend_br","type":"Guess","scene":"Bruno wipes a happy tear just thinking about good news.","lines":["Big news reactions! Mine involves lots of tears."],"question":"When your partner gets big news, how do they react?","selfQuestion":"When you get big news, how do you react?","choices":[{"id":"A","label":"Happy-cries immediately","reply":["Happy-cries! Like me!","Tears of joy. The best kind."]},{"id":"B","label":"Goes quiet, then screams","reply":["Quiet, then scream! Dramatic!","The delay is the best part."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Happy tears, and {partner} knew it!","They had the tissues ready before you even opened the letter.","Crying buddies forever."],"A:B":["You go quiet then scream. {partner} expected tears.","They have tissues. You have volume.","Scream into their shoulder. Then they can cry."],"B:A":["You happy-cry. {partner} expected quiet then screaming.","They''re bracing for a scream. You''re sobbing happily.","Both are big feelings. Both are beautiful."],"B:B":["Quiet then scream, and {partner} knew it!","They watch your face freeze, then cover their ears.","Love the drama. Honestly."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_ru','["I’m good. ...Just waiting on {partner}. Not like I care. ...I care a little.","I’ll stick around till {partner}’s back. Got nowhere to be. ...Are you okay?"]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('RU-V01','adventure_friend_ru','Trivia','{"id":"RU-V01","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue leans in your doorway, arms crossed. A tiny smile tries to escape. She stops it.","lines":["I''m good. ...Are you? Cool. Quiz. Keep up."],"question":"Why do wolves howl?","selfQuestion":null,"choices":[{"id":"A","label":"Because they''re sad","reply":["Not always. Sometimes it''s just ''hey.''","Howls are mostly for communication and finding the pack.","Happy howls exist. I don''t do them. Often."]},{"id":"B","label":"To communicate and find their pack","reply":["Correct. Good ears.","Howls help wolves find each other and mark territory over long distances.","Sky says my howl sounds like ''come home.'' ...Whatever."]},{"id":"C","label":"At the moon, obviously","reply":["Movie myth. The moon''s not involved.","Wolves howl to find each other and talk across distance.","We just tilt our heads up. Sound carries better."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Wolves howl to communicate, assemble the pack, and mark territory.","coupleReplies":{}}'::jsonb),
('RU-V02','adventure_friend_ru','Trivia','{"id":"RU-V02","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue looks at a photo of a snow leopard and almost smiles. Almost.","lines":["I''m good. ...This one''s quiet. Like me. Respect."],"question":"What can''t snow leopards do, unlike lions and tigers?","selfQuestion":null,"choices":[{"id":"A","label":"Roar","reply":["Correct. No roar.","They chuff, hiss, and mew, but their throats can''t make a true roar.","Quiet but deadly. Honestly? Goals."]},{"id":"B","label":"Climb","reply":["They climb mountains for fun. Literally.","The thing they can''t do is roar.","Instead they make a soft ''chuff.'' Very low-key. I respect it."]},{"id":"C","label":"Jump","reply":["They jump like it''s nothing. Several times their body length.","What they can''t do is roar.","Silent mountain cats. No drama. Just results."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Snow leopards cannot roar due to larynx anatomy.","coupleReplies":{}}'::jsonb),
('RU-V03','adventure_friend_ru','Trivia','{"id":"RU-V03","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue holds a mug of something warm, sipping slowly.","lines":["Sharing question. Hard for me."],"question":"What do vampire bats do for roost-mates who missed a meal?","selfQuestion":null,"choices":[{"id":"A","label":"Ignore them","reply":["Nope. They help.","They share regurgitated blood with hungry roost-mates.","Bats who share get help later. Trust, but make it bats."]},{"id":"B","label":"Teach them to hunt better","reply":["Not quite.","They share food directly, by regurgitating blood.","Friends who share, get shared with. It''s a system."]},{"id":"C","label":"Share regurgitated blood with them","reply":["Correct. Gross. Kind.","Bats share meals with roost-mates who couldn''t feed, and those friends return the favor.","Relying on others to survive. ...I''m learning."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Vampire bats share regurgitated blood with roost-mates; reciprocity is observed.","coupleReplies":{}}'::jsonb),
('RU-V04','adventure_friend_ru','Trivia','{"id":"RU-V04","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue squints at a zebra photo for a long time.","lines":["I''m good. ...Trying to find two the same. Can''t."],"question":"What''s unique about zebra stripes?","selfQuestion":null,"choices":[{"id":"A","label":"They''re all identical","reply":["Nope. They just look it from far away.","Each zebra''s stripe pattern is unique.","Blending in and standing out. At the same time."]},{"id":"B","label":"They change every morning","reply":["Ha. That''d be exhausting.","Each zebra''s pattern is unique and stays for life.","Some foals even recognize mom by her stripes."]},{"id":"C","label":"Every zebra''s pattern is one of a kind","reply":["Correct. Like fingerprints.","No two zebras share the exact same stripes.","Same herd, different stripes. Individuality. I like that."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Zebra stripe patterns are unique to individuals.","coupleReplies":{}}'::jsonb),
('RU-V05','adventure_friend_ru','Trivia','{"id":"RU-V05","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue looks up at a flock of birds outside, watching closely.","lines":["I''m good. ...Teamwork question. Ugh. Fine."],"question":"Why do geese fly in a V formation?","selfQuestion":null,"choices":[{"id":"A","label":"Because V stands for ''victory''","reply":["Cute. Wrong.","It saves energy. Birds take turns leading.","Rotating the lead means nobody burns out."]},{"id":"B","label":"To save energy, taking turns at the front","reply":["Correct. Teamwork.","Birds behind ride the lead bird''s air currents, and the lead role rotates.","Even the strongest one can''t lead forever. ...I hate that I relate."]},{"id":"C","label":"To look cool in photos","reply":["They do look cool. Not the reason.","The V helps them save energy, and they swap leaders.","Teamwork wins long distances."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Geese fly in V formation for aerodynamic efficiency, rotating the lead.","coupleReplies":{}}'::jsonb),
('RU-V06','adventure_friend_ru','Trivia','{"id":"RU-V06","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue raises one eyebrow, clearly debunking something in her head.","lines":["This one annoys me. Every documentary gets it wrong."],"question":"Is the ''alpha wolf'' fighting for dominance how wild packs work?","selfQuestion":null,"choices":[{"id":"A","label":"No, wild packs are families led by parents","reply":["Correct. Myth busted.","The ''alpha'' idea came from captive wolves, not wild families.","Even the scientist who popularized it later corrected it. Respect."]},{"id":"B","label":"Yes, wolves battle for the top spot","reply":["Nope. Popular myth.","That idea came from studying unrelated wolves in captivity.","In the wild, packs are just families. Parents lead. That''s it."]},{"id":"C","label":"Only on Tuesdays","reply":["Ha. ...Funny. No.","Wild packs are families led by the parents.","The alpha myth came from captive wolves."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"The ''alpha'' dominance concept came from captive studies; wild packs are families (Mech later corrected it).","coupleReplies":{}}'::jsonb),
('RU-V07','adventure_friend_ru','Trivia','{"id":"RU-V07","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue shadowboxes once, very fast, then pretends she didn''t.","lines":["I''m good. ...This shrimp could beat me. I''ve accepted it."],"question":"What''s special about a mantis shrimp''s punch?","selfQuestion":null,"choices":[{"id":"A","label":"It''s slow but very polite","reply":["Opposite. Very rude. Very fast.","Its strike is among the fastest in nature.","It can crack aquarium glass. Aquariums hate this guy."]},{"id":"B","label":"It''s one of the fastest strikes in the animal world","reply":["Correct. Absurdly fast.","Its club can smash snail shells and even crack aquarium glass.","Small. Colorful. Will fight you. My spirit animal."]},{"id":"C","label":"It only punches when it''s sad","reply":["Ha. It punches whenever it wants.","It''s one of the fastest strikes in nature.","Shells, glass, your confidence. All cracked."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Mantis shrimp strikes are among the fastest in nature and can crack aquarium glass.","coupleReplies":{}}'::jsonb),
('RU-V08','adventure_friend_ru','Trivia','{"id":"RU-V08","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue holds up a mushroom and narrows her eyes at it.","lines":["I''m good. ...Mushrooms are weird. Hear this."],"question":"Genetically, mushrooms are more closely related to...?","selfQuestion":null,"choices":[{"id":"A","label":"Animals","reply":["Correct. Wild, right?","Fungi split from the animal branch later than from plants.","I''m related to a mushroom. Don''t tell Sky. He''ll make it a nickname."]},{"id":"B","label":"Plants","reply":["Everyone guesses that. Wrong.","Fungi are actually closer relatives of animals than plants.","So that mushroom is technically more my cousin than a tree is. Ugh."]},{"id":"C","label":"Rocks","reply":["Ha. No. Rocks aren''t alive. Usually.","Fungi are more closely related to animals than to plants.","Mushroom, you''re family now. Unfortunately."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Fungi are more closely related to animals than plants (Opisthokonta).","coupleReplies":{}}'::jsonb),
('RU-V09','adventure_friend_ru','Trivia','{"id":"RU-V09","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue laughs at something on her phone, then quickly makes her face neutral again.","lines":["I''m good. ...Saw a meme. Sky sent it. Whatever."],"question":"What do studies suggest about couples who laugh together?","selfQuestion":null,"choices":[{"id":"A","label":"They take each other less seriously","reply":["Nope. The opposite, kind of.","Shared laughter is linked to feeling closer and more supported.","Laughing together is serious business. Ironically."]},{"id":"B","label":"It makes no difference","reply":["It does. Science said so.","Couples who laugh together tend to feel closer.","Send the dumb meme. It counts."]},{"id":"C","label":"They tend to feel closer and more supported","reply":["Correct. Shared laughter helps.","Couples who laugh together report feeling closer and more satisfied.","Sky makes me laugh. Don''t tell him. He''ll get cocky."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Kurtz & Algoe (2015): shared laughter associated with relationship closeness/satisfaction.","coupleReplies":{}}'::jsonb),
('RU-V10','adventure_friend_ru','Trivia','{"id":"RU-V10","friendId":"adventure_friend_ru","type":"Trivia","scene":"Rue dabs green paste on a cracker, bites it, and blinks very fast.","lines":["I''m good. ...I''m good. That was not real wasabi."],"question":"Most ''wasabi'' served outside Japan is actually what?","selfQuestion":null,"choices":[{"id":"A","label":"Pure grated wasabi root","reply":["Rarely. Real wasabi is pricey.","Most is horseradish, mustard, and green coloring.","Real wasabi is notoriously hard to grow. Fussy plant."]},{"id":"B","label":"Horseradish with green coloring","reply":["Correct. Imposter paste.","Real wasabi root is rare and expensive, so horseradish fills in.","Things aren''t always what they say they are. Lesson."]},{"id":"C","label":"Mashed avocado with chili","reply":["That''s just spicy guacamole.","It''s usually horseradish and mustard, colored green.","Trust no green paste. Ever."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Most ''wasabi'' outside Japan is horseradish/mustard with coloring.","coupleReplies":{}}'::jsonb),
('RU-V11','adventure_friend_ru','Preference','{"id":"RU-V11","friendId":"adventure_friend_ru","type":"Preference","scene":"Rue leans on your wall. She looks like she doesn''t care. She cares.","lines":["Independence talk. My favorite topic. Kind of. Don''t read into it."],"question":"Weekends: some solo time, or always together?","selfQuestion":null,"choices":[{"id":"A","label":"Some solo time","reply":["Solo time. Same.","Space keeps me me."]},{"id":"B","label":"Always together","reply":["Always together? Huh. That''s... sweet.","Not me. But sweet."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Solo time for both of you. Good.","So you and {partner} trust each other enough to roam.","Then you come back with stories. That''s the best part."],"A:B":["Always together for you. {partner} wants some solo time.","They''re not leaving you. They''re recharging. Different thing.","Give them one solo afternoon. They''ll come back softer."],"B:A":["Solo time for you. {partner} wants always together.","They''ll want Saturday plans. You''ll want a solo hike.","Morning alone, afternoon together. Sky and I do that. It works."],"B:B":["Always together for both of you. Huh. Cute.","Honestly, {partner} and you are a pack of two. Inseparable.","I''d get claustrophobic. You two make it look nice. Annoying."]}}'::jsonb),
('RU-V12','adventure_friend_ru','Preference','{"id":"RU-V12","friendId":"adventure_friend_ru","type":"Preference","scene":"Rue checks her phone. Puts it away. Checks it again.","lines":["Texting rules. Sky texts too much. I like it. Don''t tell him."],"question":"Staying in touch: a daily text, or only when there''s news?","selfQuestion":null,"choices":[{"id":"A","label":"A daily text","reply":["Daily text. Alright. I get it.","A tiny ''hey'' that says ''still here.''"]},{"id":"B","label":"Only when there''s news","reply":["Only when there''s news. Same.","No need to over-text."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Daily text for both of you. Alright, cute.","I can picture it: you and {partner} send one ''you good?'' a day. Minimum.","Simple. Steady. I could get used to it. Maybe."],"A:B":["Only news for you. {partner} likes a daily text.","They''re checking their phone. Waiting. For anything.","Send a one-word text. ''Good.'' That''s all. It counts."],"B:A":["Daily text for you. {partner} only texts with news.","You''ll send ''hey.'' They''ll reply in three days with ''bought a plant.''","Send yours anyway. They read them. They smile."],"B:B":["Only news for both of you. Efficient.","Pretty sure you and {partner} trust the silence. Silence means all good.","Honestly? Peaceful. Respect."]}}'::jsonb),
('RU-V13','adventure_friend_ru','Preference','{"id":"RU-V13","friendId":"adventure_friend_ru","type":"Preference","scene":"Rue sharpens a pencil with a pocket knife. Unbothered. Mostly.","lines":["I''m good. ...Recharging question. I have a method."],"question":"To recharge: alone time, friends, or a long run?","selfQuestion":null,"choices":[{"id":"A","label":"Alone time","reply":["Alone time. Same.","Quiet is power."]},{"id":"B","label":"Friends","reply":["Friends. Okay. Social.","A pack helps. ...Sometimes."]},{"id":"C","label":"A long run","reply":["A long run. Obviously.","Miles fix most things."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Alone time for both of you. Respect.","Lowkey, {partner} and you probably recharge in separate rooms. Happily.","Then reunite fully charged. Efficient."],"A:B":["Friends for you. {partner} needs alone time.","You''ll want to go out. They''ll want the couch.","Invite a friend over. Let them hide in the bedroom. Peace."],"A:C":["A run for you. {partner} needs alone time.","Run solo. They rest solo. Then meet.","Best kind of together. Apart first."],"B:A":["Alone time for you. {partner} needs friends.","They''ll be out. You''ll be in. Fine.","Meet up after. Swap stories."],"B:B":["Friends for both of you. Social pack.","You and {partner} recharge with a crowd. I''d need a nap after.","But good for you. Seriously."],"B:C":["A run for you. {partner} needs friends.","Run to the party. Arrive sweaty. Iconic.","Or run in the morning, friends at night."],"C:A":["Alone time for you. {partner} goes for a run.","They run. You rest. Both recharging. Both quiet.","Close enough. Same energy."],"C:B":["Friends for you. {partner} goes for a run.","Run with friends. Everyone wins. Mostly them.","Or meet at the finish line with snacks."],"C:C":["Long runs for both of you. Respect.","So {partner} and you probably run side by side without talking.","Best kind of conversation."]}}'::jsonb),
('RU-V14','adventure_friend_ru','Preference','{"id":"RU-V14","friendId":"adventure_friend_ru","type":"Preference","scene":"Rue struggles to open a jar. She doesn''t ask for help. She keeps struggling.","lines":["I''ve got it. I''ve got it. Okay."],"question":"When you need help: ask right away, or try alone first?","selfQuestion":null,"choices":[{"id":"A","label":"Ask right away","reply":["Ask right away. Smart. Healthy.","No shame in it. ...I''m working on that."]},{"id":"B","label":"Try alone first","reply":["Try alone first. Same.","Proving I can. Every time."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Ask right away for both of you. Great.","Honestly, you and {partner} just say ''can you help?'' Easy.","Teach me. I''m still on the jar."],"A:B":["Try alone first for you. {partner} asks right away.","They''ll hand you the jar. You''ll want to do it yourself.","Let them help once. ...It''s nice. Sky taught me."],"B:A":["Ask right away for you. {partner} tries alone first.","Offer help gently. Don''t grab the jar.","Let them try. Then say ''want me to?'' Quietly."],"B:B":["Try alone first for both of you. Same.","I can picture it: {partner} and you will struggle with the jar for ten minutes. Side by side.","Just pass it over eventually. Please."]}}'::jsonb),
('RU-V15','adventure_friend_ru','Preference','{"id":"RU-V15","friendId":"adventure_friend_ru","type":"Preference","scene":"Rue unfolds a paper map, upside down, then flips it.","lines":["I know where we are. Mostly."],"question":"Lost while driving: ask for directions, or figure it out yourself?","selfQuestion":null,"choices":[{"id":"A","label":"Ask for directions","reply":["Ask for directions. Efficient.","Less time lost. More time snacking."]},{"id":"B","label":"Figure it out","reply":["Figure it out. Same.","Pride is a GPS."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Ask for directions for both of you. Smart.","Pretty sure you and {partner} will never circle the same roundabout four times.","Respect. Practical. Sky and I once drove an hour the wrong way. Proudly."],"A:B":["You figure it out. {partner} asks for directions.","They''ll pull over. You''ll sigh.","Let them ask. Arrive on time. Pride intact. Mostly."],"B:A":["You ask for directions. {partner} wants to figure it out.","They''ll say ''I know where we are.'' They don''t.","Ask quietly. Let them think it was their idea."],"B:B":["Figure it out for both of you. Stubborn duo.","Lowkey, {partner} and you will drive in circles for an hour. Together.","At least the playlist is good."]}}'::jsonb),
('RU-V16','adventure_friend_ru','Guess','{"id":"RU-V16","friendId":"adventure_friend_ru","type":"Guess","scene":"Rue narrows her eyes at you, calculating something.","lines":["I''m good. ...Stress question. I don''t get stressed. Much."],"question":"When stressed, what does your partner do?","selfQuestion":"When you''re stressed, what do you do?","choices":[{"id":"A","label":"Pulls away","reply":["Pulls away. Same.","Distance feels safe."]},{"id":"B","label":"Leans in","reply":["Leans in. Huh. Okay.","Closeness helps them."]},{"id":"C","label":"Cleans everything","reply":["Cleans everything. Scrub therapy.","Shiny counters, calm brain."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Pulling away, and {partner} knew it.","They know your silence isn''t about them.","Still. Tell them once in a while. Sky likes that."],"A:B":["You lean in. {partner} expected you to pull away.","They''re giving you space. You want closeness.","Say it. ''Stay.'' One word. Works."],"A:C":["You clean everything. {partner} expected you to pull away.","They''re giving you space. You''re scrubbing the oven.","Let them help. Or just let them watch. It''s a show."],"B:A":["You pull away. {partner} expected you to lean in.","They''re opening their arms. You''re closing the door.","Tell them it''s not about them. It''s just how you process."],"B:B":["Leaning in, and {partner} knew it.","They know you need closeness when things get heavy.","Lucky. That''s harder than it looks."],"B:C":["You clean everything. {partner} expected you to lean in.","They want a hug. You want the floors spotless.","Hug them with rubber gloves on. Compromise."],"C:A":["You pull away. {partner} expected cleaning.","They''re waiting for scrubbing sounds. You''ve gone quiet.","Say ''I need space.'' They''ll understand."],"C:B":["You lean in. {partner} expected cleaning.","They''re handing you a sponge. You want a hug.","Hug first. Clean later. Maybe never."],"C:C":["Cleaning everything, and {partner} knew it.","They know a spotless kitchen means a stressful week.","Help them scrub. Or bring snacks."]}}'::jsonb),
('RU-V17','adventure_friend_ru','Guess','{"id":"RU-V17","friendId":"adventure_friend_ru","type":"Guess","scene":"Rue folds her arms, watching you closely.","lines":["Funny question coming. Ironic, given who''s asking."],"question":"When someone asks your partner ''you okay?'', what do they say?","selfQuestion":"When someone asks you ''you okay?'', what do you say?","choices":[{"id":"A","label":"''I''m good.'' (They''re not.)","reply":["''I''m good.'' Classic. That''s me.","Everyone''s ''good.'' Nobody''s good."]},{"id":"B","label":"The honest truth","reply":["The honest truth. Brave.","Rare. Respect."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["''I''m good,'' and {partner} sees right through it.","They know ''I''m good'' means ''ask again later.''","Sky does that. Asks twice. It works. Annoyingly."],"A:B":["You''re honest. {partner} expected ''I''m good.''","They were ready to decode an ''I''m good.'' You just told them the truth.","That''s trust. It feels weird. Then it feels really good."],"B:A":["You say ''I''m good.'' {partner} thought you''d be honest.","They''re taking ''good'' at face value. Uh oh.","Say one real thing next time. Just one."],"B:B":["The honest truth, and {partner} knew it.","They know you''ll just tell them. No code.","Keep that. It''s rare. Trust me."]}}'::jsonb),
('RU-V18','adventure_friend_ru','Guess','{"id":"RU-V18","friendId":"adventure_friend_ru","type":"Guess","scene":"Rue sneezes, then glares at you like you caused it.","lines":["I''m not sick."],"question":"When your partner gets sick, how do they act?","selfQuestion":"When you get sick, how do you act?","choices":[{"id":"A","label":"''I''m fine,'' refuses all help","reply":["Refuses help. Same.","''I''m fine,'' while sneezing."]},{"id":"B","label":"Wants to be babied","reply":["Wants to be babied. Honest.","Soup. Blankets. Attention."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Refusing help, and {partner} knew it.","They''ll leave soup by the door. Silently.","That''s how you handle a lone wolf. Respect."],"A:B":["You want babying. {partner} thought you''d refuse help.","They''re giving you space. You want a blanket burrito.","Ask for soup. They''ll be thrilled."],"B:A":["You refuse help. {partner} thought you''d want babying.","They''re bringing soup. You''re pretending you''re fine.","Take the soup. Just the soup. That''s a start."],"B:B":["Wanting to be babied, and {partner} knew it.","They''ve got the soup and the blanket ready.","Let them. It''s nice. ...I think."]}}'::jsonb),
('RU-V19','adventure_friend_ru','Guess','{"id":"RU-V19","friendId":"adventure_friend_ru","type":"Guess","scene":"Rue pretends to check her nails, avoiding your eyes.","lines":["I''m good. ...Missing someone question. Ugh."],"question":"How does your partner say ''I missed you''?","selfQuestion":"How do you say ''I missed you''?","choices":[{"id":"A","label":"A long hug","reply":["A long hug. Huh. Sweet.","Arms say it. No words needed."]},{"id":"B","label":"Pretends they didn''t","reply":["Pretends they didn''t. Same.","''Oh, you were gone?''"]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["A long hug, and {partner} knew it.","They know you''ll squeeze them for a full minute.","...That''s nice. Don''t tell anyone I said that."],"A:B":["You pretend you didn''t miss them. {partner} expected a hug.","They''re waiting with open arms. You''re ''busy.''","Hug them. Just once. Then go back to pretending."],"B:A":["You hug long. {partner} thought you''d play it cool.","Surprise. Softie revealed.","They''ll love it. Hug them extra long next time."],"B:B":["Pretending you didn''t, and {partner} knew it.","They see you trying not to smile when they walk in.","You''re not fooling anyone. Sky says the same about me."]}}'::jsonb),
('RU-V20','adventure_friend_ru','Guess','{"id":"RU-V20","friendId":"adventure_friend_ru","type":"Guess","scene":"Rue fixes your wobbly chair leg without being asked, then shrugs.","lines":["Taking care of people. Not my thing. Obviously."],"question":"How does your partner take care of you?","selfQuestion":"How do you take care of your partner?","choices":[{"id":"A","label":"Fixes practical stuff","reply":["Fixes stuff. Practical love.","Squeaky door? Gone. Leaky faucet? Fixed."]},{"id":"B","label":"Shows up with food","reply":["Shows up with food. Classic.","Love is a warm meal."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Fixing things, and {partner} knew it.","They know a fixed shelf is your ''I love you.''","Same. I fix stuff for Sky. He knows what it means."],"A:B":["You bring food. {partner} thought you''d fix stuff.","They''re expecting a toolbox. You arrive with lasagna.","Better surprise, honestly. Way better."],"B:A":["You fix stuff. {partner} thought you''d bring food.","They''re waiting for soup. You''re fixing the faucet.","Tell them the faucet is a love letter. Plumbing romance."],"B:B":["Showing up with food, and {partner} knew it.","They know dinner on the doorstep means you care.","Food is love. No argument."]}}'::jsonb)
insert into public.friend_visit_characters_v2(friend_id,waiting_lines) values('adventure_friend_tb','["I’ll wait for {partner}. No rush. I’ve got all the time in the world. Literally.","Saving a seat for {partner}. I’m comfortable. Very comfortable. No rush."]'::jsonb) on conflict(friend_id) do update set waiting_lines=excluded.waiting_lines;
insert into public.friend_visit_questions_v2(id,friend_id,kind,content) values
('TB-V01','adventure_friend_tb','Trivia','{"id":"TB-V01","friendId":"adventure_friend_tb","type":"Trivia","scene":"Tobias pulls out a small photo of a very old tortoise.","lines":["He''s a hero of mine. Old friend. No rush."],"question":"Who is Jonathan the tortoise?","selfQuestion":null,"choices":[{"id":"A","label":"The oldest known living land animal","reply":["Correct. A legend.","Jonathan is a giant tortoise believed to have hatched around 1832.","He''s lived through so much. Still eats his greens."]},{"id":"B","label":"A famous racing tortoise","reply":["Racing? Oh, no. He walks.","He''s believed to be the oldest living land animal.","Hatched around 1832. Still going. No rush."]},{"id":"C","label":"A tortoise who starred in movies","reply":["Not quite. Although he''s famous.","He''s the oldest known living land animal.","Nearly two centuries old. Puts my slow pace in perspective."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Jonathan, a Seychelles giant tortoise, is the oldest known living land animal (hatched c. 1832).","coupleReplies":{}}'::jsonb),
('TB-V02','adventure_friend_tb','Trivia','{"id":"TB-V02","friendId":"adventure_friend_tb","type":"Trivia","scene":"Tobias gazes at a photo of a golden aspen forest, utterly peaceful.","lines":["That whole forest might be one tree. No rush. Let it sink in."],"question":"What''s special about Pando, a grove of aspen trees in Utah?","selfQuestion":null,"choices":[{"id":"A","label":"It''s made of fake plastic trees","reply":["Oh, no. Very real. Very old.","It''s a single organism with one shared root system.","Possibly thousands of years old. A patient giant."]},{"id":"B","label":"The trees walk around slowly","reply":["Like me? Lovely thought. No.","It''s one organism connected by a single root system.","One of the heaviest living things on Earth. Quietly."]},{"id":"C","label":"It''s one single organism sharing one root system","reply":["Correct. One giant family under the soil.","Tens of thousands of trunks all grow from the same roots.","Connected underground, like old friends. I find that very moving."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Pando is a clonal colony of quaking aspen sharing one root system.","coupleReplies":{}}'::jsonb),
('TB-V03','adventure_friend_tb','Trivia','{"id":"TB-V03","friendId":"adventure_friend_tb","type":"Trivia","scene":"Tobias gestures to a fuzzy green plant hanging from your ceiling.","lines":["Another slow friend. I admire him. No rush."],"question":"What grows on a sloth''s fur because it moves so slowly?","selfQuestion":null,"choices":[{"id":"A","label":"Flowers","reply":["How lovely. Not quite.","It''s algae, giving sloths a green tint.","Camouflage by being patient. I respect that."]},{"id":"B","label":"Moss","reply":["Close. It''s actually algae.","Algae grows in their fur and tints it green.","A whole ecosystem on one sleepy animal."]},{"id":"C","label":"Algae","reply":["Correct. A tiny garden.","Sloth fur can host algae, which gives it a greenish tint.","Helps them blend in with the trees. Slow and stylish."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Sloth fur hosts algae (and other organisms).","coupleReplies":{}}'::jsonb),
('TB-V04','adventure_friend_tb','Trivia','{"id":"TB-V04","friendId":"adventure_friend_tb","type":"Trivia","scene":"A butterfly lands on Tobias''s foot. He doesn''t move. For a very, very long time.","lines":["She''s tasting me. That''s how they taste. No rush. I''ll wait."],"question":"How do butterflies taste things?","selfQuestion":null,"choices":[{"id":"A","label":"With their wings","reply":["A pretty idea. Not quite.","They taste with sensors on their feet.","So landing is tasting. Very efficient lunch planning."]},{"id":"B","label":"With sensors on their feet","reply":["Correct. Toes for tasting.","Butterflies taste plants by standing on them.","Imagine tasting your salad by stepping in it. Marlow said no."]},{"id":"C","label":"They can''t taste at all","reply":["Oh, they can. Just differently.","Their taste sensors are on their feet.","Very curious feet. Respect."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Butterflies have taste receptors (chemoreceptors) on their feet.","coupleReplies":{}}'::jsonb),
('TB-V05','adventure_friend_tb','Trivia','{"id":"TB-V05","friendId":"adventure_friend_tb","type":"Trivia","scene":"Tobias looks at a bamboo stalk on your shelf with deep respect.","lines":["Patience is a plant, sometimes."],"question":"How often do some bamboo species flower?","selfQuestion":null,"choices":[{"id":"A","label":"Once every 100 years or more","reply":["Correct. Remarkable.","Some species flower all at the same time, decades apart.","That''s my kind of timeline."]},{"id":"B","label":"Every spring","reply":["Oh, much rarer than that.","Some bamboo species flower only once every 100 years or more.","And often all at once, across the world. Synchronized patience."]},{"id":"C","label":"Never","reply":["They do. Just very rarely.","Some bamboo flowers only once every 100+ years.","Worth waiting for. Like Marlow saying yes."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Some bamboo species (e.g., Phyllostachys bambusoides) flower at ~120-year intervals.","coupleReplies":{}}'::jsonb),
('TB-V06','adventure_friend_tb','Trivia','{"id":"TB-V06","friendId":"adventure_friend_tb","type":"Trivia","scene":"Tobias peeks into a hole in your garden, delighted.","lines":["Being a good neighbor matters. No rush."],"question":"How many other species can use a gopher tortoise''s burrow?","selfQuestion":null,"choices":[{"id":"A","label":"Just one, the tortoise","reply":["Oh, it''s much more crowded than that.","Over 350 species use gopher tortoise burrows.","Frogs, snakes, mice, owls. A whole apartment complex."]},{"id":"B","label":"Over 350","reply":["Correct. Wonderful.","Gopher tortoise burrows shelter more than 350 other species.","Generous hosts. Marlow says I''m the same with snacks."]},{"id":"C","label":"About 10","reply":["More than that. Many more.","Over 350 species have been found using them.","The best landlord in the forest. No rent."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Gopher tortoise burrows are used by 350+ other species.","coupleReplies":{}}'::jsonb),
('TB-V07','adventure_friend_tb','Trivia','{"id":"TB-V07","friendId":"adventure_friend_tb","type":"Trivia","scene":"Tobias writes ''thank you'' on a tiny note and slides it across the table, very slowly.","lines":["Marlow and I do this. Small thanks. Every day. For years."],"question":"What does research suggest about expressing gratitude to a partner?","selfQuestion":null,"choices":[{"id":"A","label":"It helps couples feel more connected and committed","reply":["Correct. Gratitude is glue.","Feeling appreciated makes both partners more invested in each other.","Small thanks. Every day. That''s the whole secret."]},{"id":"B","label":"It makes partners take you for granted","reply":["Oh, no. The opposite.","Gratitude is linked to feeling closer and more committed.","Say thank you. Slowly. Mean it."]},{"id":"C","label":"It only matters on anniversaries","reply":["Every ordinary day counts.","Regular gratitude helps couples stay connected.","Tiny thanks pile up into something big."]}],"correctOption":"A","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Algoe et al.: expressing gratitude predicts relationship maintenance and connection.","coupleReplies":{}}'::jsonb),
('TB-V08','adventure_friend_tb','Trivia','{"id":"TB-V08","friendId":"adventure_friend_tb","type":"Trivia","scene":"Tobias admires a spiky agave plant on your windowsill.","lines":["About waiting for something big. No rush."],"question":"Why is the agave sometimes called a ''century plant''?","selfQuestion":null,"choices":[{"id":"A","label":"It grows exactly 100 leaves","reply":["Clever guess. Not it.","It can take decades to bloom, then flowers once.","Not quite a century, but a very long wait."]},{"id":"B","label":"It lives for exactly 100 years","reply":["Close in spirit. Not exactly.","It blooms once after many years, then usually dies.","One big moment. Worth the wait."]},{"id":"C","label":"It takes decades to bloom, then blooms once","reply":["Correct. Beautiful.","It grows for decades, then sends up one giant flower stalk.","Patient, then spectacular. My ideal life plan."]}],"correctOption":"C","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Agave americana (''century plant'') blooms once after 10–30+ years.","coupleReplies":{}}'::jsonb),
('TB-V09','adventure_friend_tb','Trivia','{"id":"TB-V09","friendId":"adventure_friend_tb","type":"Trivia","scene":"Tobias slowly chews a slice of watermelon. Juice drips. He is unbothered.","lines":["Very refreshing. Mostly water. Like me after a bath. No rush."],"question":"About how much of a watermelon is water?","selfQuestion":null,"choices":[{"id":"A","label":"About 10%","reply":["Oh, much juicier than that.","Watermelon is about 92% water.","It''s practically a drink you can chew."]},{"id":"B","label":"About 92%","reply":["Correct. Almost all water.","That''s why it''s so refreshing on hot days.","Best eaten slowly, in the shade, with someone you love."]},{"id":"C","label":"About 50%","reply":["More. Much more.","It''s roughly 92% water.","Nature''s slow-sipping snack."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Watermelon is ~92% water.","coupleReplies":{}}'::jsonb),
('TB-V10','adventure_friend_tb','Trivia','{"id":"TB-V10","friendId":"adventure_friend_tb","type":"Trivia","scene":"Tobias watches a chicken peck around the yard with deep respect.","lines":["That''s a dinosaur. A small one. I knew it all along. Slowly."],"question":"Which living animals are actually dinosaurs?","selfQuestion":null,"choices":[{"id":"A","label":"Crocodiles","reply":["Close cousins. Not dinosaurs themselves.","The real living dinosaurs are birds.","They evolved from small, feathered dinosaurs long ago."]},{"id":"B","label":"Birds","reply":["Correct. Birds are dinosaurs.","They descend from small feathered dinosaurs.","So that chicken is a distant cousin of T. rex. Treat it with respect."]},{"id":"C","label":"Tortoises","reply":["Oh, flattering. But no.","Birds are the living dinosaurs.","I''m old. Not that old."]}],"correctOption":"B","coinsIfCorrect":10,"coinsIfWrong":5,"factBasis":"Birds are living theropod dinosaurs.","coupleReplies":{}}'::jsonb),
('TB-V11','adventure_friend_tb','Preference','{"id":"TB-V11","friendId":"adventure_friend_tb","type":"Preference","scene":"Tobias takes a very slow sip of tea.","lines":["I chased Marlow for three years. Slowly. Very slowly."],"question":"Your love story pace: slow burn, or whirlwind?","selfQuestion":null,"choices":[{"id":"A","label":"Slow burn","reply":["Slow burn. Oh, the best kind.","Warm, steady, built to last."]},{"id":"B","label":"Whirlwind","reply":["Whirlwind. Oh, my. Exciting.","Hold on to your hat."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Slow burn for both of you. No rush, indeed.","So you and {partner} took your time. And look at you now.","Savor it. Every step."],"A:B":["Whirlwind for you. {partner} says slow burn.","You were already in love. They were still saying ''let''s see.''","Patience paid off. For both of you."],"B:A":["Slow burn for you. {partner} says whirlwind.","They were spinning. You were... considering.","Funny how both of you ended up in the same place."],"B:B":["Whirlwind for both of you. Oh, my.","I can just picture it: {partner} and you said ''I love you'' in week two.","Dizzying. Wonderful. Hold hands so you don''t fall."]}}'::jsonb),
('TB-V12','adventure_friend_tb','Preference','{"id":"TB-V12","friendId":"adventure_friend_tb","type":"Preference","scene":"Tobias gazes out the window at a lazy sunrise.","lines":["Mornings are my favorite. They come every day. No rush."],"question":"Sunday morning: sleep in, or an early walk?","selfQuestion":null,"choices":[{"id":"A","label":"Sleep in","reply":["Sleep in. Wise.","Sleep is a skill. You''re a master."]},{"id":"B","label":"Early walk","reply":["Early walk. Oh, energy.","Dew on the grass. Birds saying hello."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Sleep in, both of you. Perfect.","Honestly, you and {partner} wake up when you wake up. No alarms.","Pancakes at noon. My kind of Sunday."],"A:B":["You walk early. {partner} sleeps in.","Bring them coffee when you get back. Gently wake them.","A sunrise for you. A warm cup for them."],"B:A":["You sleep in. {partner} walks early.","They''ll be back with croissants before you open your eyes.","That''s a wonderful arrangement, really."],"B:B":["Early walks, both of you. Wonderful.","Something tells me {partner} and you greet the sunrise together.","Bring warm drinks. Walk slowly. Very slowly."]}}'::jsonb),
('TB-V13','adventure_friend_tb','Preference','{"id":"TB-V13","friendId":"adventure_friend_tb","type":"Preference","scene":"Tobias opens a dusty box full of keepsakes, one item at a time.","lines":["I keep everything. Marlow''s first note. A leaf from our first walk."],"question":"Favorite keepsake: old photos, old letters, or a playlist of ''our songs''?","selfQuestion":null,"choices":[{"id":"A","label":"Old photos","reply":["Old photos. Time in a frame.","Faces and moments, kept still."]},{"id":"B","label":"Old letters","reply":["Old letters. Ink and heart.","Words that waited to be reread."]},{"id":"C","label":"A playlist of ''our songs''","reply":["A playlist. Melodies remember.","One song, one memory."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Photos for both of you. Lovely.","Make an album with {partner}. One page a year.","Fill it slowly. No rush."],"A:B":["Letters for you. {partner} loves photos.","Tuck one small photo inside every letter you write them.","A keepsake inside a keepsake. Very efficient sentiment."],"A:C":["Playlist for you. {partner} loves photos.","Put on your songs and flip through the albums together.","A soundtrack for every memory. Take your time. Every page."],"B:A":["Photos for you. {partner} treasures letters.","Write a little caption on the back of each photo. Now it''s both.","Marlow does this. Her captions are funnier than the photos."],"B:B":["Letters for both of you. Beautiful.","You and {partner} probably have a ribbon-tied stack somewhere.","Write a new one. Add it to the pile."],"B:C":["Playlist for you. {partner} keeps the letters.","Read their letters out loud while your songs play softly.","That''s a perfect evening. Slow. Warm. No rush at all."],"C:A":["Photos for you. {partner} keeps the playlist.","Make a slideshow and set it to ''your songs.''","Watch it on a rainy evening. Bring tissues. Several."],"C:B":["Letters for you. {partner} loves a playlist.","Handwrite the one lyric that always reminds you of them.","They''ll hear that song differently forever. That''s the plan."],"C:C":["Playlists for both of you. Musical hearts.","So {partner} and you probably have a song for every season.","Play it on a long drive. Hold hands."]}}'::jsonb),
('TB-V14','adventure_friend_tb','Preference','{"id":"TB-V14","friendId":"adventure_friend_tb","type":"Preference","scene":"Tobias turns a small wrapped gift over and over, slowly.","lines":["Gifts. I take weeks to choose them. Marlow says it''s worth it. No rush."],"question":"Gifts: something useful, or something sentimental?","selfQuestion":null,"choices":[{"id":"A","label":"Something useful","reply":["Useful. Practical love.","A gift you''ll use every day."]},{"id":"B","label":"Something sentimental","reply":["Sentimental. Oh, tender.","A gift you''ll keep forever."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Useful gifts for both of you. Practical hearts.","{partner} gives you a good umbrella. You give them warm socks.","Love you can use."],"A:B":["Sentimental for you. {partner} likes useful.","Engrave something they''ll use every single day.","A mug with your words on it. They''ll think of you every sip."],"B:A":["Useful for you. {partner} loves sentimental.","Give them something practical and tuck a handwritten note inside.","An umbrella that says ''I''ll keep you dry.'' Practical poetry."],"B:B":["Sentimental gifts for both of you.","I can just picture it: you and {partner} have a drawer full of meaningful little things.","Keep every one. Even the tiny ones."]}}'::jsonb),
('TB-V15','adventure_friend_tb','Preference','{"id":"TB-V15","friendId":"adventure_friend_tb","type":"Preference","scene":"Tobias pours two cups of tea and sets one across from him.","lines":["Small rituals are big things. No rush."],"question":"A ritual you''d keep forever: morning coffee together, or an evening walk?","selfQuestion":null,"choices":[{"id":"A","label":"Morning coffee together","reply":["Morning coffee. Lovely start.","Two cups. One conversation."]},{"id":"B","label":"An evening walk","reply":["Evening walk. Lovely end.","Streetlights, quiet talks, slow steps."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Morning coffee for both of you.","Every day starts with {partner} across the table.","Forty years from now, same cups. Same love."],"A:B":["Evening walk for you. {partner} wants morning coffee.","Start with coffee. End with a walk.","A whole day held between two little rituals."],"B:A":["Morning coffee for you. {partner} wants evening walks.","Coffee at dawn. Walk at dusk. Bookends of the day.","Two rituals. Twice the love."],"B:B":["Evening walks for both of you.","Honestly, {partner} and you will know every tree in the neighborhood.","Slow steps. Long talks. Perfect."]}}'::jsonb),
('TB-V16','adventure_friend_tb','Guess','{"id":"TB-V16","friendId":"adventure_friend_tb","type":"Guess","scene":"Tobias ponders slowly, tapping two claws together.","lines":["I took three years to ask Marlow out. I''m still deciding if that was too fast."],"question":"How does your partner make big decisions?","selfQuestion":"How do you make big decisions?","choices":[{"id":"A","label":"Quickly, on instinct","reply":["Quickly, on instinct. Remarkable.","I once took a week to pick a lettuce."]},{"id":"B","label":"Takes a week","reply":["Takes a week. A kindred spirit.","Time is the best advisor. And it''s free."]},{"id":"C","label":"Asks everyone they know","reply":["Asks everyone. Very democratic.","The group chat votes. The heart decides."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Quick on instinct, and {partner} knew it.","They know you decide before they''ve finished asking the question.","I find that thrilling. From a safe distance."],"A:B":["You take a week. {partner} guessed instant instinct.","They''re tapping their foot on day two. You''re on day two of seven.","Tell them ''no rush'' in advance. It''s my favorite phrase."],"A:C":["You ask everyone. {partner} thought you''d just go with your gut.","They don''t know about the five friends you texted.","Add them to the poll. First. Before your aunt."],"B:A":["You decide fast. {partner} guessed you''d take a week.","They''re patiently waiting while you''ve already bought the thing.","Tell them gently. They were preparing to be patient."],"B:B":["A full week, and {partner} knew it.","They''ve learned to ask on Monday and expect an answer next Monday.","That''s not slowness. That''s craftsmanship."],"B:C":["You ask everyone. {partner} thought you''d quietly mull it over.","They imagine you thinking alone. You''re in four group chats.","Next time, ask them first. Their vote should count double."],"C:A":["You decide fast. {partner} guessed you''d poll everyone.","They''re expecting a group chat survey. You just... chose.","Bold. Very un-tortoise. I respect it from afar."],"C:B":["You take a week. {partner} guessed you''d ask everyone.","They think you''re consulting friends. You''re consulting the ceiling.","Quiet thinking is still thinking. Marlow taught me to say it out loud."],"C:C":["Polling everyone, and {partner} knew it.","They know your group chat has opinions on your couch, your haircut, and them.","Wise. Many voices. Just make sure theirs counts double."]}}'::jsonb),
('TB-V17','adventure_friend_tb','Guess','{"id":"TB-V17","friendId":"adventure_friend_tb","type":"Guess","scene":"Tobias settles into an imaginary line, perfectly content. He could stay here for years.","lines":["Waiting is an art form. I''m a master. Ask anyone. Slowly."],"question":"While waiting in a long line, what does your partner do?","selfQuestion":"While waiting in a long line, what do you do?","choices":[{"id":"A","label":"Chats with strangers","reply":["Chats with strangers. A friend-maker.","By the front of the line, they''re invited to a wedding."]},{"id":"B","label":"People-watches quietly","reply":["People-watches quietly. A fine pastime.","Every line is a small theater."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Chatting with strangers, and {partner} knew it.","They know you''ll know the life story of the person ahead by the time you order.","Charming. Exhausting to watch. But charming."],"A:B":["You people-watch. {partner} expected you to chat everyone up.","They''re waiting for small talk. You''re silently narrating a documentary.","Whisper your theories to them. Best line date ever."],"B:A":["You chat. {partner} expected you to quietly people-watch.","Plot twist: you''re the social one. They''ve misjudged you for years.","Introduce them to your new line friends. All of them."],"B:B":["People-watching, and {partner} knew it.","They know you''re inventing quiet backstories for everyone in line.","''He''s a retired pirate.'' Yes. Same hobby. Welcome."]}}'::jsonb),
('TB-V18','adventure_friend_tb','Guess','{"id":"TB-V18","friendId":"adventure_friend_tb","type":"Guess","scene":"Tobias lights a small candle. It takes him a while. He''s proud when it works.","lines":["Romance lives in the small things. Most things do."],"question":"What would your partner call the most romantic gesture?","selfQuestion":"What would you call the most romantic gesture?","choices":[{"id":"A","label":"A handwritten note","reply":["A handwritten note. Ink and heart.","Something they can keep in a drawer forever."]},{"id":"B","label":"Remembering a tiny detail","reply":["Remembering a tiny detail. Oh, yes.","How they take their tea. Which side they sleep on."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["A handwritten note, and {partner} knew it.","They know paper and ink mean everything to you.","Write them one tonight. Slowly. Mean every word."],"A:B":["Details move you. {partner} guessed a handwritten note.","They''re writing paragraphs. You just want them to remember your favorite mug.","Tell them one detail you love that they remember. They''ll glow."],"B:A":["A note moves you. {partner} guessed tiny details.","They''ve been memorizing your coffee order. You''ve wanted a letter.","Ask for one. Or write them a note about the details. Combo."],"B:B":["Tiny details, and {partner} knew it.","They know you melt when they remember the little things.","Marlow remembers I like my lettuce slightly wilted. I nearly proposed."]}}'::jsonb),
('TB-V19','adventure_friend_tb','Guess','{"id":"TB-V19","friendId":"adventure_friend_tb","type":"Guess","scene":"Tobias chuckles softly, remembering something from long ago. Possibly last week.","lines":["It took me a long time to realize I liked Marlow. About a year. Then two more to say it."],"question":"How long did it take your partner to realize they liked you?","selfQuestion":"How long did it take you to realize you liked your partner?","choices":[{"id":"A","label":"Right away","reply":["Right away. Oh, how lovely.","One look and they were done for."]},{"id":"B","label":"Embarrassingly long","reply":["Embarrassingly long. Oh, my people.","The heart knew. The brain needed a memo."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Right away, and {partner} knew it.","They knew you were smitten from the very first hello.","Lovely. Simple. Some hearts just know. Mine needed a calendar."],"A:B":["It took you ages. {partner} thought it was instant.","They thought you fell immediately. You were still... processing.","No rush. You got there. That''s what matters."],"B:A":["You knew right away. {partner} thought it took you ages.","They think they had to win you over. You were already won.","Tell them. They''ll smile for a week. Maybe two."],"B:B":["Embarrassingly long, and {partner} knew it.","They watched you slowly figure it out. Patiently. Possibly with popcorn.","Worth the wait. Slow-cooked love tastes best."]}}'::jsonb),
('TB-V20','adventure_friend_tb','Guess','{"id":"TB-V20","friendId":"adventure_friend_tb","type":"Guess","scene":"Tobias watches the sun rise through your curtains. He has been watching since 4 a.m.","lines":["Mornings. My favorite. They come every day, and I''m grateful every time."],"question":"How does your partner start a slow morning?","selfQuestion":"How do you start a slow morning?","choices":[{"id":"A","label":"Up with the sun","reply":["Up with the sun. A fellow early riser.","Birds and them, the first ones awake."]},{"id":"B","label":"Snoozes five times","reply":["Snoozes five times. Very human.","Five more minutes, times five."]}],"correctOption":null,"coinsIfCorrect":10,"coinsIfWrong":10,"factBasis":null,"coupleReplies":{"A:A":["Up with the sun, and {partner} knew it.","They know you''re greeting the day while they''re still dreaming.","Make them tea. Leave it by the bed. Quietly."],"A:B":["You snooze. {partner} guessed you''d be up with the sun.","They imagined a sunrise person. They got a pillow person.","Snooze one less time this week. A small gift for them."],"B:A":["Up with the sun for you. {partner} guessed snoozing.","They think you''re asleep. You''ve been up for hours, watering plants.","Bring them breakfast. Prove it."],"B:B":["Five snoozes, and {partner} knew it.","They know the alarm is more of a suggestion to you.","Sleep is precious. Snooze with dignity. No rush."]}}'::jsonb)
